NAME = 'FinSTLK2017: Pyhä Raamattu (STLK 2017)'
BOOK = 'Isaiah'

CHAPTERS = {
    1: {
        1: 'Jesajan, Aamosin pojan, näky, jonka hän näki Juudasta ja Jerusalemista Juudan kuningasten Ussian, Jootamin, Aahaan ja Hiskian päivinä.',
        2: 'Kuulkaa, taivaat, ota korviisi, maa, sillä Herra puhuu: Minä kasvatin lapset suuriksi, mutta he luopuivat minusta.',
        3: 'Härkä tuntee omistajansa ja aasi isäntänsä seimen, mutta Israel ei tunne, kansani ei ymmärrä.',
        4: 'Voi syntistä kansaa, raskaasti rikkonutta kansakuntaa, pahantekijöiden siementä, kelvottomia lapsia! He ovat hylänneet Herran, pitäneet Israelin Pyhää pilkkanaan, he ovat kääntyneet takaisin luopumukseensa.',
        5: 'Mihin teitä pitäisi vielä lyödä, kun yhä jatkatte luopumustanne? Koko pää on kipeä, koko sydän sairas.',
        6: 'Kantapäästä kiireeseen ei ole tervettä paikkaa, ainoastaan haavoja, mustelmia ja vereksiä lyömiä, joita ei ole puserrettu, ei sidottu eikä öljyllä pehmitetty.',
        7: 'Maanne on autiona, kaupunkinne ovat tulella poltetut. Peltojanne syövät muukalaiset silmienne edessä. Ne ovat autioina muukalaisten hävittäminä.',
        8: 'Jäljelle on jäänyt tytär Siion yksinään kuin maja viinitarhassa, kuin lehvämaja kurkkumaassa, kuin saarrettu kaupunki.',
        9: 'Ellei Herra Sebaot olisi jättänyt meistä jäännöstä, meidän olisi käynyt lyhyessä ajassa kuin Sodoman, olisimme tulleet Gomorran kaltaisiksi.',
        10: 'Kuulkaa Herran sana, te Sodoman päämiehet, ota korviisi Jumalamme opetus, sinä Gomorran kansa.',
        11: 'Mitä ovat minulle teidän paljot teurasuhrinne? sanoo Herra. Olen kyllästynyt pässipolttouhreihin ja juottovasikkojen rasvaan. Mullien, karitsojen ja kauristen vereen en mielly.',
        12: 'Kuka teitä vaatii tulemaan kasvojeni eteen tallaamaan esikartanoitani?',
        13: 'Älkää enää tuoko minulle turhaa ruokauhria. Suitsutus on minulle kauhistus. En kärsi uudenkuun juhlaa enkä sapattia, en kokouksen kuuluttamista, en vääryyttä enkä juhlakokousta.',
        14: 'Sieluni vihaa uusiakuitanne ja juhla-aikojanne. Ne ovat käyneet minulle kuormaksi, jota olen väsynyt kantamaan.',
        15: 'Kun te ojentelette käsiänne, minä peitän silmäni teiltä. Vaikka kuinka paljon rukoilisitte, en kuule. Kätenne ovat verta täynnä.',
        16: 'Peseytykää, puhdistautukaa. Pankaa pois pahat tekonne silmieni edestä, lakatkaa tekemästä pahaa.',
        17: 'Oppikaa tekemään hyvää. Toimikaa oikeuden mukaan, ojentakaa väkivaltaista, hankkikaa orvolle oikeus, ajakaa lesken asia.',
        18: 'Tulkaa, käykäämme oikeutta keskenämme, sanoo Herra. Vaikka syntinne ovat veriruskeat, ne tulevat lumivalkeiksi. Vaikka ne ovat purppuranpunaiset, ne tulevat villanvalkoisiksi.',
        19: 'Jos suostutte ja olette kuuliaisia, tulette syömään maan hyvyyttä.',
        20: 'Mutta jos vastustatte ja niskoittelette, miekka syö teidät. Sillä Herran suu on puhunut.',
        21: 'Voi, kuinka onkaan portoksi tullut uskollinen kaupunki! Se oli täynnä oikeutta, siellä asui vanhurskaus, mutta nyt murhamiehet.',
        22: 'Hopeasi on muuttunut kuonaksi, jaloviinisi on vedellä laimennettua.',
        23: 'Johtajasi ovat niskureita ja varkaiden tovereita. He kaikki rakastavat lahjuksia ja tavoittelevat palkkioita. He eivät hanki orvolle oikeutta, lesken asia ei pääse heidän eteensä.',
        24: 'Sen tähden sanoo Herra, Herra Sebaot, Israelin Väkevä: Voi! Minä hankin lohdutuksen vastustajistani ja kostan vihollisilleni.',
        25: 'Käännän käteni sinua vastaan ja puhdistan sinusta kuonan kuin lipeällä ja poistan sinusta kaiken lyijyn.',
        26: 'Palautan tuomarisi entiselleen ja neuvonantajasi sellaisiksi, kuin he olivat alkuaan. Sitten sinua kutsutaan "vanhurskauden linnaksi" ja "uskolliseksi kaupungiksi."',
        27: 'Siion lunastetaan oikeudella ja sen kääntyneet vanhurskaudella.',
        28: 'Mutta luopiot ja syntiset sortuvat kaikki yhdessä, ja ne, jotka hylkäävät Herran, hukkuvat.',
        29: 'Sillä he saavat häpeän niistä tammista, joita te himoitsitte, ja pettymyksen puutarhoista, jotka te valitsitte.',
        30: 'Sillä teidän käy kuin tammen, jonka lehdet lakastuvat, ja kuin puutarhan, joka on vettä vailla.',
        31: 'Niin taitaja tulee rohtimeksi ja hänen tekonsa kipinäksi, ja molemmat palavat yhdessä, eikä sammuttajaa ole.',
    },
    2: {
        1: 'Sana, jonka Jesaja, Aamosin poika, näki Juudasta ja Jerusalemista.',
        2: 'On oleva aikojen lopulla: Herran temppelin vuori on oleva vahva, kaikkia muita vuoria ylempänä, kukkuloista korkeimpana, ja kaikista pakanakansoista vaeltaa virtanaan sinne väkeä.',
        3: 'Monet kansakunnat vaeltavat sinne ja sanovat: Tulkaa mukaan ja nouskaamme Herran vuorelle, Jaakobin Jumalan temppeliin, niin hän opettaa meille tiensä ja me vaellamme hänen polkujaan, sillä Siionista lähtee laki ja Jerusalemista Herran sana.',
        4: 'Hän tuomitsee pakanoiden kesken ja myöntää oikeuden monille kansakunnille. Silloin he takovat miekkansa aurankärjiksi ja keihäänsä viinivesoimiksi eikä kansa nosta miekkaa toistaan vastaan eivätkä he enää opettele käymään sotia.',
        5: 'Jaakobin heimo, lähtekää mukaan! Vaeltakaamme Herran valkeudessa.',
        6: 'Sillä sinä olet hylännyt kansasi, Jaakobin heimon, koska he ovat täynnä idän menoa, täynnä noitia filistealaisten tapaan ja he ovat liittoutuneet muukalaisten kanssa.',
        7: 'Hänen maansa on täynnä kultaa ja hopeaa eikä hänen aarteillaan ole loppua. Hänen maansa on täynnä oriita eikä hänen vaunuillaan ole loppua.',
        8: 'Hänen maansa on täynnä epäjumalia, ja he kumartavat kättensä tekoja, omien sormiensa luomuksia.',
        9: 'Mutta ihminen nöyryytetään ja miehen uhma masennetaan, etkä sinä anna heille anteeksi.',
        10: 'Astu kallion sisään ja kätkeydy tomuun Herran kasvojen kauhulta ja hänen Majesteettinsa kirkkaudelta.',
        11: 'Ihmisten kopeat silmät kokevat nöyryytyksen ja ihmisten mahtavuus painetaan alas, ja Herra yksin on korkea sinä päivänä.',
        12: 'Sillä päivä on Herran Sebaotin, ja se on kaikkea ylvästelyä ja mahtavuutta vastaan ja kaikkea itsekorotusta vastaan, niin että se menee matalaksi,',
        13: 'ja kaikkia korkeita ja pitkiä Libanonin setrejä vastaan ja kaikkia Baasanin tammia vastaan',
        14: 'ja kaikkia korkeita vuoria ja ylhäisiä kukkuloita vastaan',
        15: 'ja kaikkia korkeita torneja ja kaikkia lujia muureja vastaan',
        16: 'ja kaikkia Tarsiin laivoja ja kaikkea sitä vastaan, mitä mielitellen katsellaan.',
        17: 'Ihmisten kopeus masentuu ja heidän mahtavuutensa painuu alas. Herra yksin on korkea sinä päivänä,',
        18: 'mutta epäjumalat katoavat kaikki tyynni.',
        19: 'He menevät vuorten onkaloihin ja maaluoliin Herran kauhua ja hänen Majesteettinsa kirkkautta pakoon, kun hän nousee saattamaan maan kauhun valtaan.',
        20: 'Sinä päivänä ihmiset heittävät myyrille ja lepakoille hopea- ja kultajumalansa, joita he olivat tehneet rukoiltavikseen',
        21: 'mennäkseen vuorten onkaloihin ja kallioluoliin Herran kauhua ja hänen Majesteettinsa kirkkautta pakoon, kun hän nousee saattamaan maan kauhun valtaan.',
        22: 'Luopukaa siis ihmisistä, jotka ovat henkäys sieraimessa, sillä sellaisiksi heidät on arvioitu.',
    },
    3: {
        1: 'Sillä katso, Herra, Herra Sebaot ottaa pois Jerusalemilta ja Juudalta tuen ja turvan, kaikki leipävarastot ja kaikki vesivarastot,',
        2: 'sankarin ja soturin, tuomarin ja profeetan, tietäjän ja vanhimman,',
        3: 'viidenkymmenenpäällikön ja arvossapidetyn, neuvonantajan, tietomiehen ja taikurin.',
        4: 'Annan nuorukaiset heille johtajiksi, ja poikaset hallitsevat heitä.',
        5: 'Kansassa toinen sortaa toistaan, jokainen lähimmäistään. Nuorukainen rehentelee vanhusta vastaan, alhainen kunnioitettavaa vastaan.',
        6: 'Kun veli tarttuu veljeensä isänsä talossa sanoen: "Sinulla on vielä vaatteet, ryhdy ruhtinaaksemme ja ota huostaasi tämä raunioläjä",',
        7: 'niin tämä sinä päivänä korottaa äänensä sanoen: "Ei minusta ole haavoja sitomaan. Talossani ei ole leipää, ei vaatetta, älkää panko minua kansan ruhtinaaksi."',
        8: 'Sillä Jerusalem kaatuu ja Juuda kukistuu, koska heidän kielensä ja heidän tekonsa ovat Herraa vastaan ja he uhittelevat hänen kunniansa kasvoja.',
        9: 'Heidän kasvojensa hahmo todistaa heitä vastaan; syntinsä he tuovat julki kuin sodomalaiset eivätkä niitä salaa. Voi heitä! Itselleen he pahaa tekevät.',
        10: 'Sanokaa hurskaasta, että hänen käy hyvin, sillä he saavat nauttia tekojensa hedelmiä.',
        11: 'Voi jumalatonta! Hänen käy pahoin, sillä hänen kättensä teot kostetaan hänelle.',
        12: 'Kansani käskijät ovat lapsia, ja naiset sitä hallitsevat. Kansani, autuuttajasi ovat eksyttäjiä. He ovat häivyttäneet sinun polkujesi suunnan.',
        13: 'Herra asettuu käymään oikeutta, nousee tuomitsemaan kansoja.',
        14: 'Herra käy tuomiolle kansansa vanhinten ja sen johtajien kanssa: "Te olette raiskanneet viinitarhan. Teidän taloissanne on köyhiltä ryöstettyä tavaraa.',
        15: 'Kuinka saatatte runnella kansaani ja ruhjoa köyhien kasvot?" sanoo Herra, Herra Sebaot.',
        16: 'Herra sanoi: Koska Siionin tyttäret ylpeilevät, kulkevat kaula kenossa ja silmillään vilkuillen, astua sipsuttelevat ja nilkkarenkaitaan kilistelevät,',
        17: 'tekee Herra Siionin tyttärien päälaen rupiseksi, ja Herra paljastaa heidän häpynsä.',
        18: 'Sinä päivänä Herra poistaa koreat nilkkarenkaat, otsanauhat, puolikuukorut,',
        19: 'korvarenkaat, rannerenkaat, hunnut,',
        20: 'juhlapäähineet, jalkaketjut, koruvyöt, hajupullot, taikahelyt,',
        21: 'sormukset, nenärenkaat,',
        22: 'juhlavaatteet, kaavut, viitat, kukkarot,',
        23: 'kuparipeilit, pellavapaidat, turbaanit ja päällysharsot.',
        24: 'Tuoksun sijaan tulee löyhkä, vyön sijaan nuora, käherretyn tukan sijaan kaljuus, korupuvun sijaan säkkiverho, kauneuden sijaan polttomerkki.',
        25: 'Miehesi kaatuvat miekkaan ja sankarisi sotaan.',
        26: 'Siionin portit valittavat ja vaikeroivat, ja hän [Siion] istuu tyhjäksi tehtynä maassa.',
    },
    4: {
        1: 'Sinä päivänä seitsemän naista tarttuu yhteen mieheen sanoen: "Me syömme omaa leipäämme ja vaatetamme itsemme omilla vaatteilla, kunhan vain meidät otetaan sinun nimiisi. Poista häpeämme."',
        2: 'Sinä päivänä Herran Vesa on oleva Israelin pelastuneille kaunistus ja kunnia ja maan hedelmä heille korkeus ja loisto.',
        3: 'Silloin niitä, jotka Siionissa ovat säilyneet ja Jerusalemista jäljelle jääneet, sanotaan pyhiksi, kaikkia, jotka ovat kirjoitetut Jerusalemissa elävien lukuun –',
        4: 'silloin kun Herra on pessyt pois Siionin tyttärien saastan ja huuhtonut Jerusalemista sen verenviat tuomion ja puhdistuksen Hengellä.',
        5: 'Silloin Herra luo Siionin vuorelle koko asuinsijansa ylle ja sen juhlakokousten ylle pilven päivän ajaksi ja savun sekä tulenliekin hohteen yöksi, sillä kaiken kirkkauden yllä on oleva peite',
        6: 'ja verho varjoamassa päivän helteeltä sekä turvana ja suojana rajuilmalta ja sateelta.',
    },
    5: {
        1: 'Minä laulan ystävästäni, rakkaani laulun hänen viinitarhastaan. Ystävälläni oli viinitarha lihavalla vuorenrinteellä.',
        2: 'Hän kuokki ja kivesi sen ja istutti siihen jaloja köynnöksiä, rakensi sen keskelle tornin ja hakkasi sinne myös kuurnan. Niin hän odotti sen kasvavan rypäleitä, mutta se kasvoi villimarjoja.',
        3: 'Mutta nyt, te Jerusalemin asukkaat ja Juudan miehet, tuomitkaa minun ja viinitarhani välillä.',
        4: 'Mitä viinitarhalleni olisi vielä ollut tehtävä, jota en olisi sille tehnyt? Miksi se kasvoi villimarjoja, kun odotin sen kasvavan rypäleitä?',
        5: 'Niin nyt ilmoitan teille, mitä teen viinitarhalleni: poistan siitä aidan, että se jää hävitettäväksi, särjen siitä muurin, että se jää tallattavaksi.',
        6: 'Hävitän sen: sitä ei enää vesota eikä kuokita, vaan se on kasvava ohdaketta ja orjantappuraa, ja kiellän pilvet sille vettä satamasta.',
        7: 'Sillä Israelin heimo on ollut Herran Sebaotin viinitarha, ja Juudan miehet hänen istutuksensa, josta hän iloitsi. Niinpä hän odotti oikeutta, mutta katso, tuli oikeudettomuus, ja vanhurskautta, mutta katso, tuli vaikerrus.',
        8: 'Voi niitä, jotka liittävät talon taloon, yhdistävät pellon peltoon, kunnes ei jää enää tilaa ja te yksin asutte maassa!',
        9: 'Minun korviini kuului Herran Sebaotin sana: Totisesti, monet talot tulevat autioiksi, suuret ja kauniit asumattomiksi.',
        10: 'Sillä kymmenen auranalaa viinitarhaa on antava yhden bat-mitan, ja hoomerin kylvö on antava eefan.',
        11: 'Voi niitä, jotka juoksevat aamuvarhaisesta väkijuoman perässä ja viipyvät iltamyöhään viinistä hehkuvina!',
        12: 'Lyyrat, harput, tamburiinit, huilut ja viinit heillä on pidoissaan, mutta Herran tekoja he eivät tutki, eivät näe hänen kättensä töitä.',
        13: 'Sen tähden kansani siirretään maastaan äkkiarvaamatta, sen ylhäiset kärsivät nälkää, ja sen remuava joukko nääntyy janoon.',
        14: 'Sen tähden helvetti levittää kitansa ammolleen, avaa suunsa suunnattomaksi. Sinne menee sen loisto, sen remuava ja pauhaava joukko, kaikki sen ilonpitäjät.',
        15: 'Ihminen masentuu ja mies painuu maahan, maahan painuvat ylpeitten silmät.',
        16: 'Mutta Herra Sebaot on oleva korkea tuomiossa, pyhä Jumala on oleva pyhä vanhurskaudessa',
        17: 'Karitsat käyvät siellä kuin laitumillaan, ja vieraat syöttävät rikkaitten rauniosijoja.',
        18: 'Voi niitä, jotka vetävät perässään rangaistusta turhuuden köysillä, synnin palkkaa kuin vaunujen valjailla.',
        19: 'Voi niitä, jotka sanovat: "Tulkoon joutuin hänen tekonsa, että sen näemme. Täyttyköön ja tapahtukoon Israelin Pyhän suunnitelma, että sen tiedämme"!',
        20: 'Voi niitä, jotka sanovat pahan hyväksi ja hyvän pahaksi, jotka tekevät pimeyden valkeudeksi ja valkeuden pimeydeksi, jotka tekevät karvaan makeaksi ja makean karvaaksi!',
        21: 'Voi niitä, jotka ovat viisaita omissa silmissään ja ymmärtäväisiä omasta mielestään!',
        22: 'Voi niitä, jotka ovat sankareita viinin juonnissa ja voiman miehiä väkijuoman sekoittamisessa,',
        23: 'jotka lahjuksesta julistavat syyllisen syyttömäksi ja ottavat oikeuden siltä, joka on oikeassa!',
        24: 'Sen tähden, niin kuin tulen kieli syö oljet ja kuloheinä raukeaa liekkiin, niin heidän juurensa mätänee, ja heidän kukkansa hajoaa tomuna ilmaan, sillä he ovat ylenkatsoneet Herran Sebaotin lain ja pitäneet pilkkanaan Israelin Pyhän sanan.',
        25: 'Sen tähden Herran viha syttyi hänen kansaansa kohtaan: hän ojensi kätensä sitä vastaan ja löi sitä, niin että vuoret vapisivat ja heidän raatonsa olivat tunkiona keskellä katuja. Tästä kaikesta hänen vihansa ei asettunut, vaan hänen kätensä on vielä ojennettuna.',
        26: 'Niinpä hän pystyttää viirin kaukaiselle kansalle ja viheltää sen luokseen maan äärestä. Katso, se tulee viipymättä, nopeasti.',
        27: 'Kukaan heistä ei väsy eikä kompastu, ei kukaan torku eikä nuku, ei vyö aukene vyötäisiltä, eikä sandaalin nyöri katkea.',
        28: 'Sen nuolet ovat teroitetut, sen jouset kaikki jännitetyt, sen oriiden kaviot ovat kuin pii, ja sen rattaat kuin rajuilma.',
        29: 'Sen karjunta on kuin naarasleijonan, se karjuu kuin nuoret leijonat, se ärjyy ja tempaa saaliin ja vie sen pois, eikä pelastajaa ole.',
        30: 'Se ärjyy sille sinä päivänä, niin kuin meri ärjyy. Silloin tähyillään maata, mutta katso, on pimeys, on ahdistus, ja valo on pimentynyt sen pilvissä.',
    },
    6: {
        1: 'Kuningas Ussian kuolinvuotena minä näin Herran istuvan korkealla ja ylhäisellä istuimella, ja hänen vaatteensa liepeet täyttivät temppelin.',
        2: 'Serafit seisoivat hänen ympärillään; kullakin oli kuusi siipeä: kahdella he peittivät kasvonsa, kahdella he peittivät jalkansa, ja kahdella he lensivät.',
        3: 'He huusivat toisilleen ja sanoivat: "Pyhä, pyhä, pyhä Herra Sebaot. Kaikki maa on täynnä hänen kunniaansa."',
        4: 'Kynnysten perustukset vapisivat heidän huutonsa äänestä, ja huone täyttyi savulla.',
        5: 'Sanoin: "Voi minua, sillä hukun, sillä minulla on saastaiset huulet, ja asun kansan keskellä, jolla on saastaiset huulet; sillä silmäni ovat nähneet kuninkaan, Herran Sebaotin."',
        6: 'Yksi serafeista lensi luokseni kädessään hehkuva kivi, jonka hän oli ottanut pihdeillä alttarilta,',
        7: 'ja kosketti sillä suutani sanoen: "Katso, tämä on koskettanut huuliasi; niin on velkasi poistettu ja syntisi sovitettu."',
        8: 'Kuulin Herran äänen sanovan: "Kenet lähetän? Kuka lähtee puolestamme?" Minä sanoin: "Katso, tässä olen, lähetä minut."',
        9: 'Hän sanoi: "Mene ja sano tälle kansalle: \'Kuulemalla kuulkaa, älkääkä ymmärtäkö, näkemällä nähkää, älkääkä käsittäkö.\'',
        10: 'Paaduta tämän kansan sydän, koveta sen korvat, sokaise sen silmät, ettei se näkisi silmillään, ei kuulisi korvillaan, ei ymmärtäisi sydämellään eikä kääntyisi ja tulisi parannetuksi."',
        11: 'Silloin sanoin: "Kuinka kauaksi aikaa, Herra?" Hän vastasi: "Siihen asti, kunnes kaupungit tulevat autioiksi, asumattomiksi, ja talot tyhjiksi ihmisistä ja pellot on hävitetty erämaaksi,',
        12: 'kunnes Herra on karkottanut ihmiset kauas ja suuri autius on tullut keskelle maata.',
        13: 'Jos siellä on jäljellä kymmenesosa, hävitetään vielä sekin. Mutta niin kuin terebintistä ja tammesta jää kaadettaessa kanto, niin siitäkin: se kanto on pyhä siemen."',
    },
    7: {
        1: 'Aahaan, Jootamin pojan, Ussian pojanpojan, Juudan kuninkaan, aikana lähtivät Resin, Aramin kuningas, ja Pekah, Remaljan poika, Israelin kuningas, sotimaan Jerusalemia vastaan, mutta eivät voineet valloittaa sitä.',
        2: 'Kun Daavidin huoneelle ilmoitettiin sanoma: "Aram on leiriytynyt Efraimiin", kuninkaan ja hänen kansansa sydän vapisi, niin kuin metsän puut vapisevat tuulessa.',
        3: 'Herra sanoi Jesajalle: "Mene Aahasta vastaan, sinä ja poikasi Sear-Jaasub, Ylälammikon vesijohdon päähän, Vanuttajankedon tielle,',
        4: 'ja sano hänelle: Ole valpas ja pysy rauhallisena, älä pelkää, älköönkä sydämesi säikkykö noita kahta savuavaa kekäleenpätkää: Resinin ja Aramin sekä Remaljan pojan vihan vimmaa.',
        5: 'Koska Aram, Efraim ja Remaljan poika ovat hankkineet pahaa sinua vastaan sanoen:',
        6: "'Lähtekäämme Juudaa vastaan, täyttäkäämme se kauhulla, vallatkaamme se itsellemme ja asettakaamme sinne kuninkaaksi Taabalin poika',",
        7: 'Herra, Herra sanoo näin: Se ei onnistu eikä tapahdu.',
        8: 'Sillä Aramin pää on Damasko, ja Damaskon pää on Resin – mutta kuusikymmentä viisi vuotta vielä, ja Efraim muserretaan eikä se ole enää kansakunta – ja Efraimin pää on Samaria,',
        9: 'ja Samarian pää on Remaljan poika. Ellette usko, ette kestä."',
        10: 'Sitten Herra puhui jälleen Aahaalle sanoen:',
        11: '"Pyydä itsellesi merkki Herralta, Jumalaltasi, pyydä alhaalta syvyydestä tai ylhäältä korkeudesta."',
        12: 'Mutta Aahas vastasi: "En pyydä enkä kiusaa Herraa."',
        13: 'Hän lausui: "Kuulkaa, te Daavidin suku, eikö riitä, että te ihmiset väsytätte, kun väsytätte vielä minun Jumalanikin itseenne?',
        14: 'Sen tähden Herra itse antaa teille merkin: Katso, neitsyt on raskaana ja synnyttää pojan ja antaa hänelle nimen Immanuel.',
        15: 'Voita ja hunajaa hän syö siinä iässä, jolloin hän oppii hylkäämään pahan ja valitsemaan hyvän.',
        16: 'Sillä ennen kuin poika on oppinut hylkäämään pahan ja valitsemaan hyvän, tulee autioksi maa, jonka kahta kuningasta sinä kauhistut.',
        17: 'Herra antaa tulla sinulle, kansallesi ja isäsi suvulle ne päivät, joita ei ole ollut siitä asti, kun Efraim luopui Juudasta. Hän antaa tulla Assurin kuninkaan.',
        18: 'Sinä päivänä Herra viheltää kärpäset Egyptin virtojen suulta ja mehiläiset Assurin maasta,',
        19: 'ja ne tulevat ja laskeutuvat kaikki vuorenrotkoihin ja kallionkoloihin, kaikkiin orjantappurapensaisiin ja kaikille juottopaikoille.',
        20: 'Sinä päivänä Herra ajattaa virran tuolta puolen palkatulla partaveitsellä, Assurin kuninkaalla, pään ja häpykarvat. Se vie vielä parrankin.',
        21: 'Siihen aikaan pitää mies nuorta lehmää ja paria lammasta,',
        22: 'mutta runsaan maidon tulon tähden hän syö kokkelipiimää, sillä kokkelipiimää ja hunajaa syövät kaikki maahan jäljelle jääneet.',
        23: 'Siihen aikaan jokainen paikka, jossa kasvaa tuhat viinipuuta, arvoltaan tuhat hopeasekeliä, joutuu orjantappuroiden ja ohdakkeiden valtaan.',
        24: 'Sinne on mentävä nuolet ja jousi mukana, sillä koko maa on pelkkää orjantappuraa ja ohdaketta.',
        25: 'Ei yhdellekään niistä vuorista, joita nyt kuokalla kuokitaan, enää mennä orjantappuroiden ja ohdakkeiden pelosta. Ne jäävät härkien laitumeksi ja lammasten tallattaviksi."',
    },
    8: {
        1: 'Herra sanoi minulle: "Ota iso taulu ja kirjoita siihen suurella kirjoituksella: Maher-Saalal Haas-Bas."',
        2: 'Otin itselleni luotettavat todistajat, pappi Uurian ja Sakarjan, Jeberekjan pojan.',
        3: 'Lähestyin profeettavaimoani, ja hän tuli raskaaksi ja synnytti pojan. Herra sanoi minulle: "Pane hänelle nimeksi Maher-Saalal Haas-Bas.',
        4: 'Sillä ennen kuin poika oppii sanomaan: \'isä\' ja \'äiti\', viedään Damaskon tavarat ja Samarian saalis Assurin kuninkaan eteen."',
        5: 'Herra puhui jälleen minulle ja sanoi:',
        6: '"Koska tämä kansa halveksii Siiloan hiljaa virtaavia vesiä ja iloitsee Resinin ja Remaljan pojan kanssa,',
        7: 'katso, sen tähden Herra antaa tulla heidän ylitseen virran vedet, valtavat ja suuret, Assurin kuninkaan ja kaiken hänen kunniansa. Se nousee kaikkien uomiensa yli ja menee yli kaikkien äyräidensä.',
        8: 'Se tunkeutuu Juudaan, paisuu, tulvii ja ulottuu kaulaan saakka. Siipensä levittäen se peittää kaikkialta maasi, Immanuel."',
        9: 'Riehukaa, kansat, kuitenkin kukistutte. Kuulkaa, kaikki kaukaiset maat. Varustautukaa, kuitenkin kukistutte. Varustautukaa, kuitenkin kukistutte.',
        10: 'Pitäkää neuvoa: se raukeaa. Sopikaa sopimus: se ei pysy. Sillä tässä on Immanuel.',
        11: 'Sillä näin sanoi minulle Herra, kun hänen kätensä valtasi minut ja hän varoitti minua vaeltamasta tämän kansan tietä:',
        12: '"Älkää sanoko salaliitoksi kaikkea, mitä tämä kansa sanoo salaliitoksi. Älkää pelätkö, mitä se pelkää, älkääkä kauhistuko.',
        13: 'Herra Sebaot pitäkää pyhänä ja häntä pelätkää ja kauhistukaa.',
        14: 'Hän on oleva pyhäkkö, loukkauskivi ja kompastuksen kallio molemmille Israelin huonekunnille, paula ja ansa Jerusalemin asukkaille.',
        15: 'Monet heistä kompastuvat, kaatuvat ja ruhjoutuvat, monet kiedotaan ja vangitaan.',
        16: 'Sido todistus talteen, lukitse laki sinetillä opetuslapsiini."',
        17: 'Odotan Herraa, joka kätkee kasvonsa Jaakobin heimolta, ja panen toivoni häneen.',
        18: 'Katso, minä ja lapset, jotka Herra on minulle antanut, me olemme Herran Sebaotin merkkeinä ja ihmeinä Israelissa, hänen, joka asuu Siionin vuorella.',
        19: 'Kun he sanovat teille: "Kysykää vainaja- ja tietäjähengiltä, jotka supisevat ja mumisevat", eikö kansa kysyisi Jumalaltaan? Kuolleiltako elävien sijaan?',
        20: '"Pysykää laissa ja todistuksessa!" Jos he eivät näin sano, heille ei aamunkoittoa ole.',
        21: 'Siellä he kuljeskelevat vaivattuina ja nälkäisinä, ja nälissään he vihastuvat ja kiroavat Kuninkaansa ja Jumalansa. He luovat silmänsä korkeuteen.',
        22: 'He katsahtavat maan puoleen, mutta katso, on ainoastaan ahdistusta ja pimeyttä. Heidät on syösty tuskan synkeyteen ja pimeyteen.',
        23: 'Mutta se, mikä nyt on vaivan alla, ei jää pimeään. Entiseen aikaan hän saattoi halveksituksi Sebulonin maan ja Naftalin maan, mutta tulevaisuudessa hän saattaa kunniaan merentien, Jordanin tuonpuoleisen maan, pakanain alueen.',
    },
    9: {
        1: 'Kansa, joka pimeydessä vaeltaa, näkee suuren valon. Niille, jotka asuvat kuoleman varjon maassa, loistaa valo.',
        2: 'Sinä lisäät kansan, annat sille suuren ilon. He iloitsevat edessäsi, kuin elonaikana iloitaan, kuin saaliinjaossa riemuitaan.',
        3: 'Sillä heidän kuormansa ikeen, heidän olkainsa vitsan ja heidän käskijänsä sauvan sinä särjet kuin Midianin päivänä.',
        4: 'Sillä kaikki taistelun pauhussa tallatut sotakengät ja verellä tahratut sotilaspuvut poltetaan ja kulutetaan tulella.',
        5: 'Sillä lapsi on meille syntynyt, Poika on meille annettu, jonka hartioilla on valtius, ja hänen nimensä on: Ihmeellinen neuvonantaja, Voimallinen Jumala, Iankaikkinen isä, Rauhanruhtinas.',
        6: 'Valtius on oleva suuri ja rauha loputon Daavidin valtaistuimella ja hänen valtakunnallaan. Se perustetaan ja vahvistetaan tuomiolla ja vanhurskaudella nyt ja iankaikkisesti. Herran Sebaotin kiivaus on sen tekevä.',
        7: 'Herra lähetti sanan Jaakobia vastaan, ja se iski Israeliin,',
        8: 'ja sen sai tuntea koko kansa, Efraim ja Samarian asukkaat, mutta he sanoivat ylpeydessään ja sydämensä kopeudessa:',
        9: '"Tiilikivet sortuivat maahan, mutta me rakennamme hakatuista kivistä. Metsäviikunapuut hakattiin poikki, mutta me panemme setripuita niiden tilalle."',
        10: 'Silloin Herra nostatti sitä vastaan Resinin ahdistajat ja kiihotti sen viholliset,',
        11: 'aramilaiset edestä ja filistealaiset takaa, ja he söivät Israelia suun täydeltä. Kaiken tämän takia hänen vihansa ei ole asettunut, ja vieläkin hänen kätensä on ojennettuna.',
        12: 'Mutta kansa ei palannut kurittajansa luo, eivätkä he etsineet Herraa Sebaotia.',
        13: 'Sen tähden Herra katkaisi Israelilta pään ja hännän, palmunlehvän ja kaislan, yhtenä päivänä.',
        14: 'Vanhin ja arvossapidetty on pää, mutta profeetta, joka valhetta opettaa, on häntä.',
        15: 'Tämän kansan johtajista tuli eksyttäjiä, ja johdettavat joutuivat hämminkiin.',
        16: 'Sen tähden Herra ei iloitse sen nuorista miehistä eikä armahda sen orpoja ja leskiä, sillä he ovat kaikki jumalattomia ja pahantekijöitä, ja jokainen suu puhuu hulluutta. Kaiken tämän takia hänen vihansa ei ole asettunut, ja vieläkin hänen kätensä on ojennettuna.',
        17: 'Sillä jumalattomuus palaa tulena, kuluttaa orjantappurat ja ohdakkeet ja sytyttää sankan metsän, niin että se tupruaa savuna ilmaan.',
        18: 'Herran Sebaotin vihasta maa syttyy palamaan, ja kansa on kuin tulen syötävänä. Toinen ei sääli toistaan.',
        19: 'Ahmivat oikealta, mutta on yhä nälkä, syövät vasemmalta, mutta eivät saa kylläänsä. Jokainen syö oman käsivartensa lihaa:',
        20: 'Manasse Efraimia ja Efraim Manassea, molemmat yhdessä käyvät Juudan kimppuun. Kaiken tämän tähden hänen vihansa ei ole asettunut, ja vieläkin hänen kätensä on ojennettuna.',
    },
    10: {
        1: 'Voi lainsäätäjiä, jotka laativat jumalattomia lakeja ja kirjoittelevat vääriä tuomioita',
        2: 'vääntääkseen köyhien asian ja riistääkseen kansani kurjien oikeuden, että lesket joutuisivat heidän saaliikseen ja orvot heidän ryöstettävikseen!',
        3: 'Mutta mitä teette koston päivänä, rajumyrskyssä, joka tulee kaukaa? Kenen turviin pakenette apua saamaan ja minne talletatte tavaranne?',
        4: 'Ei muuta kuin vaivutte vangittujen joukkoon tai kaadutte surmattujen sekaan. Kaiken tämän tähden hänen vihansa ei ole asettunut, ja vieläkin hänen kätensä on ojennettuna.',
        5: 'Voi Assuria, joka on vihani vitsa ja jolla on kädessään vihastumiseni sauva!',
        6: 'Lähetän hänet jumalattoman kansakunnan kimppuun, käsken hänet kansaa vastaan, johon olen vihastunut, saalista saamaan, ryöstämään ja tallaamaan sitä kuin katujen lokaa.',
        7: 'Mutta hän ei ajattele niin. Se ei ole hänen sydämensä ajatus, vaan hänen sydämensä halu on hävittää ja tuhota paljon kansoja.',
        8: 'Sillä hän sanoo: "Eivätkö ruhtinaani ole kaikki kuninkaita?',
        9: 'Eikö käynyt Kalnon niin kuin Karkemiin, eikö Hamatin kuin Arpadin ja Samarian kuin Damaskon?',
        10: 'Niin kuin käteni on saavuttanut epäjumalien valtakunnat, joiden jumalankuvat olivat paremmat kuin Jerusalemin ja Samarian –',
        11: 'enkö tekisi Jerusalemille ja sen epäjumalankuville, samoin kuin tein Samarialle ja sen epäjumalille?"',
        12: 'Mutta kun Herra on päättänyt kaiken työnsä Siionin vuorella ja Jerusalemissa, kostan Assurin kuninkaalle hänen sydämensä ylpeyden hedelmän ja hänen kopeitten silmiensä ylvästelyn.',
        13: 'Sillä hän sanoo: "Oman käteni voimalla sen tein ja omalla viisaudellani, sillä olen ymmärtäväinen. Siirsin kansojen rajat ja ryöstin heidän aarteensa ja puskin ne kumoon kuin härkä valtaistuimella istujat.',
        14: 'Käteni tavoitti kansojen rikkaudet kuin linnun pesän. Kuten hylätyt munat kootaan, minä olen koonnut kaikki maat, eikä ketään ollut, joka olisi siipeä räpyttänyt tai nokkansa avannut ja piipittänyt."',
        15: 'Ylpeileekö kirves hakkaajaansa vastaan, tai rehenteleekö saha olevansa sahaajaa suurempi? Ikään kuin vitsa heiluttaisi kohottajaansa ja sauva nostaisi koholle sen, mikä ei ole puuta!',
        16: 'Sen tähden Herra, Herra Sebaot, lähettää hänen lihavuuteensa näivetystaudin, ja hänen kunniansa alle syttyy tuli kuin tulipalo.',
        17: 'Israelin valo on tuleva tuleksi ja hänen Pyhänsä liekiksi, joka polttaa ja kuluttaa hänen ohdakkeensa ja orjantappuransa yhtenä päivänä',
        18: 'ja hänen metsänsä ja puutarhansa ihanuuden, luihin ja ytimiin asti, ja hän tulee riutuvan sairaan kaltaiseksi.',
        19: 'On helppo laskea ne puut, jotka jäävät jäljelle hänen metsästään. Poika voi kirjoittaa ne muistiin.',
        20: 'Sinä päivänä ei Israelin jäännös eivätkä Jaakobin heimon pelastuneet enää turvaudu lyöjäänsä, vaan he turvautuvat totuudessa Herraan, Israelin Pyhään.',
        21: 'Jäännös, Jaakobin jäännös, palaa voimallisen Jumalan luo.',
        22: 'Sillä vaikka kansaasi, Israel, olisi kuin meren hiekkaa, siitä palaa ainoastaan jäännös. Päätetty on hävitys, joka tulee, vanhurskautta tulvillaan.',
        23: 'Sillä hävityksen ja tuomiopäätöksen panee toimeen Herra, Herra Sebaot, kaikessa maassa.',
        24: 'Sen tähden Herra, Herra Sebaot, sanoo näin: "Kansani, sinä, joka asut Siionissa, älä pelkää Assuria, kun hän lyö sinua vitsalla ja kohottaa sauvansa sinua vastaan Egyptin tavalla.',
        25: 'Sillä lyhyt hetki vielä, niin suuttumus täyttyy, ja vihani kääntyy hävittämään heidät."',
        26: 'Silloin Herra Sebaot heiluttaa ruoskaa häntä vastaan, kuten silloin, kun Midian lyötiin Oorebin kalliolla, ja hänen sauvansa oli ojennettuna meren yli, ja hän kohottaa sen kuin muinoin Egyptiä vastaan.',
        27: 'Sinä päivänä kirpoaa hänen kuormansa hartioiltasi ja hänen ikeensä niskaltasi, sillä ies särkyy lihavuudesta.',
        28: 'Hän tulee Aijatiin, kulkee Migronin kautta, ja jättää kuormastonsa Mikmaaseen.',
        29: 'He kulkevat solatien poikki: "Geba on yöpaikkamme." Raama vapisee, Saulin Gibea pakenee.',
        30: 'Huuda kimakasti, tytär Gallim! Kuuntele, Laisa! Poloinen Anatot!',
        31: 'Madmena menee pakoon, Geebimin asukkaat vievät tavaransa turvaan.',
        32: 'Vielä samana päivänä hän pysähtyy Noobiin, hän kohottaa kätensä tytär Siionin vuorta, Jerusalemin kukkulaa, vastaan –',
        33: 'katso, silloin Herra, Herra Sebaot, katkaisee hänen latvansa kauhistavalla voimalla, vartevat rungot kaadetaan, ja korkeat kukistuvat.',
        34: 'Metsän tiheikkö hakataan kirveellä maahan, ja Libanon kaatuu Valtasuuruuden edessä.',
    },
    11: {
        1: 'Mutta Iisain kannosta puhkeaa Virpi, ja Vesa versoo hänen juuristaan.',
        2: 'Hänen päällään lepää Herran Henki, viisauden ja ymmärryksen Henki, neuvon ja voiman Henki, tiedon ja Herran pelon Henki.',
        3: 'Hän haluaa Herran pelkoa. Hän ei tuomitse silmän näöltä eikä jaa oikeutta korvan kuulolta,',
        4: 'vaan tuomitsee kurjat vanhurskaasti ja jakaa oikein oikeutta maan nöyrille. Suunsa sauvalla hän lyö maata, surmaa jumalattoman huultensa Henkäyksellä.',
        5: 'Vanhurskaus on hänen lanteittensa vyö ja totuus hänen lanteittensa side.',
        6: 'Susi asuu karitsan kanssa, ja pantteri makaa kilin vieressä. Vasikka, nuori leijona ja syöttöhärkä ovat yhdessä, ja pieni poika niitä paimentaa.',
        7: 'Lehmä ja karhu käyvät laitumella, niiden vasikat ja pennut makaavat yhdessä, ja leijona syö rehua kuin nauta.',
        8: 'Imeväinen leikittelee kyyn kololla, ja vieroitettu kurottaa kätensä käärmeen luolaan.',
        9: 'Ei missään pyhällä vuorellani tehdä pahaa eikä vahinkoa, sillä maa on täynnä Herran tuntemusta, niin kuin vedet peittävät meren.',
        10: 'Sinä päivänä pakanat etsivät Iisain juurta, joka on kansojen lippuna, ja hänen asumuksensa on oleva kunniaa täynnä.',
        11: 'Sinä päivänä Herra vielä toisen kerran ojentaa kätensä hankkiakseen itselleen kansansa jäännöksen, joka on jäljellä Assurissa, Egyptissä, Patroksessa, Kuusissa, Eelamissa, Sinearissa, Hamatissa ja merensaarilla.',
        12: 'Hän nostaa viirin pakanakansoille ja kokoaa Israelin karkotetut miehet, ja Juudan hajotetut naiset hän kerää maan neljästä äärestä.',
        13: 'Silloin katoaa Efraimin kateus, ja Juudan vihat häviävät. Efraim ei kadehdi Juudaa, eikä Juuda vihaa Efraimia.',
        14: 'Niin he lentävät länteen päin filistealaisten niskaan. Yhdessä he ryöstävät Idän miehiä. Edom ja Mooab joutuvat heidän käsiinsä, ammonilaiset heidän alamaisikseen.',
        15: 'Herra vihkii tuhon omaksi Egyptin merenlahden ja vihansa hehkussa kohottaa kätensä Eufrat-virtaa vastaan, lyö sen hajalle seitsemäksi puroksi ja tekee sen sandaalein kuljettavaksi.',
        16: 'Siitä tulee valtatie hänen kansansa jäännökselle, joka on jäljellä Assurissa, niin kuin tuli Israelille silloin, kun se lähti Egyptin maasta.',
    },
    12: {
        1: 'Sinä päivänä sanot: "Kiitän sinua, Herra, sillä olit minuun vihastunut, mutta vihasi asettui, ja lohdutit minua.',
        2: 'Katso, Jumala on pelastukseni, olen turvassa enkä pelkää, sillä Herra, Herra on voimani ja ylistysvirteni, hän tuli minulle pelastukseksi."',
        3: 'Te saatte ilolla ammentaa vettä pelastuksen lähteistä.',
        4: 'Sinä päivänä te sanotte: "Kiittäkää Herraa, julistakaa hänen nimeään, tehkää hänen tekonsa tiettäviksi pakanakansojen keskuudessa, tunnustakaa, että hänen nimensä on korkea.',
        5: 'Veisatkaa ylistystä Herralle, sillä valtavia tekoja hän on tehnyt. Tulkoot ne tunnetuiksi kaikessa maassa.',
        6: 'Huutakaa ja riemuitkaa, Siionin asukkaat, sillä suuri on keskellänne Israelin Pyhä."',
    },
    13: {
        1: 'Profeettasana Baabelista, Jesajan, Aamosin pojan, näkemä.',
        2: 'Pystyttäkää viiri paljaalle vuoren laelle, korottakaa äänenne heille, viittokaa heitä kädellä menemään sisälle ruhtinaiden porteista.',
        3: 'Minä olen antanut käskyn pyhitetyilleni ja kutsunut sankarini vihani työhön, ne, jotka riemuitsevat valtasuuruudestani.',
        4: 'Kuule, vuorilla käy kuin paljojen kansojen pauhu. Kuule valtakuntien, kokoontuneitten kansojen kohinaa: Herra Sebaot katsastaa sotajoukkoaan.',
        5: 'He tulevat kaukaisesta maasta, taivaan ääristä, Herra ja hänen vihansa aseet, hävittämään kaiken maan.',
        6: 'Valittakaa, sillä Herran päivä on lähellä, se tulee hävityksenä Kaikkivaltiaalta.',
        7: 'Sen tähden kaikki kädet herpoavat, ja kaikki ihmissydämet raukeavat.',
        8: 'He pelästyvät, kivut ja tuskat valtaavat heidät, he vääntelehtivät kuin synnyttäjä, tuijottavat toisiinsa kauhistuneina ja kasvot tulta leiskuen.',
        9: 'Katso, Herran päivä tulee, tulee armottomana, tulee kiivaus ja vihan hehku, tekemään autioksi maan ja hävittämään siitä syntiset.',
        10: 'Sillä taivaan tähdet ja Orionin tähdet eivät loista valollaan, aurinko on pimeä noustessaan, kuu ei kajasta kirkkaana.',
        11: 'Kostan maanpiirille sen pahuuden ja jumalattomille heidän pahat tekonsa. Lopetan julkeitten kopeuden ja painan maahan väkivaltaisten ylpeyden.',
        12: 'Teen kuolevaiset harvinaisemmiksi kuin puhdas kulta, ihmiset harvinaisemmiksi kuin Oofirin kulta.',
        13: 'Sen tähden järisytän taivaat, ja maa järkkyy paikaltaan Herran Sebaotin kiivaudesta, hänen vihansa hehkun päivänä.',
        14: 'Kuin säikytetyt gasellit ja kuin lampaat, joilla ei ole kokoajaa, he kääntyvät kukin kansansa luo, pakenevat kukin omalle maalleen.',
        15: 'Kuka ikinä tavoitetaan, se lävistetään. Se, joka joutuu kiinni, kaatuu miekkaan.',
        16: 'Heidän pienet lapsensa murskataan heidän silmiensä edessä, heidän talonsa ryöstetään, ja heidän vaimonsa raiskataan.',
        17: 'Katso, herätän heitä vastaan meedialaiset, jotka eivät huoli hopeasta eivätkä välitä kullasta.',
        18: 'Heidän jousensa kaatavat nuoria miehiä. He eivät armahda kohdun hedelmää eivätkä sääli lapsia.',
        19: 'Silloin Baabelin, valtakuntien kaunistuksen, kaldealaisten ylpeyden ja loiston, käy kuin Sodoman ja Gomorran, jotka Jumala hävitti.',
        20: 'Sitä ei ikinä enää asuta. Se jää autioksi polvesta polveen. Arabi ei tee sinne telttaansa, eivätkä paimenet lepuuta siellä laumaansa.',
        21: 'Erämaan eläimet lepäävät siellä, sen huoneet ovat pöllöjä täynnä, strutsit asuvat siellä, ja vuohipukit siellä hyppelevät.',
        22: 'Sakaalit ulvovat sen palatseissa ja hyeenat huvilinnoissa. Sen aika on lähellä, tulemaisillaan. Sen päiviä ei pidennetä.',
    },
    14: {
        1: 'Sillä Herra armahtaa Jaakobia ja valitsee vielä Israelin ja sijoittaa heidät heidän omaan maahansa. Muukalaiset liittyvät heihin ja yhtyvät Jaakobin heimoon.',
        2: 'Kansat ottavat heidät ja tuovat heidät heidän kotiinsa, ja Israelin heimo saa heidät Herran maassa omikseen, orjiksi ja orjattariksi, ja he vangitsevat vangitsijansa ja hallitsevat käskijöitään.',
        3: 'Sinä päivänä, jona Herra päästää sinut rauhaan vaivastasi, tuskastasi ja siitä kovasta työstä, jota sinulla teetettiin,',
        4: 'virität tämän pilkkalaulun Baabelin kuninkaasta ja sanot: "Kuinka on käskijästä tullut loppu, tullut loppu ahdistuksesta!',
        5: 'Herra on murtanut jumalattomien sauvan, valtiaitten vitsan,',
        6: 'joka löi kansoja vihan vimmassa, löi lakkaamatta, joka vihassa vallitsi kansakuntia ja vainosi niitä säälimättä.',
        7: 'Kaikki maa on saanut levon ja rauhan. He puhkeavat riemuun.',
        8: "Sypressitkin sekä Libanonin setrit iloitsevat sinusta: 'Sinun maata mentyäsi ei nouse kukaan meitä hakkaamaan.'",
        9: 'Helvetti tuolla alhaalla värisi tähtesi ottaakseen sinut vastaan, kun tulet. Se herättää kuolleet sinulle, kaikki maan johtomiehet, nostattaa valtaistuimiltaan kaikki kansojen kuninkaat.',
        10: "Kaikki he lausuvat ja sanovat sinulle: 'Myös sinä olet riutunut niin kuin mekin, olet tullut meidän kaltaiseksemme.'",
        11: 'Alas helvettiin on vaipunut komeutesi ja harppujesi helinä. Allasi ovat vuoteena madot. Toukat ovat peittonasi.',
        12: 'Kuinka olet taivaalta pudonnut, sinä kointähti, aamuruskon poika! Kuinka olet maahan syösty, sinä kansojen kukistaja!',
        13: "Sinä sanoit sydämessäsi: 'Nousen taivaaseen, korkeammalle Jumalan tähtiä korotan istuimeni ja istun kokoontumisvuorelle pohjoisen puolelle.",
        14: "Nousen pilvien kukkuloille, teen itseni Korkeimman vertaiseksi.'",
        15: 'Mutta alas helvettiin sinä joudut, syvimpään kuiluun.',
        16: "Ne, jotka sinut näkevät, katsovat pitkään, tarkastelevat sinua: 'Onko tämä se mies, joka järisytti maan ja järkytti valtakunnat,",
        17: "joka teki maanpiirin erämaaksi ja hävitti sen kaupungit, joka ei päästänyt vankejaan kotiin?'",
        18: 'Kansojen kuninkaat lepäävät kaikki kunniassa, kukin kammiossaan.',
        19: 'Mutta sinä olet kaukana haudastasi, viskattuna pois kuin hylätty vesa, olet peittynyt surmattujen, miekalla lävistettyjen, kiviseen kuoppaan suistuneitten alle, olet kuin tallattu raato.',
        20: 'Et saa yhtyä heihin haudassa, sillä olet maasi hävittänyt, kansasi tappanut. Ikinä enää ei mainita pahantekijöiden sukua.',
        21: 'Laittakaa hänen lapsilleen verilöyly heidän isiensä pahojen tekojen tähden, etteivät he nousisi ottamaan omakseen maata ja täyttäisi maanpiiriä kaupungeilla."',
        22: 'Nousen heitä vastaan, sanoo Herra Sebaot, ja hävitän Baabelilta nimen ja jäännöksen, suvun ja jälkeläiset, sanoo Herra.',
        23: 'Teen sen siilien perinnöksi ja vesirämeeksi, lakaisen sen pois hävityksen luudalla, sanoo Herra Sebaot.',
        24: 'Herra Sebaot on vannonut sanoen: Totisesti, mitä olen ajatellut, se tapahtuu, mitä olen päättänyt, se toteutuu:',
        25: 'muserran Assurin maassani ja tallaan hänet vuorillani, niin että hänen ikeensä heltiää heidän päältään ja hänen kuormansa heltiää heidän hartioiltaan.',
        26: 'Tämä on päätös, päätetty kaikesta maasta, tämä on käsi, ojennettu kaikkien kansojen yli.',
        27: 'Sillä Herra Sebaot on päättänyt, – kuka sen tyhjäksi tekee? Hänen kätensä on ojennettu, – kuka sen torjuu?',
        28: 'Kuningas Aahaan kuolinvuotena tuli tämä profeettasana:',
        29: 'Älä, Filistea kaikkinesi, iloitse siitä, että sauva, joka sinua löi, on murtunut. Sillä käärmeen juuresta kasvaa kyy, ja sen hedelmä on lentävä käärme.',
        30: 'Vaivaisista kurjimmat löytävät laitumen, ja köyhät saavat levätä turvassa, mutta sinun juuresi tapan nälkään, ja sinun jäännöksesi surmataan.',
        31: 'Valita, portti, huuda, kaupunki. Menehdy pelkoon, Filistea kaikkinesi, sillä pohjoisesta tulee savu; eikä yksikään erkane vihollisen riveistä.',
        32: 'Mutta mitä vastataan pakanakansan sanansaattajille? " Herra on perustanut Siionin, ja hänen kansansa kurjat saavat siinä turvan."',
    },
    15: {
        1: 'Ennustus Mooabista. Hävityksen yönä tuhoutuu Aar-Mooab; hävityksen yönä tuhoutuu Kiir-Mooab.',
        2: 'Bait ja Diibon nousevat uhrikukkuloille itkemään, Nebolla ja Meedebassa Mooab valittaa; kaikki päät ovat paljaiksi ajettuja, kaikki parrat ovat leikattuja.',
        3: 'Kaduilla he kääriytyvät säkkeihin, katoilla ja toreilla kaikki valittavat, he menehtyvät itkuun.',
        4: 'Hesbon ja Elale huutavat. Niiden itku kuuluu Jahaaseen asti. Sen tähden Mooabin varustetut miehet vaikeroivat, sen sielu vapisee.',
        5: 'Sydämeni huutaa Mooabin tähden. Sen pakolaisia on aina Sooariin saakka, aina Eglat-Selisijjaan asti. Luuhitin solatietä he nousevat itkien, Hooronaimin tiellä he puhkeavat itkuun hävityksen tähden.',
        6: 'Nimrimin vedet ehtyvät erämaaksi, heinä kuivuu, ruoho lakastuu eikä vihantaa ole.',
        7: 'Sen tähden he kantavat hankkimansa säästön ja tallettamansa tavaran Pajupuron yli.',
        8: 'Itku kiertää Mooabin rajoja, voihke kuuluu Eglaimiin asti, valitus Beer-Eelimiin asti.',
        9: 'Sillä Diimonin vedet ovat verta täynnä, ja vielä muutakin tuon Diimonille: leijonan Mooabin pelastuneiden ja maahan jääneiden kimppuun.',
    },
    16: {
        1: '"Lähettäkää maan hallitsijalle tulevat lampaat Selasta erämaan kautta tytär Siionin vuorelle."',
        2: 'Kuin pakenevat linnut, säikytetty pesue, ovat Mooabin tyttäret Arnonin kahlauspaikoilla.',
        3: '"Anna neuvo, ryhdy välittäjäksi, tee varjosi yön kaltaiseksi keskellä päivää, kätke karkotetut äläkä ilmaise pakenevia.',
        4: 'Salli minun karkotettujeni asua luonasi, Mooab, ole heille suojana hävittäjää vastaan. Sillä sortajalle tulee loppu, hävitys lakkaa, ja tallaaja on maasta poissa.',
        5: 'Valtaistuin vahvistetaan laupeudella, ja sillä istuu vakaasti Daavidin majassa Tuomari, joka harrastaa oikeutta ja ahkeroi vanhurskautta."',
        6: '"Me olemme kuulleet Mooabin ylpeilyn, tuon hyvin korskean, hänen kopeilunsa, ylpeilynsä ja vihansa, hänen väärät puheensa."',
        7: 'Sen tähden Mooab valittaa Mooabille, kaikki he valittavat. Kiir-Haresetin rypälekakkuja te huokailette, ja olette aivan murtuneita.',
        8: 'Sillä kuihtuneet ovat Hesbonin viinitarhat, Sibman viiniköynnökset. Niiden jalot rypäleet kaatoivat kansojen valtiaita, ne ulottuivat Jaeseriin asti, harhailivat halki erämaan, niiden vesat levisivät ja menivät yli meren.',
        9: 'Sen tähden minä itken Jaeserin kanssa, itken Sibman viiniköynnöksiä, kastelen kyyneleilläni sinua, Hesbon, ja sinua, Elale, sillä hedelmän- ja viininkorjuun keskelle on kajahtanut sotahuuto.',
        10: 'Ilo ja riemu on tauonnut puutarhasta, viinitarhoissa ei riemuita, ei ratketa nauruun; ei poljeta viiniä viinikuurnissa. "Minä olen vaientanut ilohuudon."',
        11: 'Siksi sisimpäni värisee Mooabin tähden kuin lyyra, sydämeni Kiir-Hereksen tähden.',
        12: 'Vaikka Mooab kuinka astuisi uhrikukkulalle ja uuvuttaisi itsensä sillä ja vaikka kuinka menisi pyhäkköönsä rukoilemaan, se ei häntä auta.',
        13: 'Tämä on sana, jonka Herra oli jo ennen puhunut Mooabille.',
        14: 'Mutta nyt Herra lausuu sanoen: Ennen kuin kolme vuotta on kulunut – kolme palkkalaisen vuotta – Mooabin kunnia suurine joukkoineen tehdään halvaksi, ja jäännös on oleva hyvin pieni ja mitätön.',
    },
    17: {
        1: 'Ennustus Damaskosta. Katso, Damasko poistetaan kaupunkien luvusta ja luhistuu raunioiksi.',
        2: 'Aroerin kaupungit jäävät autioiksi karjalaumojen haltuun. Ne lepäävät siellä kenenkään pelottelematta.',
        3: 'Efraimilta menee suojavarustus ja Damaskolta kuninkuus ja Aramista jäännöskin. Niiden käy kuin israelilaisten kunnian, sanoo Herra Sebaot.',
        4: 'Sinä päivänä Jaakobin kunnia köyhtyy, ja hänen ruumiinsa lihavuus laihtuu.',
        5: 'Silloin käy kuin leikkaajan kahmaistessa viljaa ja hänen käsivartensa leikatessa tähkiä. Silloin käy kuin tähkiä poimittaessa Refaimin tasangolla.',
        6: 'Sen verran jää jälkikorjuuta kuin öljypuuta karistettaessa: pari, kolme marjaa korkealle latvaan, neljä, viisi hedelmäpuun oksiin, sanoo Herra, Israelin Jumala.',
        7: 'Sinä päivänä ihminen luo katseen Luojaansa, ja hänen silmänsä katsovat Israelin Pyhään,',
        8: 'eikä hän luo katsettaan alttareihin, heidän omien kättensä tekoon, eikä katso niihin, mitä hänen sormensa ovat tehneet, ei aseroihin eikä auringonpatsaisiin.',
        9: 'Sinä päivänä hänen linnoitetut kaupunkinsa ovat kuin autioituneet paikat metsissä ja kukkuloilla, jotka jätettiin autioiksi israelilaisten tullessa, ja maa muuttuu erämaaksi.',
        10: 'Sillä unohdit pelastuksesi Jumalan etkä muistanut turvakalliotasi. Sen tähden istutat ihania istutuksia ja kylvät vieraita viiniköynnöksiä.',
        11: 'Istutuspäivänä saat ne kasvamaan, ja aamulla saat kylvösi kukoistamaan – mutta poissa on sato sairauden päivänä, ja parantumaton on kipu.',
        12: 'Voi paljojen kansojen pauhua – ne pauhaavat, kuin meri pauhaa, ja kansakuntien kohinaa – ne kohisevat, kuin valtavat vedet kohisevat!',
        13: 'Kansakunnat kohisevat, kuin suuret vedet kohisevat. Mutta hän nuhtelee niitä, ja ne pakenevat kauas. Ne karkotetaan kuin akanat tuulessa vuorilla, kuin lentävät lehdet rajuilmassa.',
        14: 'Katso, ehtoolla on oleva kauhu, aamun tullen ei heitä enää ole. Tämä on riistäjiemme osa, ryöstäjiemme arpa.',
    },
    18: {
        1: 'Voi siipien surinan maata, joka on tuolla puolen Kuusin jokien,',
        2: 'joka lähettää sanansaattajat virralle, ruokoveneissä vesiä myöten! Lähtekää, te nopeat sanansaattajat, kookkaan ja kiiltäväihoisen kansan luo, lähellä ja kaukana pelätyn kansan luo, voimakkaan sortajakansan luo, jonka maata joet halkovat.',
        3: 'Te kaikki maanpiirin asukkaat, te maan asuttajat, katsokaa, milloin viiri nostetaan vuorille, ja kuunnelkaa, kun puhalletaan torveen.',
        4: 'Sillä näin Herra on minulle sanonut: "Pysyn hiljaa ja katselen asunnostani kuin hehkuva helle päivän paistaessa ja kuin kastepilvi elonajan helteessä."',
        5: 'Sillä ennen viininkorjuuta, kun kukinta on päättynyt ja kukasta on tullut kypsyvä marja, hän hakkaa vesoimella köynnökset, hävittää ja katkoo varret.',
        6: 'Ne jätetään kaikki vuorten petolintujen ja maan eläinten haltuun. Petolinnut pitävät siellä kesää, ja kaikenlaiset maan eläimet siellä talvehtivat.',
        7: 'Siihen aikaan kookas ja kiiltäväihoinen kansa, lähellä ja kaukana pelätty kansa, voimakas sortajakansa, jonka maata joet halkovat, tuodaan lahjaksi Herralle Sebaotille siihen paikkaan, missä asuu Herran Sebaotin nimi: Siionin vuorelle.',
    },
    19: {
        1: 'Profeettasana Egyptistä. Katso, Herra ajaa nopealla pilvellä ja tulee Egyptiin. Silloin vapisevat Egyptin epäjumalat hänen edessään, ja sydän raukeaa Egyptin rinnassa.',
        2: 'Kiihotan Egyptin Egyptiä vastaan, niin että he sotivat keskenään, ystävä ystävää vastaan, kaupunki kaupunkia vastaan, valtakunta valtakuntaa vastaan.',
        3: 'Silloin Egyptiltä katoaa rohkeus rinnasta, ja hämmennän hänen neuvonsa. He kysyvät epäjumalilta, henkienmanaajilta, vainaja- ja tietäjähengiltä.',
        4: 'Annan Egyptin tylyn herran käsiin, ja kova kuningas on hallitseva heitä, sanoo Herra, Herra Sebaot.',
        5: 'Vedet loppuvat virrasta, joki ehtyy ja kuivuu.',
        6: 'Joet levittävät löyhkää, Egyptin kanavat madaltuvat ja ehtyvät, ruoko ja kaisla lakastuvat.',
        7: 'Ruohikot Niilivirran varsilla, virran suussa, ja kaikki Niilivirran kylvömaat kuivuvat, kuihtuvat ja häviävät.',
        8: 'Kalastajat valittavat ja murehtivat. Kaikki, jotka heittävät onkea virtaan ja laskevat verkkoa veteen, nääntyvät.',
        9: 'Häpeään joutuvat ne, jotka pitelevät häkilöityjä pellavia ja jotka kutovat pellavakankaita.',
        10: 'Maan peruspylväät murskataan, ja kaikki palkkalaiset ovat murheellisella mielellä.',
        11: 'Hulluina ovat Sooanin päämiehet kaikki, viisaimmat faraon neuvonantajista ovat neuvossaan tulleet tyhmiksi. Kuinka voitte sanoa faraolle: "Olen viisaitten poika, muinaisajan kuninkaitten jälkeläinen"?',
        12: 'Missä ovat viisaasi? Ilmoittakoot sinulle – hehän sen tietävät – mitä Herra Sebaot on Egyptin osalle päättänyt.',
        13: 'Sooanin päämiehet ovat käyneet typeriksi, Noofin päämiehet ovat pettyneet. Egyptiä horjuttavat sen sukukuntien kulmakivet.',
        14: 'Herra on vuodattanut sen keskuuteen sekasorron hengen, ja niin he saattavat Egyptin horjumaan kaikissa menoissaan, kuin juopunut horjahtaa oksennukseensa.',
        15: 'Eikä menesty Egyptille mikään teko, tekipä sen pää tai häntä, palmunlehvä tai kaisla.',
        16: 'Sinä päivänä Egypti on oleva naisten kaltainen. Se vapisee ja pelkää Herran Sebaotin käden heilutusta, kun hän heiluttaa kättään sitä vastaan.',
        17: 'Juudan maa on oleva Egyptille kauhuksi. Niin usein kuin sitä sille mainitaan, se pelkää Herran Sebaotin päätöstä, jonka hän on siitä päättänyt.',
        18: 'Sinä päivänä on viisi kaupunkia Egyptin maassa puhuva Kanaanin kieltä ja vannova valan Herralle Sebaotille. Yhtä niistä mainitaan nimellä Iir-Heres.',
        19: 'Sinä päivänä on oleva Herran alttari keskellä Egyptin maata ja sen rajalla Herran patsas.',
        20: 'Se on oleva merkkinä ja todistuksena Herralle Sebaotille Egyptin maassa. Sillä he huutavat Herraa sortajien tähden, ja hän lähettää heille vapauttajan ja puolustajan, joka pelastaa heidät.',
        21: 'Silloin Herra tekee itsensä tunnetuksi egyptiläisille, ja egyptiläiset tuntevat Herran sinä päivänä ja palvelevat häntä teuras- ja ruokauhreilla, ja he tekevät Herralle lupauksia ja täyttävät ne.',
        22: 'Herra lyö egyptiläisiä, lyö ja parantaa. He palaavat Herran luo, ja hän kuulee heidän rukouksensa ja parantaa heidät.',
        23: 'Sinä päivänä on oleva valtatie Egyptistä Assuriin, ja Assur yhtyy Egyptiin ja Egypti Assuriin, ja ne, Egypti sekä Assur, palvelevat Herraa.',
        24: 'Sinä päivänä Israel on oleva kolmantena Egyptin ja Assurin rinnalla, siunauksena keskellä maata,',
        25: 'sillä Herra Sebaot siunaa sitä sanoen: "Siunattu olkoon Egypti, kansani, ja Assur, kätteni teko, ja Israel, perintöosani."',
    },
    20: {
        1: 'Sinä vuonna, jona Tartan, Sargonin, Assurin kuninkaan, lähettämänä, tuli Asdodiin, ryhtyi taisteluun Asdodia vastaan ja valloitti sen –',
        2: 'siihen aikaan Herra puhui Jesajan, Aamosin pojan, kautta sanoen: "Mene, riisu säkkipuku lanteiltasi ja vedä sandaalit jalastasi." Hän teki niin: kulki ilman viittaa ja avojaloin.',
        3: 'Herra sanoi: "Niin kuin palvelijani Jesaja on kolme vuotta kulkenut ilman viittaa ja avojaloin, merkiksi ja enteeksi Egyptille ja Kuusille,',
        4: 'niin on Assurin kuningas kuljettava Egyptin sotavankeja ja Kuusin karkotettuja, sekä nuoria että vanhoja, ilman viittaa ja avojaloin, takapuolet paljaina – Egyptin häpeä!',
        5: 'He kauhistuvat ja joutuvat häpeään Kuusin tähden, joka oli heidän toivonsa, ja Egyptin tähden, joka oli heidän ylpeytensä.',
        6: 'Tämän rantamaan asukkaat sanovat sinä päivänä: \'Katso, näin on käynyt toivomme, jonka turviin pakenimme apua saamaan vapautuaksemme Assurin kuninkaasta. Kuinka me pelastumme?\'"',
    },
    21: {
        1: 'Profeettasana meren viereisestä erämaasta. Niin kuin myrskytuulet kiitävät Negevissä, niin se tulee erämaasta, pelottavasta maasta.',
        2: 'Julma näky ilmoitettiin minulle: "Ryöstäjä ryöstää, hävittäjä hävittää. Hyökkää, Eelam! Piiritä, Meedia! Kaiken huokailun lopetan."',
        3: 'Sen tähden lanteeni ovat täynnä vapinaa, minut valtaavat tuskat kuin synnyttäjän tuskat. Minua huimaa, niin etten kuule, kauhistuttaa, niin etten näe.',
        4: 'Sydämeni värisee, kauhu pelästyttää minut. Ikävöimäni iltahämärän se muuttaa minulle vavistukseksi.',
        5: 'Pöytä katetaan, matto levitetään, syödään, juodaan. Nouskaa, te ruhtinaat, voidelkaa kilvet.',
        6: 'Sillä näin on Herra minulle sanonut: "Mene, aseta tähystäjä. Hän ilmoittakoon, mitä näkee.',
        7: 'Kun hän näkee jonon ratsastajia pareittain, jonon aaseja, jonon kameleja, niin kuunnelkoon tarkasti, hyvin tarkasti."',
        8: 'Hän huusi kuin leijona: "Tähystyspaikalla, Herra, minä seison alati, päivät pitkät, pysyn vartiopaikallani kaiket yöt.',
        9: 'Katso, tuolla tulee jonossa miehiä, parivaljakoita." Sitten hän lausui sanoen: "Kukistunut, kukistunut on Baabel, ja kaikki sen jumalien kuvat hän on murskannut maahan."',
        10: 'Maahan puitu kansani, puimatantereella poljettuni! Mitä olen kuullut Herralta Sebaotilta, Israelin Jumalalta, sen teille ilmoitan.',
        11: 'Ennustus Duumasta. Minulle huudetaan Seiristä: "Vartija, mikä hetki yöstä on? Vartija, mikä hetki yöstä on?"',
        12: 'Vartija vastaa: "Aamu on tullut, mutta silti on yö. Jos vielä kyselette, kyselkää. Tulkaa uudelleen."',
        13: 'Profeettasana Arabiaa vastaan. Yöpykää Arabian viidakoissa, te dedanilaiset karavaanit.',
        14: 'Menkää vastaan, viekää vettä janoaville. Teeman maan asukkaat ottavat pakolaiset vastaan leipää tarjoten.',
        15: 'Sillä he ovat miekkoja paossa, paljastettua miekkaa, jännitettyä jousta ja sodan raskautta paossa.',
        16: 'Sillä näin on Herra minulle sanonut: Vielä vuosi – sellainen kuin on palkkalaisen vuosi – niin kaikki Keedarin kunnia on kadonnut,',
        17: 'ja Keedarin sankarien jousiluvun jäännös on oleva vähäinen. Sillä Herra, Israelin Jumala, on puhunut.',
    },
    22: {
        1: 'Ennustus Näkylaaksosta. Mikä sinun on, kun nouset katoille kaikki mukanasi,',
        2: 'sinä kohiseva, pauhaava kaupunki, sinä remuava kylä? Surmattusi eivät ole miekan surmaamia, eivät sotaan kuolleita.',
        3: 'Kaikki sinun johtajasi ovat yhdessä paenneet, vangeiksi joutuneet, jousta vailla. Keitä vain sinun omiasi tavattiin, heidät kaikki vangittiin, kuinka kauas pakenivatkin.',
        4: 'Sen tähden sanon: "Kääntäkää katseenne minusta pois: itken katkerasti; älkää tungeksiko minua lohduttamaan, kun tytär, kansani, tuhoutuu."',
        5: 'Sillä hämmingin, hävityksen ja häiriön päivän on Herra, Herra Sebaot, pitävä Näkylaaksossa. Muurit ovat murretut, vuorille on kohonnut huuto.',
        6: 'Eelam nosti viinen saapuen vaunuineen, väkineen ja ratsumiehineen, ja Kiir paljasti kilven.',
        7: 'Ihanimmat laaksosi täyttyivät vaunuista, ratsumiehet asettuivat asemiin portin eteen.',
        8: 'Hän riisui Juudalta verhon, ja sinä päivänä loit katseesi Metsätalon asevarastoon.',
        9: 'Huomasitte monta repeämää Daavidin kaupungin muurissa ja kokositte vedet Alalammikkoon.',
        10: 'Luitte Jerusalemin talot ja hajotitte taloja vahvistaaksenne muurin,',
        11: 'ja teitte molempien muurien välille paikan, johon Vanhan lammikon vedet koottiin. Mutta sen puoleen ette katsoneet, joka tämän tuotti, häntä ette nähneet, joka tämän kauan sitten valmisti.',
        12: 'Sinä päivänä Herra, Herra Sebaot, kutsui itkuun ja valitukseen, ajamaan pään paljaaksi ja vyöttäytymään säkkiin.',
        13: 'Mutta katso: on iloa ja riemua, nautojen tappamista ja lammasten teurastusta, lihan syöntiä ja viinin juontia! "Syökäämme ja juokaamme, sillä huomenna kuolemme."',
        14: 'Korviini kuului Herran Sebaotin ilmoitus: "Totisesti, tämä syntinne ei tule sovitetuksi, ei kuolemaanne saakka, sanoo Herra, Herra Sebaot."',
        15: 'Näin sanoo Herra, Herra Sebaot: Mene tuon huoneenhaltijan luo, Sebnan luo, joka on linnan päällikkönä.',
        16: '"Mitä sinulla täällä on asiaa, ja keitä sinulla täällä on, kun hakkautat tänne itsellesi haudan, hakkautat hautasi korkeuteen, koverrat kalliolle itsellesi asunnon?"',
        17: 'Katso, Herra heittää sinua, mies, rajusti: hän kahmaisee sinut kokoon,',
        18: 'kääräisee sinut keräksi ja paiskaa pallona menemään maahan, jossa on laajuutta joka suuntaan. Sinne kuolet, ja sinne jäävät kunniavaunusi, sinä Herrasi huoneen häpeä.',
        19: 'Syöksen sinut pois paikastasi. Hän kukistaa sinut asemastasi.',
        20: 'Mutta sinä päivänä kutsun palvelijani Eljakimin, Hilkian pojan,',
        21: 'ja puetan hänen päälleen paitasi, vyötän hänet vyölläsi ja panen valtasi hänen käteensä, niin että hän on oleva isänä Jerusalemin asukkaille ja Juudan suvulle.',
        22: 'Panen Daavidin huoneen avaimen hänen olalleen. Hän avaa, eikä kukaan sulje, ja hän sulkee, eikä kukaan avaa.',
        23: 'Lyön hänet vaarnaksi vahvaan paikkaan, ja hänestä tulee kunniaistuin isänsä suvulle.',
        24: 'Hänen varaansa ripustautuu hänen isänsä suvun kaikki paljous, vesat ja versot, kaikki pienet astiat, kaikki maljat ja ruukut.',
        25: 'Sinä päivänä, sanoo Herra Sebaot, vahvaan paikkaan lyöty vaarna pettää, se katkeaa ja putoaa, ja kuorma, joka oli sen varassa, särkyy. Sillä Herra on sen puhunut.',
    },
    23: {
        1: 'Profeettasana Tyyrosta. Valittakaa, te Tarsiin laivat, sillä se on hävitetty talottomaksi, paikaksi, johon ei kuljeta. Kittiläisten maasta he saivat tämän tiedon.',
        2: 'Mykistykää, te rantamaan asukkaat! Siidonin kauppamiehet, merenkulkijat, täyttivät sinut.',
        3: 'Suuria vesiä kulki Siihorin siemen, Niilivirran vilja. Se oli Tyyron sato, ja siitä tuli kansojen kauppatavara.',
        4: 'Häpeä, Siidon, sillä näin sanoo meri, meren linnoitus: "En ole kivuissa ollut, en ole synnyttänyt, en ole kasvattanut nuorukaisia enkä saattanut neitsyitä suuriksi."',
        5: 'Kun tämä kuullaan Egyptissä, vavistaan Tyyron kuulumisia.',
        6: 'Menkää Tarsiiseen. Valittakaa, te rantamaan asukkaat.',
        7: 'Onko tämä remuava kaupunkinne, jonka alku on kaukaa menneisyydestä, se, jonka jalat kuljettivat kauas muukalaisena asumaan?',
        8: 'Kuka on tämän päättänyt Tyyron osalle, kruunujen jakelijan, jonka kauppamiehet olivat ruhtinaita, kauppiaat kunnioitettuja kautta maan?',
        9: 'Herra Sebaot on sen päättänyt häväistäkseen kaiken ylvästelyn koreuden tähden ja saattaakseen kaikki maan kunnioitetut halveksituiksi.',
        10: 'Tulvi yli maasi, tytär Tarsis kuin Niilivirta. Enää ei ole patoa.',
        11: 'Hän on ojentanut kätensä meren yli ja järkyttänyt valtakunnat. Herra on antanut käskyn Kanaania vastaan, että sen linnoitukset hävitettäkööt.',
        12: 'Hän sanoo: "Älä enää ilakoi, sinä häväisty neitsyt, tytär Siidon. Nouse, mene kittiläisten maahan; et sinä sielläkään saa levätä.',
        13: 'Katso, kaldealaisten maa, kansa, jota ei ollut enää olemassa, jonka Assur oli valmistanut erämaan eläimille, – he pystyttävät vartiotorninsa, he kukistavat sen palatsit, tekevät sen raunioiksi.',
        14: 'Valittakaa, te Tarsiin laivat, sillä hävitetty on teidän linnoituksenne."',
        15: 'Siihen aikaan Tyyro unohdetaan seitsemäksikymmeneksi vuodeksi, jotka ovat kuin saman kuninkaan aikaa. Seitsemänkymmenen vuoden kuluttua käy Tyyron, niin kuin porton laulussa sanotaan:',
        16: '"Ota lyyra, kierrä kaupunkia, sinä unohdettu portto; soita kauniisti, laula vireästi, että sinut muistettaisiin!"',
        17: 'Sitten seitsemänkymmenen vuoden kuluttua Herra katsoo Tyyron puoleen, ja se pääsee jälleen portonpalkoilleen ja tekee huorin kaikkien maan valtakuntien kanssa, mitä maan päällä on.',
        18: 'Mutta sen voitto ja palkka on oleva Herralle pyhitetty. Sitä ei koota eikä talleteta, vaan sen voitto on tuleva niille, jotka Herran edessä asuvat, runsaaksi ravinnoksi ja jaloksi vaatetukseksi.',
    },
    24: {
        1: 'Katso, Herra tekee maan tyhjäksi ja autioksi, mullistaa sen muodon ja hajottaa sen asukkaat.',
        2: 'Kuten kansan käy, niin papinkin, kuten orjan, niin hänen isäntänsä, kuten orjattaren, niin hänen emäntänsä, kuten ostajan, niin myyjän, kuten lainanottajan, niin lainanantajan, kuten velallisen, niin velkojankin.',
        3: 'Maa tyhjentämällä tyhjennetään ja ryöstämällä ryöstetään. Sillä Herra on tämän sanan puhunut.',
        4: 'Maa murehtii ja lakastuu, maanpiiri nääntyy ja lakastuu; kansan ylhäiset nääntyvät maassa.',
        5: 'Maa on saastunut asukkaittensa alla, sillä he ovat rikkoneet lait, muuttaneet käskyt, hylänneet iankaikkisen liiton.',
        6: 'Sen tähden kirous kalvaa maata, ja sen asukkaat kärsivät omasta syystään. Sen tähden maan asukkaat korventuvat kuumuudesta, ja ihmisiä jää jäljelle vain vähän.',
        7: 'Viini murehtii, viiniköynnös kuihtuu, kaikki sydämeltään iloiset huokaavat.',
        8: 'Loppunut on tamburiinien riemu, lakannut remuavien melu, loppunut lyyrojen riemu.',
        9: 'Ei juoda viiniä laulaen, väkijuoma käy juojilleen karvaaksi.',
        10: 'Kukistettu on autio kaupunki, jokainen talo on teljetty ja sisään pääsemätön.',
        11: 'Viinistä on kaduilla valitus, kaikki ilo on mennyt mailleen, riemu on paennut maasta.',
        12: 'Jäljellä on kaupungissa hävitys, portti on lyöty pirstaleiksi.',
        13: 'Sillä niin on käyvä maan päällä kansojen keskuudessa, kuin öljypuuta karistettaessa, kuin jälkikorjuussa viininkorjuun päätyttyä.',
        14: 'He korottavat äänensä ja riemuitsevat. He huutavat mereltä päin Herran valtasuuruudessa:',
        15: '"Sen tähden kunnioittakaa Herraa valon mailla, ja meren saarilla Herran, Israelin Jumalan, nimeä."',
        16: 'Maan äärestä kuulemme ylistysvirret: "Ihana on vanhurskaan osa!" Mutta sanon: "Riutuminen, riutuminen on osani, voi minua: ryöstäjät ryöstävät, repien ryöstäjät ryöstävät!"',
        17: 'Kauhu, kuoppa ja ansa ovat edessäsi, sinä maan asukas.',
        18: 'Se, joka pakenee kauhun ääntä, putoaa kuoppaan, ja se, joka kuopasta nousee, tarttuu paulaan. Sillä korkeuden ikkunat aukeavat ja maan perustukset järkkyvät.',
        19: 'Maa musertuu murskaksi, maa halkeaa ja hajoaa, maa horjuu ja huojuu.',
        20: 'Maa hoippuu ja hoipertelee kuin juopunut, huojuu kuin lehvämaja. Raskaana painaa sitä sen rikos, se kaatuu eikä enää nouse.',
        21: 'Sinä päivänä Herra kostaa korkeuden sotajoukolle korkeudessa ja maan kuninkaille maan päällä.',
        22: 'Heidät kootaan sidottuina vankikuoppaan ja suljetaan vankeuteen. Pitkän ajan kuluttua heille kostetaan.',
        23: 'Silloin kuu punastuu, ja aurinko häpeää, sillä Herra Sebaot on kuningas Siionin vuorella ja Jerusalemissa, ja hänen vanhintensa edessä loistaa kirkkaus.',
    },
    25: {
        1: 'Herra, sinä olet Jumalani; kunnioitan sinua, kiitän nimeäsi, sillä olet tehnyt ihmeitä, suunnitelmasi kaukaisilta päiviltä ovat todet ja vakaat.',
        2: 'Sillä olet tehnyt kaupungin kivikasaksi, varustetun kaupungin raunioiksi. Muukalaisten linna on kadonnut kaupunkien luvusta. Sitä ei enää ikinä rakenneta.',
        3: 'Sen tähden sinua kunnioittaa voimakas kansa, väkivaltaisten pakanoiden kaupunki sinua pelkää.',
        4: 'Sillä olit turvana kurjalle, turvana köyhälle hänen ahdingossaan, suojana rankkasateelta ja varjona helteeltä. Sillä väkivaltaisten vihan vimma on kuin rankkasade seinää vasten.',
        5: 'Kuin helteen kuivassa maassa vaimensit muukalaisten melun. Kuin helle pilven varjossa vaipuu väkivaltaisten voittolaulu.',
        6: 'Herra Sebaot laittaa kaikille kansoille tällä vuorella pidot rasvasta, pidot viinistä, ydinrasvasta, puhtaasta viinistä.',
        7: 'Hän hävittää tällä vuorella verhon, joka verhoaa kaikki kansat, ja peiton, joka peittää kaikki kansakunnat.',
        8: 'Hän hävittää kuoleman ainiaaksi, ja Herra, Herra pyyhkii kyyneleet kaikkien kasvoilta ja ottaa pois kansansa häväistyksen kaikesta maasta. Sillä Herra on puhunut.',
        9: 'Sinä päivänä sanotaan: "Katso, tämä on Jumalamme, jota odotimme meitä pelastamaan; tämä on Herra, jota odotimme: iloitkaamme ja riemuitkaamme pelastuksesta, jonka hän toi."',
        10: 'Sillä Herran käsi lepää tällä vuorella. Mutta Mooab tallataan siihen paikkaansa, niin kuin oljet tallautuvat lantaveteen.',
        11: 'Hän haroo siinä käsiään, kuin uimari haroo uidessaan, mutta Herra painaa alas hänen ylpeytensä sekä hänen käsiensä rimpuilut.',
        12: 'Korkeitten muuriesi varustukset hän kukistaa, painaa ne alas ja syöksee maahan tomuun asti.',
    },
    26: {
        1: 'Sinä päivänä lauletaan Juudan maassa tätä laulua: "Meillä on vahva kaupunki. Pelastuksen hän on pannut sille muuriksi ja varustukseksi.',
        2: 'Avatkaa portit vanhurskaan kansan astua sisään, sen, joka pysyy uskollisena.',
        3: 'Säilytät eheän rauhan sille, joka sinussa pysyy, sillä hänen turvansa on sinussa.',
        4: 'Turvatkaa Herraan ainiaan, sillä Herra, Herra on iankaikkinen kallio.',
        5: 'Sillä hän on kukistanut korkealla asuvat, ylhäisen kaupungin. Hän painoi sen alas, painoi maan tasalle ja syöksi sen tomuun asti.',
        6: 'Sitä tallaa jalka, kurjan jalat, vaivaisten askeleet.',
        7: 'Vanhurskaan polku on suora, sinä teet vanhurskaan tien tasaiseksi.',
        8: 'Niin, sinun tuomioittesi tiellä odotamme sinua, Herra. Nimeäsi ja muistoasi sielu ikävöi.',
        9: 'Sieluni ikävöi sinua yöllä, henkeni sisimmässäni etsii sinua varhain. Sillä kun tuomiosi kohtaavat maata, maanpiirin asukkaat oppivat vanhurskautta.',
        10: 'Jos jumalaton saa armon, hän ei opi vanhurskautta. Oikeuden maassa hän tekee vääryyttä eikä näe Herran korkeutta.',
        11: 'Herra, kätesi on kohotettu, mutta he eivät sitä näe. He saakoot häpeäkseen nähdä kiivautesi kansan puolesta. Kuluttakoon heidät tuli, joka vihollisesi kuluttaa.',
        12: 'Herra, sinä saatat meille rauhan, sillä myös kaikki meidän tekomme sinä olet tehnyt.',
        13: 'Herra, meidän Jumalamme, meitä ovat vallinneet muut herrat, et sinä. Sinua yksin me ylistämme, sinun nimeäsi.',
        14: 'Kuolleet eivät virkoa eloon, vainajat eivät nouse: niin olet heille kostanut, tuhonnut heidät ja hävittänyt kaiken heidän muistonsa.',
        15: 'Olet lisännyt kansan, Herra, olet lisännyt kansan, olet kunniasi näyttänyt ja laajentanut kaikki maan rajat.',
        16: 'Herra, ahdistuksessa he ovat etsineet sinua, vuodattaneet hiljaisia rukouksia, kun heitä kuritit.',
        17: 'Kuin raskaana oleva vaimo, joka on synnyttämäisillään, vääntelehtii ja huutaa kivuissaan, niin olimme edessäsi, Herra.',
        18: 'Olimme raskaina, vääntelehdimme, mutta oli kuin olisimme synnyttäneet tuulta: emme saaneet aikaan pelastusta maalle eivätkä maanpiirin asukkaat synnyttäneet.',
        19: 'Mutta sinun kuolleesi virkoavat eloon, minun ruumiini nousevat ylös. Herätkää ja riemuitkaa, te jotka tomussa lepäätte, sillä kasteesi on valkeuksien kaste, ja maa tuo vainajat ilmoille.',
        20: 'Mene, kansani, kammioihisi ja sulje ovet jälkeesi, kätkeydy hetkeksi, kunnes viha on mennyt ohi.',
        21: 'Sillä katso, Herra lähtee asuinsijastaan kostamaan maan asukkaille heidän pahat tekonsa, ja maa paljastaa verivelkansa eikä enää peitä surmattujaan."',
    },
    27: {
        1: 'Sinä päivänä Herra kostaa kovalla, suurella ja väkevällä miekallaan leviatanille, kiitävälle käärmeelle, ja leviatanille, kiemurtelevalle käärmeelle, ja tappaa lohikäärmeen, joka on meressä.',
        2: 'Sinä päivänä sanotaan: "On viinitarha, parhaan viinin tarha. Laulakaa siitä:',
        3: "'Minä, Herra, olen sen vartija. Kastelen sitä hetkestä hetkeen. Vartioin sitä öin ja päivin, ettei mikään vahingoita sitä.",
        4: 'Vihaa minulla ei ole. Olisipa vain orjantappuroita ja ohdakkeita, niiden kimppuun kävisin sodalla ja polttaisin ne kaikki yhdessä –',
        5: 'tai säilyttäköön minut voimassani ja tehköön rauhan kanssani, tehköön rauhan kanssani.\'"',
        6: 'Tulevina aikoina juurtuu Jaakob, Israel kukkii ja kukoistaa ja täyttää maanpiirin hedelmällään.',
        7: 'Löikö hän sitä, kuten sen lyöjät lyötiin, tapettiinko se, kuten sen tappajat tapettiin?',
        8: 'Karkottamalla sen, lähettämällä sen pois rankaisit sitä. Hän pyyhkäisi sen pois kovalla myrskyllään itätuulen päivänä.',
        9: 'Sen tähden sovitetaan Jaakobin pahat teot sillä, ja se on hänen syntiensä poistamisen täysi hedelmä, että hän tekee kaikki alttarikivet rikottujen kalkkikivien kaltaisiksi: eivät kohoa enää aserat eivätkä auringonpatsaat.',
        10: 'Sillä varustettu kaupunki on autio. Se on hylätty maja, tyhjäksi jätetty kuin erämaa. Siellä vasikat käyvät laitumella. Ne siellä makailevat ja kaluavat sieltä kaikki vesat.',
        11: 'Kun oksat kuivuvat, ne taitetaan pois. Naiset tulevat ja tekevät niillä tulta. Sillä se ei ole ymmärtäväistä kansaa. Sen tähden sen tekijä ei armahda sitä eikä sen Luoja sääli sitä.',
        12: 'Sinä päivänä Herra karistaa hedelmät maahan Eufrat-virrasta aina Egyptin puroon asti, ja teidät, te israelilaiset, poimitaan talteen yksitellen.',
        13: 'Sinä päivänä puhalletaan suureen torveen, ja Assurin maahan häipyneet ja Egyptin maahan karkotetut tulevat ja kumartavat Herraa pyhällä vuorella Jerusalemissa.',
    },
    28: {
        1: 'Voi Efraimin juopuneitten ylvästä kruunua ja sen kunnian loisteen kuihtuvaa kukkaa, joka on kukkulan laella, viinistä päihtyneitten lihavan laakson keskellä!',
        2: 'Katso, Herralta tulee se, joka on väkevä ja voimakas, kuin raesade, rajumyrsky. Rankkasateen, väkevien tulvavetten kuohun tavoin hän kaataa pilvet voimalla tyhjäksi maahan.',
        3: 'Jalkoihin tallataan Efraimin juopuneitten ylväs kruunu.',
        4: 'Sen kunnian loisteen kuihtuvan kukan, joka on kukkulan laella, lihavan laakson keskellä, käy kuin varhaisviikunan ennen kesää: kuka vain sen näkee, tuskin se on hänen kourassaan, niin hän sen jo nielee.',
        5: 'Sinä päivänä Herra Sebaot on oleva loistava kruunu ja kunnian seppele kansansa jäännökselle',
        6: 'ja oikeuden henki sille, joka oikeutta istuu, ja voima niille, jotka torjuvat hyökkäyksen takaisin porttia kohden.',
        7: 'Nämäkin horjuvat viinistä ja hoipertelevat väkijuomasta. Väkijuomasta horjuu pappi ja profeetta. He ovat sekaisin viinistä, hoipertelevat väkijuomasta. He horjuvat näyissä, huojuvat tuomioissa.',
        8: 'Sillä täynnä oksennusta ja saastaa ovat kaikki pöydät – ei ole puhdasta paikkaa!',
        9: '"Keitähän tuokin luulee taitoon neuvovansa, keitä saarnalla opettavansa? Olemmeko me vasta maidosta vieroitettuja, äidin rinnoilta otettuja?',
        10: 'Käsky käskyn perään, käsky käskyn perään, höpötystä höpötyksen jälkeen, höpötystä höpötyksen jälkeen, milloin sitä, milloin tätä!" –',
        11: 'Niin, sopertavin huulin ja vieraalla kielellä hän on puhuva tälle kansalle,',
        12: 'hän, joka on sanonut heille: "Tässä on lepo; antakaa väsyneen levätä, tässä on levähdyspaikka." Mutta he eivät tahtoneet kuulla.',
        13: 'Niinpä Herran sana on oleva heille: "Käsky käskyn perään, käsky käskyn perään, höpötystä höpötyksen jälkeen, höpötystä höpötyksen jälkeen, milloin sitä, milloin tätä", niin että he kulkiessaan kaatuvat selälleen ja ruhjoutuvat, jotta heidät kiedotaan ja vangitaan.',
        14: 'Sen tähden kuulkaa Herran sana, te pilkkaajat, te jotka hallitsette tätä kansaa Jerusalemissa.',
        15: 'Koska te sanotte: "Olemme tehneet liiton kuoleman kanssa ja sopimuksen helvetin kanssa. Tulkoon vitsaus kuin tulva, se ei meitä saavuta, sillä olemme tehneet valheen turvaksemme ja piiloutuneet petokseen" –',
        16: 'sen tähden, näin sanoo Herra, Herra: Katso, lasken Siioniin peruskiven, koetellun kiven, kalliin kulmakiven, lujasti perustetun. Joka uskoo, se ei pakene.',
        17: "Panen oikeuden mittanuoraksi ja vanhurskauden vaa'aksi. Silloin rakeet hävittävät valheturvan, ja vedet huuhtovat pois piilopaikan.",
        18: 'Liittonne kuoleman kanssa pyyhkäistään pois, eikä teidän sopimuksenne helvetin kanssa kestä. Kun vitsaus tulee kuin tulva, se tallaa teidät maahan.',
        19: 'Niin usein kuin se tulee, tempaa se teidät valtaansa, sillä se tulee aamu aamulta, se tulee sekä päivällä että yöllä: totisesti, kauhuksi on tämän saarnan opetus.',
        20: 'Sillä vuode on oleva liian lyhyt ojentautua ja peitto liian kaita kääriytyä.',
        21: 'Sillä Herra nousee kuin Perasimin vuorella, hän kiivastuu kuin Gibeonin laaksossa tehdäkseen työnsä, oudon työnsä, ja toimittaakseen tekonsa, kumman tekonsa.',
        22: 'Älkää siis pilkatko, etteivät teidän siteenne vielä kiristyisi. Sillä Herralta Sebaotilta olen kuullut hävitys- ja tuomiopäätöksen, joka on kohtaava kaikkea maata.',
        23: 'Kuunnelkaa ja kuulkaa ääntäni, tarkatkaa ja kuulkaa sanojani.',
        24: 'Ainako kyntäjä kyntää, muokkaa ja äestää maataan saadakseen satoa?',
        25: 'Eikö niin: kun hän on tasoittanut sen pinnan, hän kylvää mustaa kuminaa, sirottelee maustekuminaa, panee vehnänjyvät riviin, ohran omaan paikkaansa ja spelttivehnää vierelle?',
        26: 'Hänen Jumalansa on neuvonut hänelle oikean tavan ja opettaa häntä.',
        27: 'Sillä ei mustaa kuminaa puida puimaäkeellä eikä puimajyrän tela pyöri maustekuminan yli, vaan musta kumina lyödään irti sauvalla ja maustekumina kepillä.',
        28: 'Puidaanko leipävilja murskaksi? Ei sitä kukaan pui loputtomiin eikä aina aja sen yli puimajyrällään ja hevosillaan. Sitä ei puida murskaksi.',
        29: 'Tämäkin on tullut Herralta Sebaotilta. Hänen neuvonsa on ihmeellinen ja ymmärryksensä hyvin suuri.',
    },
    29: {
        1: 'Voi Arielia, Arielia, kaupunkia, jonne Daavid asetti leirinsä! Liittäkää vuosi vuoteen, kiertäkööt juhlat kiertonsa,',
        2: 'ahdistan Arielia, ja se on oleva täynnä valitusta ja vaikerrusta. Se on oleva minulle kuin Jumalan uhriliesi.',
        3: 'Asetan leirini yltympäri sinua vastaan ja saarran sinut vartiostoilla ja luon vallit sinua vastaan.',
        4: 'Puhut maasta matalalta, sanasi tulevat vaimeina tomusta, sopertelet kuin vainajahenki maasta, puheesi tulee supisten tomusta.',
        5: 'Mutta sinun vainolaistesi lauma on oleva kuin hieno pöly, ja väkivaltaisten lauma kuin lentävät akanat, ja tämä tapahtuu äkkiä, silmänräpäyksessä:',
        6: 'Herra Sebaot etsii sinua ukkosenjylinässä ja maanjäristyksessä, kovassa pauhinassa, myrskyssä ja rajuilmassa, kuluttavan tulen liekissä.',
        7: 'Kuin yöllinen uninäky on oleva kansojen lauma, joka sotii Arielia vastaan, kaikki ne, jotka sotivat sitä ja sen varustuksia vastaan ja ahdistavat sitä.',
        8: 'Kuin nälkäinen on unissaan syövinään, mutta herää nälkä sydämessä, ja kuin janoinen on unissaan juovinaan, mutta herää, ja katso, hän on nääntynyt ja hänellä on kova jano, niin on oleva kaikki kansojen lauma, joka sotii Siionin vuorta vastaan.',
        9: 'Hämmästykää ja ihmetelkää, tuijottakaa itsenne sokeiksi ja sokeiksi jääkää! He ovat juovuksissa, vaikkeivät viinistä. He hoipertelevat, vaikkeivät väkijuomasta.',
        10: 'Sillä Herra on vuodattanut teidän päällenne raskaan unen hengen ja sulkenut teidän silmänne – profeettanne, ja peittänyt päänne – näkijänne.',
        11: 'Kaikki ilmoitus on teille kuin lukitun kirjan sanat. Jos se annetaan lukutaitoiselle ja sanotaan: "Lue tämä", hän vastaa: "En voi, sillä se on lukittu".',
        12: 'Jos taas kirja annetaan lukutaidottomalle ja sanotaan: "Lue tämä", hän vastaa: "En osaa lukea."',
        13: 'Niin Herra sanoi: Koska tämä kansa lähestyy minua suullaan ja kunnioittaa minua huulillaan, mutta pitää sydämensä minusta kaukana, ja koska heidän jumalanpelkonsa on vain opittuja ihmiskäskyjä,',
        14: 'sen tähden, katso, teen tälle kansalle vielä outoja tekoja – kummia ja ihmeitä, ja sen viisaitten viisaus häviää, ja sen ymmärtäväisten ymmärrys katoaa.',
        15: 'Voi niitä, jotka kätkevät syvälle hankkeensa Herralta, joiden teot tapahtuvat pimeässä ja jotka sanovat: "Kuka meidät näkee, kuka meistä tietää?"',
        16: 'Voi mielettömyyttänne! Onko savi savenvalajan veroinen? Ja sanooko työ tekijästään: "Ei hän ole minua tehnyt", tai sanooko kuva piirtäjästään: "Ei hän mitään ymmärrä"?',
        17: 'Vain lyhyt hetki enää, niin Libanon muuttuu puutarhaksi, ja puutarha on metsän veroinen.',
        18: 'Sinä päivänä kuurot kuulevat kirjan sanat, ja sokeiden silmät näkevät vapaina synkästä pimeydestä.',
        19: 'Nöyrät saavat yhä uutta iloa Herrassa, ja ihmisistä köyhimmätkin riemuitsevat Israelin Pyhästä.',
        20: 'Sillä väkivaltaisista on tullut loppu, pilkkaajat ovat hävinneet, ja kaikki vääryyteen valppaat on tuhottu,',
        21: 'ne, jotka sanallaan saattavat ihmisiä tekemään syntiä ja virittävät pauloja sille, joka oikeutta puolustaa portissa, ne, jotka vääntävät tekosyillä syyttömän asian vääräksi.',
        22: 'Sen tähden Herra, joka vapahti Aabrahamin, sanoo Jaakobin heimolle näin: Ei Jaakob enää joudu häpeään, eivätkä hänen kasvonsa enää kalpene.',
        23: 'Sillä kun hän näkee, kun hänen lapsensa näkevät keskellään kätteni työn, he pyhittävät nimeni, pitävät pyhänä Jaakobin Pyhän ja pelkäävät Israelin Jumalaa.',
        24: 'Silloin hengessään eksyvät käsittävät ymmärryksen ja kapinoivat ottavat opikseen.',
    },
    30: {
        1: 'Voi uppiniskaisia lapsia, sanoo Herra, niitä, jotka pitävät neuvoa, mikä ei ole minusta, ja hierovat liittoa ilman Henkeäni kooten syntiä synnin päälle.',
        2: 'Voi niitä, jotka menevät Egyptiin minulta kysymättä turvautuakseen faraoon ja etsiäkseen suojaa Egyptin varjossa!',
        3: 'Faraon turva koituu teille häpeäksi ja suojan etsiminen Egyptin varjosta häväistykseksi.',
        4: 'Sillä vaikka hänen ruhtinaansa ovat Sooanissa ja hänen sanansaattajansa ovat saapuneet Haanekseen asti,',
        5: 'he joutuvat kaikki häpeään kansan tähden, josta heillä ei ole hyötyä – ei apua, ei hyötyä, vaan häpeää ja pilkkaa.',
        6: 'Profeettasana Eteläisen maan Behemotia vastaan. Halki ahdingon ja ahdistuksen maan, halki naarasleijonan ja leijonan maan, kyykäärmeen ja lentävän käärmeen maan he kuljettavat aasinvarsojen selässä rikkautensa ja kamelien kyttyrällä aarteensa kansalle, josta ei ole hyötyä.',
        7: 'Egyptin apu on turha ja tyhjä; sen tähden annan sille nimen: "Rahab, joka ei pääse paikaltaan."',
        8: 'Mene siis nyt ja kirjoita se tauluun heidän läsnä ollessaan ja piirrä se kirjaan, että se säilyisi tuleviin aikoihin, ainiaan, ikuisesti.',
        9: 'Sillä he ovat niskoitteleva kansa. He ovat vilpillisiä lapsia, lapsia, jotka eivät tahdo kuulla Herran lakia,',
        10: 'jotka sanovat näkijöille: "Älkää nähkö", ja ennustajille: "Älkää ennustako meille tosia, puhukaa meille mieluisia, ennustakaa silmänlumeita.',
        11: 'Poiketkaa tieltä, väistykää polulta; viekää pois silmistämme Israelin Pyhä."',
        12: 'Sen tähden, näin sanoo Israelin Pyhä: Koska halveksitte tätä sanaa ja luotatte väkivaltaan ja vääryyteen ja turvaudutte siihen,',
        13: 'tämä synti on oleva kuin repeämä korkeassa muurissa, joka uhkaa sortua ja pullistuu. Se särkyy äkkiä, yhtäkkiä.',
        14: 'Se särkyy, kuin särkyy savenvalajan astia, joka lyödään rikki säälimättä, niin ettei sen sirpaleista löydy palasta, millä ottaa tulta liedestä tai ammentaa vettä altaasta.',
        15: 'Sillä näin sanoo Herra, Herra, Israelin Pyhä: Kääntymällä ja pysymällä hiljaa pelastutte, rauhallisuus ja luottamus on voimanne, mutta te ette tahtoneet,',
        16: 'vaan sanoitte: "Ei! Hevosilla tahdomme kiitää" – niinpä saatte kiitää pakoon. "Nopean selässä me tahdomme ratsastaa" – niinpä ovat vainoajanne nopeat.',
        17: 'Tuhat pakenee yhden uhkaa. Viiden uhkaa te pakenette, kunnes se, mikä teistä jää, on kuin merkkipuu vuoren huipulla, kuin lipputanko kukkulalla.',
        18: 'Sen tähden Herra odottaa antaakseen teille armonsa, sen tähden hän nousee armahtaakseen teitä, sillä Herra on oikeuden Jumala. Autuaita kaikki, jotka häntä odottavat!',
        19: 'Sinä kansa, joka asut Siionissa, Jerusalemissa, älä itke! Jo häneltä apua huutaessasi hän on sinulle totisesti armollinen. Sen kuullessaan hän jo vastaa sinulle.',
        20: 'Vaikka Herra antaa teille hädän leipää ja ahdistuksen vettä, niin opettajasi ei enää kätkeydy, vaan silmäsi saavat nähdä opettajasi.',
        21: 'Silloin korvasi kuulevat takaasi tämän sanan, milloin poikkeatte oikealle tai vasemmalle: "Tässä on tie, sitä kulkekaa."',
        22: 'Silloin sinä julistat saastaiseksi veistettyjen jumalankuviesi hopeapäällyksen ja valettujen jumalankuviesi kultakuoren. Sinä heität ne pois kuin jonkin inhottavan ja sanot niille: "Ulos!"',
        23: 'Hän antaa sateen siemenellesi, jonka kylvät maahan, ja maan sadosta leivän, joka on oleva mehevä ja lihava, ja karjasi on sinä päivänä käyvä laajalla laitumella.',
        24: 'Härät ja aasinvarsat, jotka tekevät peltotyötä, syövät suolaista rehuviljaa, joka on viskattu hangolla ja viskimellä.',
        25: 'Silloin kaikilla korkeilla vuorilla ja kaikilla ylhäisillä kukkuloilla on oleva puroja, vesivirtoja, suuren surmaamisen päivänä tornien sortuessa.',
        26: 'Silloin kuun valo on oleva kuin auringon valo, ja auringon valo on oleva seitsenkertainen. Se on oleva kuin seitsemän päivän valo, sinä päivänä, jona Herra sitoo kansansa vammat ja parantaa siihen isketyt haavat.',
        27: 'Katso, Herran nimi tulee kaukaa. Hänen vihansa leimuaa. Sankka savu tupruaa. Hänen huulensa ovat täynnä vihaa, ja hänen kielensä on kuin kuluttava tuli.',
        28: 'Hänen hengityksensä on kuin virta, joka tulvii ja ulottuu kaulaan asti. Se seuloo kansoja turmion seulalla ja panee eksyttävät suitset kansakuntien suupieliin.',
        29: 'Te veisaatte kuin yöllä, kun pyhä juhla alkaa, ja sydämenne riemuitsee niin kuin sen, joka huilujen soidessa astuu vaeltaen Herran vuorelle, Israelin kalliolle.',
        30: 'Herra antaa kuulla äänensä voiman ja nähdä käsivartensa laskeutuvan alas vihan tuimuudessa ja kuluttavan tulen liekissä, myrskysateina, rankkasateena ja raekivinä.',
        31: 'Sillä Herran äänestä pelästyy Assur. Hän lyö vitsalla.',
        32: 'Silloin jokaisella ruoskan iskulla, jolla Herra häntä satuttaa, soivat tamburiinit ja harput, ja hän sotii häntä vastaan, sotii kättä heiluttaen.',
        33: 'Sillä jo aikoja sitten on polttopaikka valmistettu. Kuninkaallekin se on varattu. Syvä ja leveä on sen valkea, tulta ja polttopuita on paljon. Herran Henki sytyttää sen kuin laavavirta.',
    },
    31: {
        1: 'Voi niitä, jotka menevät alas Egyptiin etsimään apua ja turvautuvat hevosiin, luottavat sotavaunuihin, koska niitä on paljon, ja ratsumiehiin, koska niiden lukumäärä on hyvin suuri, mutta eivät katso Israelin Pyhään eivätkä kysy neuvoa Herralta.',
        2: 'Mutta myös hän on viisas ja tuottaa onnettomuuden. Hän ei peruuta sanojaan, vaan nousee pahantekijöiden sukua vastaan ja väärintekijöiden apuun tuloa vastaan.',
        3: 'Egypti on ihminen eikä Jumala, ja heidän hevosensa ovat lihaa eivätkä henkeä. Kun Herra ojentaa kätensä, suistuu auttaja, ja autettava kaatuu, ja yhdessä he kumpikin hukkuvat.',
        4: 'Sillä näin on Herra minulle sanonut: Niin kuin leijona, nuori leijona, murisee saaliinsa ääressä, kun sitä vastaan hälytetään paimenten täysi joukko, eikä pelästy heidän huutoaan, ei huoli heidän hälinästään, niin Herra Sebaot on astuva alas sotimaan Siionin vuorelle ja sen kukkulalle.',
        5: 'Kuin liitelevät linnut, niin Herra Sebaot varjelee Jerusalemia – varjelee ja pelastaa, säästää ja vapahtaa.',
        6: 'Palatkaa, te israelilaiset, hänen luokseen, josta olette niin kauas luopuneet.',
        7: 'Sillä sinä päivänä jokainen hylkää hopeiset ja kultaiset epäjumalansa, jotka kätenne ovat tehneet teille synniksi.',
        8: 'Silloin Assur kaatuu miekkaan, joka ei ole miehen, ja hänet syö miekka, joka ei ole ihmisen. Hän pakenee miekkaa, ja hänen nuorukaisensa joutuvat työorjuuteen.',
        9: 'Hänen kallionsa kukistuu kauhusta, ja hänen ruhtinaansa säikkyvät lipun luota pakoon, sanoo Herra, jonka tuli on Siionissa ja ahjo Jerusalemissa.',
    },
    32: {
        1: 'Katso, kuningas on hallitseva vanhurskaudessa, ja valtiaat vallitsevat oikeuden mukaan.',
        2: 'Jokainen heistä on oleva turvana tuulelta ja suojana rankkasateelta, kuin vesipurot kuivassa maassa, kuin korkean kallion varjo nääntyvässä maassa.',
        3: 'Näkevien silmät eivät ole sokaistut, ja kuulevien korvat kuulevat tarkasti.',
        4: 'Ajattelemattomien sydän käsittää taidon, ja änkyttävien kieli puhuu sujuvasti ja selkeästi.',
        5: 'Houkkaa ei enää kutsuta jaloksi eikä petollista enää sanota yleväksi.',
        6: 'Sillä houkka puhuu houkan lailla, ja hänen sydämensä hankkii turmiota, ja niin hän harjoittaa riettautta ja puhuu eksyttävästi Herrasta, jättää tyhjäksi nälkäisen sielun ja janoisen juomaa vaille.',
        7: 'Pahat ovat petollisen aseet, hän miettii ilkitöitä tuhotakseen kurjat valheen sanoilla, vaikka köyhä puhuisi miten oikeaa asiaa tahansa.',
        8: 'Mutta jalo miettii jaloja ja pysyy lujana jaloudessa.',
        9: 'Nouskaa, te suruttomat naiset, kuulkaa ääntäni; te huolettomat tyttäret, tarkatkaa sanojani.',
        10: 'Vielä vuosi ja joitakin päiviä sen päälle, niin vapisette, te huolettomat. Sillä silloin on viininkorjuusta tullut loppu, hedelmänkorjuuta ei tule.',
        11: 'Kauhistukaa, te suruttomat, vaviskaa, te huolettomat, riisuutukaa, paljastukaa, vyöttäkää säkki lanteillenne.',
        12: 'Silloin valitetaan ja lyödään rintoihin ihanien peltojen tähden ja hedelmällisten viiniköynnösten tähden,',
        13: 'kansani maan tähden, joka kasvaa orjantappuraa ja ohdaketta, remuavan kaupungin kaikkien iloisten talojen tähden.',
        14: 'Sillä palatsi on hylätty, kaupungin kohina lakannut, Oofel ja vartiotorni ovat jääneet ikuisesti luoliksi, villiaasien iloksi ja laumojen laitumeksi.',
        15: 'Näin on siihen asti, kunnes päällemme vuodatetaan Henki korkeudesta. Silloin erämaa muuttuu puutarhaksi,',
        16: 'ja puutarha on metsän veroinen. Silloin erämaassa asuu oikeus ja puutarhassa asustaa vanhurskaus.',
        17: 'Silloin vanhurskauden hedelmä on rauha, vanhurskauden vaikutus on lepo ja turvallisuus iankaikkisesti.',
        18: 'Silloin kansani asuu rauhan majoissa, turvallisissa asunnoissa, huolettomissa lepopaikoissa.',
        19: 'Mutta raesade tulee, metsä kaatuu, ja kaupunki alennetaan alhaiseksi.',
        20: 'Onnelliset te, jotka kylvätte kaikkien vetten vierille ja laskette härän ja aasin jalat kulkemaan valtoimina!',
    },
    33: {
        1: 'Voi sinua hävittäjää, sinua, jota itseäsi ei ole hävitetty, sinua ryöstäjää, jota kukaan ei ole ryöstänyt! Kun olet saanut päätökseen hävitystyösi, hävitetään sinut, kun olet ryöstösi ryöstänyt, ryöstetään sinut.',
        2: 'Herra, armahda meitä, sinua me odotamme. Ole näiden käsivarsi joka aamu, ole apumme hädän aikana.',
        3: 'Kansat pakenevat jyrinäsi ääntä. Kun sinä nouset, hajoavat kansakunnat.',
        4: 'Saaliinne viedään, niin kuin tuhosirkat vievät. Niin kuin hyppysirkat hyökkäävät, niin sen kimppuun hyökätään.',
        5: 'Herra on korkea, sillä hän asuu korkeudessa. Hän täyttää Siionin oikeudella ja vanhurskaudella.',
        6: 'Silloin hän on sinun aikojesi vakuus, avun runsaus, viisaus ja ymmärrys. Herran pelko on oleva Siionin aarre.',
        7: 'Katso, sankarit huutavat ulkona, rauhan sanansaattajat itkevät katkerasti.',
        8: 'Tiet ovat autioina, polulta on kulkija poissa. Hän on rikkonut liiton, ylenkatsonut kaupungit, ei ole pitänyt ihmistä minään.',
        9: 'Maa murehtii ja nääntyy, Libanon kuihtuu häpeästä, Saaron on aromaaksi tullut, Baasan ja Karmel varistavat lehtensä.',
        10: 'Nyt nousen, sanoo Herra, nyt korotan itseni, nyt kohoan korkealle.',
        11: 'Olkia te kannatte kohdussanne, akanoita synnytätte. Teidän kiukkunne on tuli, joka kuluttaa teidät.',
        12: 'Kansat poltetaan kuin kalkki, kuin katkotut orjantappurat, jotka palavat tulessa.',
        13: 'Kuulkaa, te kaukaiset, mitä olen tehnyt, te lähellä olevat, tuntekaa voimani.',
        14: 'Syntiset Siionissa pelästyvät, vapina valtaa jumalattomat: "Kuka meistä voi asua kuluttavassa tulessa, kuka asua iankaikkisessa hehkussa?"',
        15: 'Joka vanhurskaudessa vaeltaa ja puhuu sitä, mikä on oikein, joka halveksii väärää voittoa, jonka käsi torjuu lahjukset luotaan, joka tukkii korvansa kuulemasta veritöitä ja sulkee silmänsä näkemästä pahaa,',
        16: 'hän on asuva kukkuloilla, kalliolinnat ovat hänen turvansa, hänelle annetaan hänen leipänsä, eikä vesi häneltä ehdy.',
        17: 'Silmäsi saavat katsoa kuningasta hänen ihanuudessaan. Ne saavat nähdä avaran maan.',
        18: 'Sydämesi muistelee kauhuja: missä on nyt veronlaskija, missä punnitsija, missä tornien lukija?',
        19: 'Et näe enää sitä röyhkeää kansaa, kansaa, jolla on outo, käsittämätön puhe, jonka sopertavaa kieltä ei kukaan ymmärrä.',
        20: 'Katso Siionia, juhliemme kaupunkia. Silmäsi näkevät Jerusalemin, rauhan asuinsijan, telttamajan, jota ei muuteta, jonka vaarnoja ei ikinä reväistä irti, jonka köysistä ei katkaista yhtään.',
        21: 'Sillä voimallinen meillä on siellä Herra, siellä ovat joet, ovat virrat, leveät rannasta toiseen, joita ei kulje soutualus, joiden poikki ei pääse uljas laiva.',
        22: 'Sillä Herra on tuomarimme, Herra on johdattajamme, Herra on kuninkaamme. Hän pelastaa meidät.',
        23: 'Nyt ovat köytesi höltyneet. Ne eivät pidä mastoa kannassaan kiinni eivätkä vedä lippua liehumaan. Mutta silloin jaetaan riistosaalista runsaasti, rammatkin ryöstävät ja raastavat.',
        24: 'Eikä yksikään asukas sano: "Minä olen vaivanalainen." Kansa, joka siellä asuu, on saanut syntinsä anteeksi.',
    },
    34: {
        1: 'Astukaa esiin, te kansat, ja kuulkaa; te kansakunnat, ottakaa varteen. Kuulkoon maa ja kaikki, mitä siinä on, maanpiiri ja kaikki, mikä siitä kasvaa.',
        2: 'Sillä Herra on vihastunut kaikkiin kansoihin ja kiivastunut kaikkiin heidän joukkoihinsa. Hän on vihkinyt heidät tuhon omiksi, jättänyt heidät teurastettaviksi.',
        3: 'Heidän surmattunsa heitetään pois, ja niiden raadoista nousee löyhkä, ja vuoret valuvat heidän vertaan.',
        4: 'Kaikki taivaan joukot menehtyvät, taivas kääritään kokoon kuin kirja, ja kaikki sen joukot varisevat alas, niin kuin lehdet varisevat viinipuusta, niin kuin raakileet viikunapuusta.',
        5: 'Sillä miekkani taivaassa on juopunut. Katso, se iskee alas Edomiin tuomioksi kansalle, jonka olen vihkinyt tuhoon.',
        6: 'Herran miekka on verta täynnä, rasvaa helmeilevä, karitsojen ja kauristen verta, pässien munuaisrasvaa. Sillä Herralla on uhri Bosrassa, suuri teurastus Edomin maassa.',
        7: "Re'eem-eläimiä kaatuu yhteen joukkoon, mulleja härkien mukana. Heidän maansa juopuu verestä, ja heidän multansa helmeilee rasvaa.",
        8: 'Sillä Herralla on koston päivä, maksun vuosi Siionin asian puolesta.',
        9: 'Edomin purot muuttuvat pieksi ja sen multa laavaksi, sen maa tulee palavaksi pieksi.',
        10: 'Se ei sammu yöllä eikä päivällä, iäti nousee siitä savu. Se on oleva raunioina polvesta polveen, siellä ei kulje kukaan, iankaikkisesta iankaikkiseen.',
        11: 'Sen perivät pelikaanit ja siilit, pöllöt ja korpit asuvat siellä. Hän vetää sen yli autiuden mittanuoran ja tyhjyyden luotilangan.',
        12: 'Siellä ei ole enää ylimyksiä huutamassa ketään kuninkaaksi, kaikki sen ruhtinaat ovat poissa.',
        13: 'Sen palatsit kasvavat orjantappuroita, sen linnat nokkosia ja ohdakkeita. Siitä tulee sakaalien asunto ja strutsien tyyssija.',
        14: 'Siellä erämaan eläimet ja sakaalit yhtyvät, vuohipukit tapaavat toisiaan. Siellä öinen kulkija saa yksin rauhan ja löytää lepopaikan.',
        15: 'Siellä nuolikäärme pesii ja laskee munansa, kuorii ne ja kiertyy kerälle pimentoonsa. Sinne haarahaukatkin kokoontuvat yhteen.',
        16: 'Etsikää Herran kirjasta ja lukekaa: näistä ei tule puuttumaan yhtään eikä yksikään ole toistaan kaipaava. – "Sillä minun suuni on niin käskenyt." – Hänen Henkensä on koonnut ne yhteen.',
        17: 'Hän on heittänyt arpaa niiden kesken, ja hänen kätensä on jakanut sen niille mittanuoralla. Ne perivät sen ikiajoiksi ja asuvat siellä polvesta polveen.',
    },
    35: {
        1: 'Erämaa ja kuiva hietikko iloitsevat, aromaa riemuitsee ja kukoistaa kuin lilja.',
        2: 'Se kukoistaa kauniisti ja iloitsee ilolla ja riemulla. Sille annetaan Libanonin kunnia, Karmelin ja Saaronin ihanuus. He saavat nähdä Herran kunnian, Jumalamme ihanuuden.',
        3: 'Vahvistakaa hervonneet kädet, voimistakaa horjuvat polvet.',
        4: 'Sanokaa hätääntyneille sydämille: "Olkaa lujat, älkää pelätkö. Katso, teidän Jumalanne! Kosto tulee, Jumalan rangaistus. Hän tulee ja pelastaa teidät."',
        5: 'Silloin avautuvat sokeiden silmät ja kuurojen korvat aukeavat.',
        6: 'Silloin rampa hyppii kuin peura ja mykän kieli ratkeaa riemuun, sillä erämaahan puhkeavat vedet ja aromaahan purot.',
        7: 'Hehkuva hiekka tulee lammikoiksi ja kuiva maa vesilähteiksi. Sakaalien asunnossa, missä ne makasivat, kasvaa ruoho sekä ruoko ja kaisla.',
        8: 'Silloin siellä on oleva valtatie, ja sen nimi on "pyhä tie". Sitä ei kulje saastainen. Se on heitä itseään varten. Se, joka sitä tietä kulkee, ei eksy – eivät hullutkaan.',
        9: 'Ei siellä ole leijonaa, ei sinne nouse raateleva peto. Sellaista siellä ei tavata. Lunastetut sitä kulkevat.',
        10: 'Herran vapahdetut palaavat ja tulevat Siioniin riemuiten päänsä päällä iankaikkinen ilo. Riemu ja ilo saavuttavat heidät, mutta murhe ja huokaus pakenevat.',
    },
    36: {
        1: 'Kuningas Hiskian neljäntenätoista hallitusvuotena hyökkäsi Sanherib, Assurin kuningas, kaikkien Juudan varustettujen kaupunkien kimppuun ja valloitti ne.',
        2: 'Assurin kuningas lähetti Laakiista Rabsaken suuren sotajoukon kanssa kuningas Hiskiaa vastaan Jerusalemiin ja [Rabsake] pysähtyi Ylälammikon vesijohdolle, joka on Vanuttajankedon tien varrella.',
        3: 'Eljakim, Hilkian poika, joka oli palatsin päällikkönä, ja kirjuri Sebna ja kansleri Jooah, Aasafin poika, menivät hänen luokseen.',
        4: 'Rabsake sanoi heille: "Sanokaa Hiskialle: Näin sanoo suurkuningas, Assurin kuningas: \'Mitä on tuo luottamus, joka sinulla on?',
        5: 'Sanon: pelkkää huulten puhetta on tuollainen neuvo ja voima sodankäyntiin. Keneen sinä oikein luotat, kun kapinoit minua vastaan?',
        6: 'Katso, sinä luotat Egyptiin, tuohon särkyneeseen ruokosauvaan, joka tunkeutuu sen käteen, joka siihen nojaa, ja lävistää sen. Sellainen on farao, Egyptin kuningas, kaikille, jotka häneen luottavat.',
        7: "Vai sanotko ehkä minulle: Me luotamme Herraan, Jumalaamme? Mutta eikö hän ole se, jonka uhrikukkulat ja alttarit Hiskia poisti, kun hän sanoi Juudalle ja Jerusalemille: Tämän alttarin edessä on teidän kumartaen rukoiltava?'",
        8: 'Mutta lyö nyt vetoa herrani, Assurin kuninkaan, kanssa: annan sinulle kaksi tuhatta hevosta, jos voit antaa niille ratsastajat.',
        9: 'Kuinka sitten voisit torjua ainoankaan käskynhaltijan, ainoankaan herrani vähimmän palvelijan, hyökkäyksen? Mutta sinä luotat Egyptiin, sen vaunuihin ja ratsumiehiin.',
        10: 'Olenko nyt Herran sallimatta hyökännyt tähän maahan hävittämään sitä? Herra itse on sanonut minulle: \'Hyökkää tähän maahan ja hävitä se.\'"',
        11: 'Eljakim, Sebna ja Jooah sanoivat Rabsakelle: "Puhu palvelijoillesi aramin kieltä, sillä me ymmärrämme sitä; älä puhu meille juudan kieltä kansan kuullen, jota on muurilla."',
        12: 'Mutta Rabsake vastasi: "Onko herrani lähettänyt minut puhumaan näitä sanoja herrallesi ja sinulle? Eikö juuri niille miehille, jotka istuvat muurilla ja joutuvat kanssanne syömään omaa likaansa ja juomaan omaa vettänsä?"',
        13: 'Sitten Rabsake astui esiin, huusi kovalla äänellä juudan kielellä ja sanoi: "Kuulkaa suurkuninkaan, Assurin kuninkaan, sanoja.',
        14: "Näin sanoo kuningas: 'Älkää antako Hiskian pettää itseänne, sillä hän ei voi teitä pelastaa.",
        15: 'Älköön Hiskia saako teitä luottamaan Herraan, kun hän sanoo: Herra on varmasti pelastava meidät. Tätä kaupunkia ei anneta Assurin kuninkaan käsiin.',
        16: "Älkää kuulko Hiskiaa.' Sillä Assurin kuningas sanoo näin: 'Tehkää sovinto kanssani ja antautukaa minulle, niin saatte syödä kukin viinipuustanne ja viikunapuustanne ja juoda kukin kaivostanne,",
        17: 'kunnes tulen ja vien teidät maahan, joka on teidän maanne kaltainen, vilja- ja viinimaahan, leivän ja viinitarhojen maahan.',
        18: 'Älköön Hiskia vietelkö teitä, sanoessaan: Herra pelastaa meidät. Onko muidenkaan kansojen jumalista kukaan pelastanut maatansa Assurin kuninkaan käsistä?',
        19: 'Missä ovat Hamatin ja Arpadin jumalat? Missä ovat Sefarvaimin jumalat? Ovatko ne pelastaneet Samariaa minun käsistäni?',
        20: 'Kuka näiden maiden kaikista jumalista on pelastanut maansa käsistäni? Kuinka sitten Herra pelastaisi Jerusalemin käsistäni?\'"',
        21: 'Mutta he olivat vaiti eivätkä vastanneet hänelle mitään, sillä kuningas oli käskenyt niin ja sanonut: "Älkää vastatko hänelle."',
        22: 'Sitten palatsin päällikkö Eljakim, Hilkian poika, ja kirjuri Sebna ja kansleri Jooah, Aasafin poika, tulivat Hiskian luo vaatteet reväistyinä ja kertoivat hänelle, mitä Rabsake oli sanonut.',
    },
    37: {
        1: 'Kun kuningas Hiskia kuuli sen, hän repäisi vaatteensa, pukeutui säkkiin ja meni Herran temppeliin.',
        2: 'Hän lähetti palatsin päällikön Eljakimin ja kirjuri Sebnan sekä pappien vanhimmat säkkeihin puettuina profeetta Jesajan, Aamosin pojan, luo.',
        3: 'He sanoivat hänelle: "Näin sanoo Hiskia: \'Hädän, kurituksen ja häväistyksen päivä on tämä päivä, sillä lapset ovat tulleet kohdun suulle saakka, mutta ei ole voimaa synnyttää.',
        4: 'Ehkä Herra, Jumalasi, kuulee Rabsaken sanat, joilla hänen herransa, Assurin kuningas, on lähettänyt hänet herjaamaan elävää Jumalaa, ja rankaisee häntä näistä sanoista, jotka Herra, Jumalasi, on kuullut. Kohota nyt rukous jäännöksen puolesta, joka vielä on olemassa.\'"',
        5: 'Kun kuningas Hiskian palvelijat tulivat Jesajan luo,',
        6: 'Jesaja sanoi heille: "Näin sanokaa herrallenne: \'Näin sanoo Herra: Älä pelkää niitä sanoja, jotka olet kuullut ja joilla Assurin kuninkaan poikaset ovat häväisseet minua.',
        7: 'Katso, annan sellaisen hengen mennä häneen, että hän kuultuaan sanoman palaa omaan maahansa. Annan hänen kaatua miekkaan omassa maassaan.\'"',
        8: 'Niin Rabsake kääntyi takaisin ja tapasi Assurin kuninkaan sotimassa Libnaa vastaan. Hän oli näet kuullut, että tämä oli lähtenyt pois Laakiista.',
        9: 'Mutta kun Sanherib kuuli Tirhakasta, Kuusin kuninkaasta, sanottavan: "Hän on lähtenyt liikkeelle sotiakseen sinua vastaan", hän sen kuultuaan lähetti sanansaattajat Hiskian luo ja käski sanoa:',
        10: '"Sanokaa näin Hiskialle, Juudan kuninkaalle: \'Älä anna Jumalasi, johon luotat, pettää itseäsi äläkä ajattele: Jerusalem ei joudu Assurin kuninkaan käsiin.',
        11: 'Olethan kuullut, mitä Assurin kuninkaat ovat tehneet kaikille maille, kuinka he ovat vihkineet ne tuhon omiksi. Sinäkö pelastuisit!',
        12: 'Ovatko kansojen jumalat pelastaneet niitä, jotka isäni ovat tuhonneet: Goosania, Harrania, Resefiä ja Telassarin edeniläisiä?',
        13: 'Missä on Hamatin kuningas ja Arpadin kuningas, Sefarvaimin kaupungin, Heenan ja Ivvan kuningas?\'"',
        14: 'Kun Hiskia oli ottanut kirjeen sanansaattajilta ja lukenut sen, hän meni Herran temppeliin, ja Hiskia levitti sen Herran eteen.',
        15: 'Sitten Hiskia rukoili Herraa ja sanoi:',
        16: '" Herra Sebaot, Israelin Jumala, jonka valtaistuinta kerubit kannattavat, sinä yksin olet maan kaikkien valtakuntien Jumala. Sinä olet tehnyt taivaan ja maan.',
        17: 'Herra, kallista korvasi ja kuule; Herra, avaa silmäsi ja katso. Kuule kaikki Sanheribin sanat, jotka hän lähetti herjatakseen elävää Jumalaa.',
        18: 'Se on totta, Herra, että Assurin kuninkaat ovat hävittäneet kaikki maat ja omankin maansa.',
        19: 'He ovat heittäneet niiden jumalat tuleen, sillä ne eivät olleet jumalia, vaan ihmiskätten tekoa, puuta ja kiveä, ja sen tähden he saattoivat hävittää ne.',
        20: 'Mutta pelasta nyt meidät, Herra, Jumalamme, hänen käsistään, että kaikki maan valtakunnat tietäisivät, että sinä, Herra, olet ainoa."',
        21: 'Jesaja, Aamosin poika, lähetti Hiskialle tämän sanan: "Näin sanoo Herra, Israelin Jumala: Koska olet rukoillut minua avuksi Sanheribia, Assurin kuningasta, vastaan,',
        22: 'niin tämä on se sana, jonka Herra on puhunut hänestä: Neitsyt, tytär Siion, halveksii ja pilkkaa sinua. Tytär Jerusalem nyökyttää ilkkuen päätään sinun jälkeesi.',
        23: 'Ketä olet herjannut ja häväissyt, ja ketä vastaan olet korottanut äänesi? Korkealle olet kohottanut silmäsi Israelin Pyhää vastaan.',
        24: "Palvelijaisi kautta sinä herjasit Herraa ja sanoit: 'Monilla vaunuillani minä nousin vuorten harjalle Libanonin ääriin saakka ja hakkasin maahan sen korkeat setrit, sen parhaat sypressit, ja tunkeuduin sen etäisimmälle harjalle, sen rehevimpään metsään.",
        25: "Minä kaivoin kaivoja ja join kuiviin vedet, ja jalkapohjallani kuivasin kaikki Egyptin virrat.'",
        26: 'Etkö ole kuullut: kauan sitten olen tätä valmistellut, muinaisuudesta saakka olen tämän aikonut tehdä! Nyt olen sen toteuttanut, ja niin hävitit varustetut kaupungit autioiksi kivikasoiksi.',
        27: 'Niiden asukkaat olivat voimattomia, kauhistuivat ja joutuivat häpeään. Heidän kävi kuin kedon ruohon ja kuin vihannan heinän, kuin katolla kasvavien korsien ja kuin laihon ennen oljelle tulemista.',
        28: 'Istuitpa tai lähdit tai tulit, sen tiedän, niin kuin senkin, että raivoat minua vastaan.',
        29: 'Koska minua vastaan raivoat ja koska ylpeytesi on tullut korviini, panen koukkuni nenääsi ja suitseni suuhusi ja vien sinut takaisin samaa tietä, jota tulitkin.',
        30: 'Tämä on oleva sinulle merkkinä: tänä vuonna syödään jälkikasvua ja toisena vuonna kylvämättä kasvanutta, mutta kolmantena vuonna kylväkää ja leikatkaa, istuttakaa viinitarhoja ja syökää niiden hedelmää.',
        31: 'Juudan heimon pelastuneet, jotka ovat jääneet jäljelle, tekevät taas juurta alaspäin ja hedelmää ylöspäin.',
        32: 'Sillä Jerusalemista lähtee kasvamaan jäännös, pelastunut joukko Siionin vuorelta. Herran Sebaotin kiivaus on sen tekevä.',
        33: 'Sen tähden, näin sanoo Herra Assurin kuninkaasta: Hän ei tule tähän kaupunkiin eikä ammu siihen nuolia. Hän ei tuo sitä vastaan kilpeä eikä luo sitä vastaan vallia.',
        34: 'Samaa tietä, jota hän tuli, hän palaa, mutta tähän kaupunkiin hän ei tule, sanoo Herra.',
        35: 'Sillä varjelen tämän kaupungin ja pelastan sen itseni tähden ja palvelijani Daavidin tähden."',
        36: 'Herran enkeli lähti ja löi Assurin leirissä sata kahdeksankymmentä viisi tuhatta miestä, ja kun noustiin aamulla varhain, katso, he olivat kaikki kuolleina ruumiina.',
        37: 'Silloin Sanherib, Assurin kuningas, lähti liikkeelle ja meni pois. Hän palasi maahansa ja jäi Niiniveen.',
        38: 'Mutta kerran kun hän oli rukoilemassa jumalansa Nisrokin temppelissä, surmasivat hänen poikansa Adrammelek ja Sareser hänet miekalla. Sitten he pakenivat Araratin maahan. Silloin hänen poikansa Eesarhaddon tuli kuninkaaksi hänen sijaansa.',
    },
    38: {
        1: 'Niihin aikoihin Hiskia sairastui ja oli kuolemaisillaan; ja profeetta Jesaja, Aamosin poika, tuli hänen luokseen ja sanoi hänelle: "Näin sanoo Herra: Järjestä asiasi; sillä sinä kuolet etkä enää parane."',
        2: 'Hiskia käänsi kasvonsa seinään päin ja rukoili Herraa',
        3: 'ja sanoi: "Oi Herra, muista, kuinka olen vaeltanut edessäsi uskollisesti ja ehyellä sydämellä ja tehnyt sitä, mikä on hyvää silmissäsi!" Ja Hiskia itki katkerasti.',
        4: 'Jesajalle tuli tämä Herran sana, ja se kuului:',
        5: '"Mene ja sano Hiskialle: \'Näin sanoo Herra, sinun isäsi Daavidin Jumala: Olen kuullut rukouksesi ja nähnyt kyyneleesi. Katso, lisään päiviisi viisitoista vuotta',
        6: 'ja pelastan sinut ja tämän kaupungin Assurin kuninkaan käsistä ja varjelen tämän kaupungin.',
        7: 'Tämä on oleva sinulle merkkinä Herralta siitä, että Herra tekee, mitä on sanonut:',
        8: 'katso, annan aurinkokellon varjon siirtyä takaisin kymmenen astetta, jotka se jo on auringon mukana laskeutunut Aahaan aurinkokellossa.\'" Niin aurinko siirtyi aurinkokellossa takaisin kymmenen astetta, jotka se jo oli laskeutunut.',
        9: 'Hiskian, Juudan kuninkaan, kirjoittama laulu, kun hän oli ollut sairaana ja toipunut taudistaan:',
        10: '"Minä sanoin: Kesken rauhallisten päivieni minun on mentävä haudan porteista. Jäljellä olevat vuoteni on minulta riistetty pois.',
        11: 'Sanoin: En saa enää nähdä Herraa, Herraa elävien maassa, enkä enää katsella ihmisiä maailman asukkaiden joukossa.',
        12: 'Majani puretaan ja viedään minulta pois kuin paimenen teltta. Olen kutonut loppuun elämäni kuin kankuri kankaansa, minut leikataan irti loimilangoista. Ennen kuin päivä muuttuu yöksi, teet minusta lopun.',
        13: 'Rauhoittelin itseäni aamuun asti – kuin leijona hän murskaa kaikki luuni. Ennen kuin päivä vaihtuu yöksi, teet minusta lopun.',
        14: 'Kuin pääskynen, kuin kurki valitan, kujerran kuin kyyhkynen. Voipuen katsovat silmäni korkeuteen. Herra, minulla on ahdistus, puolusta minua.',
        15: 'Mitä nyt sanonkaan? Hän lupasi minulle ja täytti myös: vaellan hiljaisesti kaikki elämäni vuodet sieluni murheen tähden.',
        16: 'Herra, tämänkaltaiset ovat elämäksi, ja niissä on koko henkeni elämä. Sinä teet minut terveeksi. Suo minun elää.',
        17: 'Katso, onneksi muuttui minulle katkera murhe: sinä rakastit sieluani, nostit sen kadotuksen kuopasta, sillä sinä heitit kaikki syntini selkäsi taakse.',
        18: 'Sillä ei hauta sinua kiitä, ei kuolema sinua ylistä. Hautaan vaipuneet eivät pane toivoaan totuuteesi.',
        19: 'Elävät, elävät sinua kiittävät, kuten minä tänä päivänä. Isä ilmoittaa lapsilleen totuutesi.',
        20: 'Herra on auttajani. Lyyrani soittoja soittakaamme kaikkina elinpäivinämme Herran temppelissä."',
        21: 'Jesaja käski tuoda viikunakakkua ja hautoa paisetta, että hän tulisi terveeksi.',
        22: 'Hiskia sanoi: "Mikä merkki tämä onkaan, että voin mennä Herran temppeliin!"',
    },
    39: {
        1: 'Siihen aikaan Merodak-Baladan, Baladanin poika, Baabelin kuningas, lähetti kirjeen ja lahjoja Hiskialle, kun oli kuullut hänen olleen sairaana ja parantuneen.',
        2: 'Hiskia iloitsi lähettiläistä ja näytti heille varastohuoneen, hopean ja kullan, hajuaineet ja kalliin öljyn ja koko asehuoneensa ja kaikki, mitä hänen aarrekammioissaan oli. Hiskian talossa ei ollut mitään eikä koko hänen valtakunnassaan, mitä hän ei olisi heille näyttänyt.',
        3: 'Mutta profeetta Jesaja tuli kuningas Hiskian luo ja sanoi hänelle: "Mitä nämä miehet ovat sanoneet, ja mistä he ovat tulleet luoksesi?" Hiskia vastasi: "He ovat tulleet luokseni kaukaisesta maasta, Baabelista."',
        4: 'Hän sanoi: "Mitä he ovat nähneet talossasi?" Hiskia vastasi: "Kaiken, mitä talossani on, he ovat nähneet. Aarrekammiossani ei ole mitään, mitä en olisi näyttänyt heille."',
        5: 'Jesaja sanoi Hiskialle: "Kuule Herran Sebaotin sana:',
        6: 'Katso, päivät tulevat, jolloin kaikki, mitä talossasi on ja mitä isäsi ovat koonneet tähän päivään asti, viedään pois Baabeliin. Tänne ei jää mitään, sanoo Herra.',
        7: 'Omia poikiasi, jotka polveutuvat sinusta ja jotka sinulle syntyvät, viedään hovipalvelijoiksi Baabelin kuninkaan palatsiin."',
        8: 'Hiskia sanoi Jesajalle: " Herran sana, jonka olet puhunut, on hyvä." Sillä hän ajatteli: "Onpahan rauha ja turvallisuus minun päivinäni."',
    },
    40: {
        1: '"Lohduttakaa, lohduttakaa kansaani", sanoo Jumalanne.',
        2: '"Puhukaa suloisesti Jerusalemille ja julistakaa sille, että sen vaivanaika on päättynyt, että sen velka on sovitettu, sillä se on saanut Herran kädestä kaksinkertaisesti kaikista synneistään."',
        3: 'Airuen ääni kuuluu: "Valmistakaa Herralle tie erämaahan, tehkää arolle tasaiset polut Jumalallemme.',
        4: 'Kaikki laaksot korotettakoot, kaikki vuoret ja kukkulat alennettakoot. Kivikot tulkoot tasangoksi ja kalliolouhikot tasaiseksi maaksi.',
        5: 'Herran kunnia ilmestyy: kaikki liha saa sen nähdä. Sillä Herran suu on puhunut."',
        6: 'Ääni sanoo: "Julista!" Toinen vastaa: "Mitä minun tulee julistaa?" Kaikki liha on kuin ruoho, ja kaikki sen kauneus kuin kedon kukkanen:',
        7: 'ruoho kuivuu, kukkanen lakastuu, kun Herran Henki puhaltaa siihen. Totisesti, ruohoa on kansa.',
        8: 'Ruoho kuivuu, kukkanen lakastuu, mutta Jumalamme sana pysyy iankaikkisesti.',
        9: 'Nouse korkealle vuorelle, Siion, sinä ilosanoman tuoja. Korota voimakkaasti äänesi, Jerusalem, sinä ilosanoman tuoja. Korota, älä pelkää, sano Juudan kaupungeille: "Katso, teidän Jumalanne!"',
        10: 'Katso, Herra Herra tulee voimallisena, hänen käsivartensa vallitsee. Katso, hänen palkkansa on hänen mukanaan, hänen työnsä ansio käy hänen edellään.',
        11: 'Niin kuin paimen hän kaitsee laumaansa. Hän kokoaa karitsat käsivarrelleen, kantaa niitä sylissään ja johdattaa imettäviä lampaita.',
        12: "Kuka on kourallaan mitannut vedet ja vaaksalla määrännyt taivaitten mitat? Kuka on kolmannesmittaan mahduttanut maan tomun, puntarilla punninnut vuoret, vaa'alla kukkulat?",
        13: 'Kuka on Herran Henkeä ohjannut, ollut hänen neuvonantajansa ja opettajansa?',
        14: 'Kenen kanssa hän on neuvotellut, joka olisi antanut hänelle ymmärrystä ja opettanut oikean polun, opettanut hänelle tiedon ja osoittanut hänelle ymmärryksen tien?',
        15: "Katso, kansakunnat ovat kuin pisara vesisangon uurteessa. Ne ovat kuin tomuhiukkanen vaa'assa. Katso, merensaaret hän nostaa kuin hiekanjyvän.",
        16: 'Libanon ei riittäisi polttopuiksi eikä sen riista polttouhriksi.',
        17: 'Kaikki kansakunnat ovat kuin ei mitään hänen edessään. Ne ovat hänelle kuin olematon ja tyhjä.',
        18: 'Keneen te siis vertaatte Jumalan, ja minkä muotoiseksi te hänet teette?',
        19: 'Jumalankuvanko? – Sen valaa valaja, ja kultaseppä päällystää sen kullalla, ja muotoilee sille hopeaketjut.',
        20: 'Kellä ei ole varaa sellaiseen antiin, se valitsee puun, joka ei lahoa, hakee taitavan tekijän pystyttämään jumalankuvan, joka ei horju.',
        21: 'Ettekö tiedä, ettekö kuule, eikö teille ole alusta asti ilmoitettu, ettekö ole ottaneet vaarin maan perustuksista?',
        22: 'Hän istuu korkealla maanpiirin päällä, kuin heinäsirkkoja ovat sen asukkaat. Hän levittää taivaan kuin harson, pingottaa sen kuin teltan asuttavaksi.',
        23: 'Hän tekee ruhtinaat olemattomiksi ja maan tuomarit tyhjän veroisiksi.',
        24: 'Tuskin heidät on istutettu, tuskin kylvetty, tuskin heidän vartensa on juurtunut maahan, hän puhaltaa heihin, ja he kuivettuvat. Myrsky vie heidät kuin oljenkorret.',
        25: '"Keneen siis vertaatte minut, jonka kaltainen olisin", sanoo Pyhä.',
        26: 'Nostakaa silmänne korkeuteen ja katsokaa: kuka on nämä luonut? Hän, joka johdattaa esiin niiden joukot täysilukuisina, joka kutsuu ne kaikki nimeltä. Niin suuri on hänen mahtinsa ja vahva hänen voimansa, ettei yksikään jää häneltä pois.',
        27: 'Miksi sinä, Jaakob, sanot ja sinä, Israel, puhut: "Tieni on Herralta salassa, oikeuteni on joutunut pois Jumalani huomasta"?',
        28: 'Etkö tiedä, etkö ole kuullut: Herra on iankaikkinen Jumala, joka on luonut maan ääret? Ei hän väsy eikä näänny, hänen ymmärryksensä on tutkimaton.',
        29: 'Hän voimistaa voipuneen ja antaa voimattomalle voimaa yltäkyllin.',
        30: 'Nuorukaiset väsyvät ja nääntyvät, nuoret miehet kompastuvat ja kaatuvat.',
        31: 'Mutta ne, jotka Herraa odottavat, saavat uuden voiman. He kohottavat siipensä kuin kotkat. He juoksevat eivätkä näänny, he vaeltavat eivätkä väsy.',
    },
    41: {
        1: 'Vaietkaa edessäni, te merensaaret. Kansat uudistakoot voimansa, astukoot esiin ja puhukoot sitten. Käykäämme oikeutta keskenämme.',
        2: 'Kuka herätti päivänkoiton maasta sen, jota vanhurskaus seuraa joka askeleella? Kuka antaa kansat hänen valtaansa, kukistaa kuninkaat hänen jalkoihinsa? Kuka muuttaa heidän miekkansa tomuksi, heidän jousensa lentäviksi oljenkorsiksi?',
        3: 'Hän ajaa heitä takaa, kulkee turvallisesti polkua, jota hänen jalkansa eivät ole ennen kulkeneet.',
        4: 'Kuka on tämän tehnyt ja saanut aikaan? Hän, joka alusta asti kutsuu sukupolvet esiin: minä, Herra, joka olen ensimmäinen ja viimeisten luona vielä sama.',
        5: 'Merensaaret näkivät sen ja pelästyivät, maan ääret vapisivat. He lähestyivät, he tulivat,',
        6: 'he auttoivat toinen toistaan ja sanoivat toisilleen: "Ole luja!"',
        7: 'Valaja rohkaisee kultaseppää, levyseppä alasimen iskijää. Hän sanoo juotoksesta: "Se on hyvä", ja vahvistaa sen nauloilla, niin ettei siihen jää väljyyttä.',
        8: 'Mutta sinä, Israel, palvelijani, sinä Jaakob, jonka olen valinnut, Aabrahamin, ystäväni, siemen,',
        9: 'jonka olen ottanut maan ääristä ja kutsunut maan kaukaisimmilta periltä, jolle sanoin: "Sinä olet palvelijani, sinut olen valinnut enkä pitänyt sinua halpana",',
        10: 'älä pelkää, sillä minä olen kanssasi. Älä arkaile, sillä minä olen Jumalasi: vahvistan sinua, autan sinua, tuen sinua vanhurskauteni oikealla kädellä.',
        11: 'Katso, häpeän ja pilkan saavat kaikki, jotka palavat vihasta sinua vastaan. Tyhjiin raukeavat ja hukkuvat ne, jotka sinua vastaan riitelevät.',
        12: 'Hakemallakaan et löydä niitä, jotka sinua vastaan taistelivat. Tyhjiin raukeavat ja lopun saavat ne, jotka sotivat sinua vastaan.',
        13: 'Sillä minä, Herra, Jumalasi, tartun oikeaan käteesi, sanon sinulle: "Älä pelkää, minä autan sinua."',
        14: 'Älä pelkää, Jaakob, sinä mato, sinä Israelin vähäinen väki. Minä autan sinua, sanoo Herra, lunastajasi, Israelin Pyhä.',
        15: 'Katso, panen sinut raastavaksi puimaäkeeksi, uudeksi, monihampaiseksi. Sinä puit ja rouhennat vuoret, muutat kukkulat akanoiksi.',
        16: 'Heität ne pois, tuuli vie ne ja myrsky hajottaa. Mutta sinä iloitset Herrassa ja Israelin Pyhä on kerskauksesi.',
        17: 'Kurjat ja köyhät etsivät vettä, eikä sitä ole. Heidän kielensä kuivuu janosta. Mutta minä, Herra, kuulen heitä, minä, Israelin Jumala, en heitä hylkää.',
        18: 'Puhkaisen purot korkeille kallioille ja lähteet laaksojen pohjiin. Muutan erämaan vesilammikoiksi ja hietikon hetteiköksi.',
        19: 'Kasvatan erämaahan setripuita, akasioita, myrttejä ja öljypuita. Istutan arolle yhdessä sypressejä, jalavia sekä puksipuita,',
        20: 'jotta he näkisivät ja tietäisivät, huomaisivat ja myös ymmärtäisivät, että Herran käsi on tämän tehnyt, Israelin Pyhä on sen luonut.',
        21: 'Tuokaa esiin riita-asianne, sanoo Herra, esittäkää todisteenne, sanoo Jaakobin kuningas.',
        22: 'Esittäkööt ja ilmoittakoot meille, mitä on tapahtuva. Ilmoittakaa entiset, mitä ne olivat, tutkiaksemme ja tietääksemme, mitä niistä on tullut, tai antakaa meidän kuulla tulevia.',
        23: 'Ilmoittakaa, mitä vastedes tapahtuu, tietääksemme, oletteko te jumalia. Tehkää hyvää tai tehkää pahaa, me katselemme ja ihmettelemme.',
        24: 'Katso, te olette pelkkää tyhjää, ja tekonne ovat turhia. Kauhistus se, joka teidät valitsee!',
        25: 'Herätin pohjoisesta hänet, ja hän tuli, päivänkoitosta hänet, joka rukoilee nimeäni, ja hän tallaa käskynhaltijoita kuin lokaa, kuin savenvalaja sotkee savea.',
        26: 'Kuka on sen alun pitäen ilmoittanut, että olisimme sen tienneet, ja edeltäpäin, että voisimme sanoa: "Hän oli oikeassa"? Ei kukaan sitä ilmoittanut, ei kukaan sitä kuuluttanut, ei kukaan kuullut teiltä sanaakaan.',
        27: 'Ensimmäisenä sanon Siionille: "Katso, siinä ne ovat!" ja annan Jerusalemille ilosanomantuojan.',
        28: 'Katselen ympärilleni, mutta ei ole ketään; ei kukaan näistä voi antaa neuvoa, että kysyisin heiltä ja he vastaisivat.',
        29: 'Katso, kaikki he ovat pelkkää petosta, turhat ovat heidän työnsä. Tuulta ja tyhjää ovat heidän valetut kuvansa.',
    },
    42: {
        1: 'Katso, palvelijani, jota tuen, valittuni, johon sieluni on mieltynyt. Olen pannut Henkeni hänen päälleen, hän tuo pakanoille oikeuden.',
        2: 'Hän ei huuda eikä korota ääntään eikä anna sen kuulua kaduilla.',
        3: 'Särjettyä ruokoa hän ei muserra, ja suitsevaa lampun sydäntä hän ei sammuta. Hän levittää oikeutta uskollisesti.',
        4: 'Hän ei itse sammu eikä murru, kunnes on saattanut oikeuden maan päälle, ja merensaaret odottavat hänen opetustaan.',
        5: 'Näin sanoo Jumala, Herra, joka on luonut taivaan ja levittänyt sen, joka on tehnyt maan laveuden ja mitä siinä kasvaa, antanut henkäyksensä kansalle, joka siinä on, ja hengen niille, jotka siellä vaeltavat:',
        6: 'Minä, Herra, olen vanhurskaudessa kutsunut sinut, olen tarttunut käteesi, varjellut sinut ja pannut sinut kansoille liitoksi ja pakanoille valkeudeksi,',
        7: 'avaamaan sokeat silmät, päästämään sidotut vankeudesta ja pimeydessä istuvat vankilasta.',
        8: 'Minä, Herra, se on minun nimeni, en anna kunniaani toiselle enkä ylistystäni epäjumalille.',
        9: 'Katso, entiset ovat toteen käyneet, ja uusia minä ilmoitan. Ennen kuin ne puhkeavat taimelle, annan teidän ne kuulla.',
        10: 'Veisatkaa Herralle uusi virsi, veisatkaa hänen ylistystään maan ääristä, te merenkulkijat ja meri kaikkineen, te merensaaret ja niissä asuvat.',
        11: 'Korottakoot äänensä erämaa ja sen kaupungit, kylät, joissa Keedar asuu. Riemuitkoot kallioilla asuvat, huutakoot ilosta vuorten huipuilta.',
        12: 'Antakoot Herralle kunnian ja julistakoot hänen ylistystään merensaarissa.',
        13: 'Herra lähtee sotaan kuin sankari, kuin soturi hän kiihottaa kiivautensa. Hän nostaa sotahuudon ja jyrisee, hän kukistaa vihollisensa.',
        14: 'Olen ollut vaiti ikiajoista asti, olen ollut hiljaa ja pidättänyt itseni. Mutta nyt huudan kuin lapsensynnyttäjä, puhallan ja vapisen.',
        15: 'Teen autioiksi vuoret ja kukkulat ja kuihdutan niiltä kaiken ruohon. Muutan virrat saariksi ja kuivaan vesilammikot.',
        16: 'Johdatan sokeat tietä, jota he eivät tunne. Kuljetan heidät polkuja, joita he eivät tunne. Muutan pimeyden heidän edellään valkeudeksi ja kivikot tasangoksi. Nämä sanat teen enkä niitä tekemättä jätä.',
        17: 'Mutta ne perääntyvät ja joutuvat häpeään, jotka turvaavat veistettyyn kuvaan, jotka sanovat valetuille kuville: "Te olette jumalamme."',
        18: 'Te kuurot, kuulkaa, ja te sokeat, katsokaa ja nähkää.',
        19: 'Kuka on sokea, ellei palvelijani, ja kuka niin kuuro kuin sanansaattajani, jonka lähetän? Kuka on niin sokea kuin palkkalaiseni, niin sokea kuin Herran palvelija?',
        20: 'Paljon sinä olet nähnyt, mutta et ole ottanut siitä vaarin. Korvat avattiin, mutta hän ei kuule.',
        21: 'Herra on nähnyt hyväksi vanhurskautensa tähden tehdä lain suureksi ja ihanaksi.',
        22: 'Mutta tämä on raastettu ja ryöstetty kansa, kaikki nuoret miehet ovat sidotut ja kätketyt vankiloihin. He ovat joutuneet saaliiksi, eikä ole auttajaa, ryöstetyiksi, eikä ole, kuka sanoisi: "Palauta!"',
        23: 'Kuka teistä ottaa tämän korviinsa, ottaa sen varteen ja kuulee vastaisen varalta?',
        24: 'Kuka on antanut Jaakobin ryöstettäväksi ja Israelin riistäjien valtaan? Eikö Herra, jota vastaan olemme syntiä tehneet, jonka teitä he eivät tahtoneet vaeltaa ja jonka lakia he eivät totelleet?',
        25: 'Niin hän vuodatti Israelin päälle vihansa hehkun ja sodan ankaruuden. Se liekehti hänen ympärillään, mutta hän ei ollut tietävinään. Se poltti häntä, mutta hän ei siitä välittänyt.',
    },
    43: {
        1: 'Mutta nyt, näin sanoo Herra, joka loi sinut, Jaakob, joka valmisti sinut, Israel: Älä pelkää, sillä olen lunastanut sinut, olen kutsunut sinut nimeltä. Sinä olet minun.',
        2: 'Kun kuljet vetten yli, minä olen kanssasi, jos virtojen yli, ne eivät sinua upota. Jos kuljet tulessa, et pala, eikä liekki sinua polta.',
        3: 'Sillä minä olen Herra, Jumalasi, Israelin Pyhä, vapahtajasi. Annan lunnaiksesi Egyptin, sinun sijastasi Kuusin ja Seban.',
        4: 'Koska olet silmissäni kallis ja suuriarvoinen ja koska minä sinua rakastan, minä annan ihmisiä sijastasi ja kansakuntia hengestäsi.',
        5: 'Älä pelkää, sillä minä olen kanssasi. Tuon siemenesi päivänkoiton ääriltä, päivän laskusta kokoan sinut.',
        6: 'Sanon pohjoiselle: Anna tänne! ja etelälle: Älä pidätä! Tuo poikani kaukaa ja tyttäreni maan ääristä –',
        7: 'kaikki, jotka on otettu nimiini ja jotka olen kunniakseni luonut, jotka olen valmistanut ja tehnyt.',
        8: 'Tuo esiin sokea kansa, jolla kuitenkin on silmät, ja kuurot, joilla kuitenkin on korvat.',
        9: 'Kaikki kansat ovat kokoontuneet yhteen ja kansakunnat tulleet kokoon. Kuka heistä voi ilmoittaa tällaista? Tai antakoot meidän kuulla entisiä. Asettakoot todistajansa ja näyttäkööt, että ovat oikeassa. Sittenpä kuullaan ja sanotaan: se on totuus.',
        10: 'Te olette todistajani, sanoo Herra, palvelijani, jonka olen valinnut, jotta tuntisitte minut ja uskoisitte minuun ja ymmärtäisitte, että minä se olen. Ennen minua ei ole tehty yhtään jumalaa, eikä minun jälkeeni tule toista.',
        11: 'Minä, minä olen Herra, eikä ole muuta pelastajaa kuin minä.',
        12: 'Minä olen ilmoittanut, olen pelastanut ja julistanut, eikä ollut vierasta jumalaa teidän keskuudessanne. Te olette todistajani, sanoo Herra, ja minä olen Jumala.',
        13: 'Tästedeskin minä olen sama. Kukaan ei voi vapauttaa kädestäni. Kuka peruuttaa sen, minkä teen?',
        14: 'Näin sanoo Herra, lunastajanne, Israelin Pyhä: Teidän tähtenne lähetän sanan Baabeliin, syöksen heidät kaikki pakoon, syöksen kaldealaiset laivoihin, jotka olivat heidän ilonsa.',
        15: 'Minä, Herra, olen Pyhänne, minä, Israelin Luoja, olen kuninkaanne.',
        16: 'Näin sanoo Herra, joka teki tien mereen ja polun valtaviin vesiin,',
        17: 'joka vei sotaan vaunut ja hevoset, sotaväen ja kaikki sankarit. He makasivat maassa eivätkä nousseet, he raukesivat ja sammuivat kuin lampun sydän:',
        18: 'Älkää entisiä muistelko, älkää menneistä välittäkö.',
        19: 'Katso, teen uutta. Nyt se versoo, ettekö sitä huomaa? Teen tien autiomaahan, virrat erämaahan.',
        20: 'Minua kunnioittavat aron eläimet, sakaalit ja strutsit, koska annan vedet autiomaahan ja virrat erämaahan antaakseni kansani, valittuni, juoda.',
        21: 'Kansa, jonka olen itselleni valmistanut, on julistava kiitostani.',
        22: 'Mutta et sinä, Jaakob, ole minua kutsunut, et sinä, Israel, ole itseäsi minun tähteni vaivannut.',
        23: 'Et ole tuonut minulle lampaitasi polttouhriksi, et teurasuhreillasi minua kunnioittanut. En ole pannut sinua palvelemaan itseäni ruokauhrilla enkä vaivannut suitsutusuhrilla.',
        24: 'Et ole ostanut minulle kalmoruokoa hopealla etkä minua teurasuhriesi rasvalla ravinnut – et, vaan olet minua synneilläsi vaivannut ja rasittanut minua pahoilla teoillasi.',
        25: 'Minä, minä pyyhin pois rikoksesi itseni tähden enkä syntejäsi muista.',
        26: 'Muistuta minua, käykäämme oikeutta keskenämme. Puhu sinä ja näytä, että olet oikeassa.',
        27: 'Esi-isäsi teki syntiä, välittäjäsi luopuivat minusta.',
        28: 'Häpäisin pyhät ruhtinaat, jätin Jaakobin tuhon omaksi, Israelin alttiiksi pilkalle.',
    },
    44: {
        1: 'Mutta nyt kuule, Jaakob, palvelijani, ja Israel, jonka olen valinnut.',
        2: 'Näin sanoo Herra, Luojasi, joka on valmistanut sinut hamasta äidin kohdusta, joka sinua auttaa: Älä pelkää, palvelijani Jaakob, sinä Jesurun, jonka olen valinnut.',
        3: 'Sillä vuodatan vedet janoisen päälle ja virrat kuivan maan päälle. Vuodatan Henkeni siemenesi päälle ja siunaukseni vesojesi päälle,',
        4: 'niin että ne kasvavat nurmikolla kuin pajut vesipurojen reunalla.',
        5: 'Kuka sanoo: "Minä olen Herran oma", kuka nimittää itsensä Jaakobin nimellä, kuka kirjoittaa käteensä: " Herran oma", ja ottaa Israelin kunnianimekseen.',
        6: 'Näin sanoo Herra, Israelin kuningas, ja sen lunastaja, Herra Sebaot: Minä olen ensimmäinen, ja minä olen viimeinen, eikä ole muuta Jumalaa kuin minä.',
        7: 'Kuka on kaltaiseni? Hän julistakoon ja ilmoittakoon ja osoittakoon sen minulle, siitä alkaen kun perustin ikiaikojen kansan. He ilmoittakoot tulevat, ja mitä on tapahtuva.',
        8: 'Älkää vavisko älkääkä pelätkö. Enkö minä aikoja sitten antanut sinun kuulla ja sinulle ilmoittanut, ja te olette minun todistajani: Onko muuta Jumalaa kuin minä? Ei ole muuta pelastuskalliota, minä en ketään tunne.',
        9: 'Jumalankuvien tekijät ovat turhia kaikki tyynni, eivätkä nuo heidän rakkaansa auta mitään. Niiden todistajat eivät näe eivätkä tiedä mitään, ja niin he joutuvat häpeään.',
        10: 'Kuka tahansa muovatkoon jumalan ja valakoon kuvan. Se ei auta yhtään.',
        11: 'Katso, kaikki sen seuraajat joutuvat häpeään, ja sen tekijät ovat vain ihmisiä. Tulkoot kokoon kaikki ja astukoot esiin: vaviskoot ja hävetkööt!',
        12: 'Rautaseppä ottaa työkalun, työskentelee hiilten hehkussa, muovailee kuvaa vasaralla ja takoo sitä käsivartensa voimalla. Hänen tulee nälkä, ja voima menee, hän ei saa vettä juodakseen, ja hän nääntyy.',
        13: 'Puuseppä jännittää mittanuoran, kaavailee piirtimellä, vuolee kovertimilla, mittailee harpilla ja tekee miehen kuvan inhimillisen kauneuden mukaan huoneeseen asumaan.',
        14: 'Hän hakkaa itselleen setripuita, hän ottaa rautatammen ja tammen ja kasvattaa ne itselleen vahvoiksi metsän puiden seassa, istuttaa setrin, ja sade kasvattaa sen suureksi.',
        15: 'Se on ihmisillä polttopuuna. Hän ottaa sitä lämmitelläkseen, sytyttää uunin ja paistaa leipää, vieläpä veistää siitä jumalan ja kumartaa sitä, tekee siitä jumalankuvan ja lankeaa maahan sen eteen.',
        16: 'Osan siitä hän polttaa tulessa, toisen osan vierellä hän syö lihaa, paistaa paistin ja tulee ravituksi. Hän myös lämmittelee itseään ja sanoo: "Hyvä, minun on lämmin, näen liekin."',
        17: 'Hän tekee lopusta jumalan, jumalankuvan, jonka eteen hän lankeaa maahan, jota hän kumartaa ja rukoilee sanoen: "Pelasta minut, sillä sinä olet jumalani."',
        18: 'He eivät tajua eivätkä ymmärrä mitään, sillä heidän silmänsä ovat suljetut, niin etteivät he näe, ja heidän sydämensä on suljettu, niin etteivät he käsitä.',
        19: 'Heidän mieleensä ei tule, heillä ei ole järkeä eikä ymmärrystä, että sanoisivat: "Osan siitä olen polttanut tulessa, olen paistanut sen hiilillä leipää, paistanut lihaa ja syönyt. Tekisinkö tähteestä kauhistuksen ja lankeaisinko maahan puupölkyn eteen!"',
        20: 'Sen, joka riippuu kiinni tuhkassa, petetty sydän on vienyt harhaan. Hän ei pelasta sieluaan eikä sano: "Eikö se, mikä on oikeassa kädessäni, ole petosta?"',
        21: 'Muista tämä, Jaakob, ja sinä, Israel, sillä sinä olet palvelijani. Olen sinut valmistanut, sinä olet palvelijani. En unohda sinua, Israel.',
        22: 'Pyyhin pois rikoksesi kuin pilven ja syntisi kuin sumun. Palaa luokseni, sillä lunastan sinut.',
        23: 'Iloitkaa, te taivaat, sillä Herra sen tekee. Riemuitkaa, te maan syvyydet. Puhjetkaa riemuun, te vuoret, sekä metsä ja kaikki sen puut. Sillä Herra lunastaa Jaakobin ja kirkastaa itsensä Israelissa.',
        24: 'Näin sanoo Herra, lunastajasi, joka on valmistanut sinut hamasta äidin kohdusta: Minä olen Herra, joka teen kaiken, joka yksin jännitin taivaan ja levitin maan – kuka oli kanssani? –',
        25: 'joka teen tyhjäksi valehtelijoiden merkit ja teen taikurit tyhmiksi, joka panen tietäjät peräytymään ja muutan heidän tietonsa typeryydeksi.',
        26: 'Mutta palvelijani sanan minä toteutan ja saatan täyttymään sanansaattajieni neuvon. Olen se, joka sanon Jerusalemille: "Sinussa asuttakoon!" ja Juudan kaupungeille: "Teidät rakennettakoon!" Kohotan sen rauniot.',
        27: 'Olen se, joka sanon syvyydelle: "Kuivu; minä kuivaan sinun virtasi!"',
        28: 'joka sanon Koorekselle: "Paimeneni!" Hän täyttää kaiken tahtoni ja sanoo Jerusalemille: "Sinut rakennettakoon!" ja temppelille: "Sinut perustettakoon!"',
    },
    45: {
        1: 'Näin sanoo Herra voidellulleen Koorekselle, jonka oikeaan käteen olen tarttunut kukistaakseni kansat hänen edestään ja riisuakseni kuninkaitten vyötäisiltä vyöt, jotta ovet hänen edessään avautuisivat eivätkä portit sulkeutuisi:',
        2: 'Minä käyn edelläsi ja tasoitan kukkulat, murran vaskiovet ja rikon rautasalvat.',
        3: 'Annan sinulle aarteet pimeän peitosta, kalleudet niiden kätköistä tietääksesi, että minä, Herra, olen se, joka olen kutsunut sinut nimeltä, minä, Israelin Jumala.',
        4: 'Palvelijani Jaakobin ja valittuni Israelin tähden olen kutsunut sinut nimeltä ja antanut sinulle kunnianimen, vaikka et minua tuntenut.',
        5: 'Minä olen Herra, eikä toista ole, minun lisäkseni ei ole yhtään Jumalaa. Vyötän sinut, vaikka et minua tunne,',
        6: 'jotta tiedettäisiin auringon noususta sen laskuun asti, että minun lisäkseni ei ole yhtään: minä olen Herra, eikä toista ole,',
        7: 'minä, joka teen valkeuden ja luon pimeyden, joka tuotan onnen ja luon onnettomuuden; minä, Herra, teen kaiken tämän.',
        8: 'Tihkukaa, te taivaat, ylhäältä, vuotakoot pilvet vanhurskautta. Avautukoon maa ja antakoon hedelmänään pelastuksen, versokoon se myös vanhurskautta. Minä, Herra, olen sen luonut.',
        9: 'Voi sitä, joka riitelee tekijänsä kanssa, saviastia saviastioiden joukossa – maasta tehtyjä kaikki! Sanooko savi valajalleen: "Mitä teet? Työsi on kädettömän työtä!"',
        10: 'Voi sitä, joka sanoo isälleen: "Mitä olet siittänyt?" ja äidilleen: "Mitä olet synnyttänyt?"',
        11: 'Näin sanoo Herra, Israelin Pyhä, joka on hänet tehnyt: Kysykää tulevia minulta ja jättäkää minun haltuuni lapseni, kätteni teot.',
        12: 'Minä olen tehnyt maan ja luonut ihmisen maan päälle; käteni ovat levittäneet taivaan, minä olen kutsunut koolle kaikki sen joukot.',
        13: 'Minä herätin hänet vanhurskaudessa, ja minä tasoitin kaikki hänen tiensä. Hän rakentaa kaupunkini ja päästää vapaiksi karkotettuni ilman maksua ja ilman lahjusta, sanoo Herra Sebaot.',
        14: 'Näin sanoo Herra: Egyptin työn tulos ja Kuusin kauppavoitto ja sebalaiset, kookkaat miehet, tulevat luoksesi, tulevat omiksesi. Sinun perässäsi he käyvät, kulkevat kahleissa, sinua kumartavat, sinua rukoilevat: "Ainoastaan sinun luonasi on Jumala, ei ole toista, ei yhtään muuta jumalaa."',
        15: 'Totisesti, sinä olet salattu Jumala, sinä Israelin Jumala, sinä Vapahtaja.',
        16: 'Häpeän ja pilkan he saavat kaikki, pilkan alaisina he kulkevat kaikki, nuo kuvien tekijät.',
        17: 'Mutta Israelin pelastaa Herra iankaikkisella pelastuksella. Ette joudu häpeään ettekä pilkan alaisiksi, ette ikinä, ette ikuisuuteen saakka.',
        18: 'Sillä näin sanoo Herra, joka on luonut taivaan – hän on Jumala – joka on valmistanut maan ja tehnyt sen ja on sen vahvistanut. Hän ei luonut sitä autioksi, asuttavaksi hän sen valmisti. Minä olen Herra, eikä toista ole.',
        19: 'En ole puhunut salassa, en pimeässä maan paikassa. En ole sanonut Jaakobin jälkeläisille: etsikää minua tyhjyydestä. Minä Herra puhun vanhurskautta, ilmoitan, mikä on oikein.',
        20: 'Kokoontukaa ja tulkaa, lähestykää kaikki, te kansakunnista pelastuneet. Eivät ne mitään ymmärrä, jotka kantavat puisia kuviaan ja rukoilevat jumalaa, joka ei voi auttaa.',
        21: 'Ilmoittakaa ja tuokaa esiin – neuvotelkoot keskenään – kuka on tämän julistanut hamasta muinaisuudesta, aikoja sitten ilmoittanut? Enkö minä, Herra! Minun lisäkseni ei ole yhtään Jumalaa; ei ole vanhurskasta ja pelastavaa Jumalaa muuta kuin minä.',
        22: 'Kääntykää minun luokseni ja tulkaa osallisiksi pelastuksesta, te maan ääret kaikki, sillä minä olen Jumala, eikä toista ole.',
        23: 'Olen vannonut itseni kautta, suustani on lähtenyt totuus, peruuttamaton sana: Minun edessäni pitää kaikkien polvien notkistua, minulle jokaisen kielen tulee vannoa valansa.',
        24: 'Ainoastaan Herrassa – niin tulee minusta sanoa – on vanhurskaus ja voima. Hänen luokseen tulevat häveten kaikki, jotka ovat palaneet vihasta häntä vastaan.',
        25: 'Herrassa tulee vanhurskaaksi kaikki Israelin siemen, ja hän on heidän kerskauksensa.',
    },
    46: {
        1: 'Beel sortuu, Nebo taipuu. Niiden kuvat joutuvat eläinten ja juhtien selkään. Se, mitä te kulkueessa kannoitte, sälytetään kuormaksi uupuville.',
        2: 'Ne taipuvat, ne sortuvat molemmat. Ne eivät voi pelastaa kuormaa, ja itsekin ne vaeltavat vankeuteen.',
        3: 'Kuulkaa minua, te Jaakobin heimo, kaikki te Israelin heimon tähteet, te, joita on pitänyt kantaa äidinkohdusta asti, nostaa hamasta äidinhelmasta.',
        4: 'Vanhuuteenne asti minä olen sama, aina harmaantumiseenne saakka minä kannan. Niin minä olen tehnyt, ja vastedeskin minä nostan, minä kannan ja pelastan.',
        5: 'Keneen te vertaatte minut, kenen rinnalle te asetatte minut, kenen kaltaisena te minua pidätte, että olisimme toistemme vertaisia?',
        6: "He kaatavat kultaa kukkarosta ja punnitsevat hopeaa vaa'alla. He palkkaavat kultasepän, ja hän tekee siitä jumalan, jonka eteen he lankeavat maahan ja jota he kumartavat.",
        7: 'He nostavat sen olalleen, kantavat sitä ja asettavat sen paikoilleen, ja se seisoo eikä liikahda paikaltaan. Sitä huudetaan avuksi, mutta se ei vastaa eikä pelasta hädästä.',
        8: 'Muistakaa tämä ja olkaa lujat. Menkää itseenne, te luopiot.',
        9: 'Muistakaa ennen tapahtuneita ikiajoista asti, sillä minä olen Jumala, eikä toista ole. Minä olen Jumala, eikä ole minun vertaistani.',
        10: 'Ilmoitan alusta asti, mitä on tuleva, paljon ennen kuin se on vielä tapahtunut. Sanon: neuvoni pysyy, kaiken, mitä tahdon, minä teen.',
        11: 'Olen kutsunut kotkan päivänkoitosta, kaukaisesta maasta päätökseni toimeenpanijan. Minkä olen puhunut, sen myös toteutan. Sen, mitä olen ajatellut, myös teen.',
        12: 'Kuulkaa minua, te kovasydämiset, jotka olette kaukana vanhurskaudesta.',
        13: 'Olen antanut vanhurskauteni lähestyä, se ei ole kaukana. Pelastus, jonka tuon, ei viivy. Annan Siioniin pelastuksen, annan kirkkauteni Israelille.',
    },
    47: {
        1: 'Astu alas ja istu tomuun, sinä neitsyt, tytär Baabel, istu maahan, valtaistuinta vailla, sinä Kaldean tytär. Sillä sinua ei sanota enää hienoksi ja kauniiksi.',
        2: 'Tartu käsikiviin ja jauha jauhoja, riisu huntusi, nosta helmasi, paljasta sääresi, kahlaa jokien poikki.',
        3: 'Häpysi paljastuu, häpeäsi näkyy. Minä kostan enkä armahda ainoatakaan.',
        4: 'Lunastajamme nimi on Herra Sebaot, Israelin Pyhä.',
        5: 'Istu vaieten ja väisty pimeään, sinä Kaldean tytär. Sillä sinua ei enää kutsuta valtakuntien valtiattareksi.',
        6: 'Vihastuin kansaani, annoin häväistä perintöni ja annoin heidät käsiisi. Et osoittanut heille sääliä, vanhuksellekin teit ikeesi hyvin raskaaksi.',
        7: 'Silloin sanoit: "Ikuisesti olen valtiaasi", niin ettet näitä mieleesi pannut etkä loppua ajatellut.',
        8: 'Mutta nyt kuule tämä, sinä hekumoitsija, joka istut turvallisena, joka sanot sydämessäsi: "Minä, eikä kukaan muu! En ole leskenä istuva enkä lapsettomuudesta tietävä."',
        9: 'Mutta nämä molemmat tulevat osaksesi äkkiä, yhtenä päivänä: lapsettomuus ja leskeys. Ne kohtaavat sinua täysimääräisinä huolimatta velhouksiesi paljoudesta ja loitsujesi suuresta voimasta.',
        10: 'Luotit pahuuteesi ja sanoit: "Ei kukaan minua näe." Viisautesi ja tietosi eksyttivät sinut, ja sanoit sydämessäsi: "Minä, eikä kukaan muu!"',
        11: 'Sen tähden kohtaa sinua onnettomuus, etkä tiedä, milloin se tulee. Sinut yllättää tuho, josta et selviä lunnailla, sinut kohtaa äkkiä perikato, aavistamattasi.',
        12: 'Astu esiin loitsuinesi ja paljoine velhouksinesi, joilla olet vaivannut itseäsi nuoruudestasi asti: ehkä hyvinkin saat avun, ehkä herätät pelkoa.',
        13: 'Sinä olet väsyttänyt itsesi paljolla neuvottelemisellasi. Astukoot esiin ja auttakoot sinua taivaan mittaajat, tähtien tähystäjät, jotka kuu kuulta ilmoittavat, mitä sinulle on tapahtuva.',
        14: 'Katso, he ovat kuin kuivat korret: tuli polttaa heidät. He eivät pelasta henkeään liekin vallasta. Se ei ole hiillos, jolla he lämmittelisivät eikä tuli, jonka ääressä istutaan.',
        15: 'Tämän saat sinä niistä, joista olet vaivaa nähnyt: He ovat niitä, joiden kanssa olet kauppaa käynyt nuoruudestasi asti. He harhailevat kukin taholleen, eikä kukaan sinua pelasta.',
    },
    48: {
        1: 'Kuulkaa tämä, Jaakobin heimo, te, joista käytetään nimeä Israel ja jotka olette lähteneet Juudan lähteestä, jotka vannotte Herran nimeen ja tunnustatte Israelin Jumalan, mutta ette totuudessa ettekä vanhurskaudessa',
        2: '– sillä he saavat nimensä pyhän kaupungin mukaan ja he pitävät tukenaan Israelin Jumalaa, jonka nimi on Herra Sebaot:',
        3: 'Entiset olen jo ajat sitten ilmoittanut, ne ovat lähteneet suustani, ja olen ne kuuluttanut. Äkkiä panin ne täytäntöön, ja ne tapahtuivat.',
        4: 'Koska tiesin, että sinä olet paatunut, että niskajänteesi on rautaa ja otsasi vaskea,',
        5: 'niin ilmoitin ne sinulle jo ajat sitten, kuulutin ne sinulle, ennen kuin ne tapahtuivat, ettet sanoisi: "Epäjumalankuvani on ne tehnyt, veistetty kuvani ja valettu kuvani on niin säätänyt."',
        6: 'Olet ne kuullut, katso nyt kaikkea: ettekö sitä tunnusta? Tästä lähtien kuulutan sinulle uusia, salattuja asioita, joita et ole tiennyt.',
        7: 'Ne on luotu nyt eikä aikoja sitten, ennen tätä päivää et ole kuullut niistä, ettet sanoisi: "Katso, olen ne tietänyt!"',
        8: 'Et ole niistä kuullut etkä niistä tietänyt, eikä korvasi ole niille aikaisemmin auennut. Sillä tiesin, että olet aivan uskoton ja luopioksi sanottu jo äidin kohdusta asti.',
        9: 'Oman nimeni tähden olen kärsivällinen, ylistykseni tähden hillitsen vihani, etten sinua tuhoaisi.',
        10: 'Katso, olen sulattanut sinua hopeaa saamatta, olen sinua koetellut kärsimyksen pätsissä.',
        11: 'Itseni, itseni tähden sen teen. Sillä kuinka onkaan nimeäni häväisty! Mutta en anna kunniaani toiselle.',
        12: 'Kuule minua, Jaakob, ja sinä, Israel, jonka olen kutsunut: Minä olen aina sama, minä olen ensimmäinen, minä olen myös viimeinen.',
        13: 'Käteni on perustanut maan, oikea käteni on levittänyt taivaan. Minä kutsun ne, ja siinä ne ovat.',
        14: 'Kokoontukaa kaikki ja kuulkaa – kuka noista muista on ilmoittanut tämän: että se, jota Herra rakastaa, tekee hänen tahtonsa Baabelia vastaan ja on hänen käsivartenaan kaldealaisia vastaan.',
        15: 'Minä, minä olen puhunut, minä olen hänet kutsunut, olen hänet tuonut, ja hän on menestynyt teillään.',
        16: 'Lähestykää minua, kuulkaa tämä: Alkujaankaan en ole puhunut salassa. Kun nämä tapahtuivat, minä olin jo siellä. Mutta nyt Herra Herra on lähettänyt minut sekä oman Henkensä.',
        17: 'Näin sanoo Herra, lunastajasi, Israelin Pyhä: Minä olen Herra, Jumalasi, joka opetan sinulle, mikä on hyödyllistä, johdatan sinut sitä tietä, jota sinun tulee kulkea.',
        18: 'Jospa ottaisit käskyistäni vaarin, rauhasi olisi kuin virta ja vanhurskautesi kuin meren aallot.',
        19: 'Lastesi paljous olisi kuin hiekka, kohtusi hedelmä kuin hiekan jyvät. Sen nimi ei häviäisi eikä katoaisi kasvojeni edestä.',
        20: 'Lähtekää Baabelista, paetkaa Kaldeasta; riemuhuudoin ilmoittakaa, kuuluttakaa tämä, viekää tieto siitä maan ääriin asti, sanokaa: " Herra on lunastanut palvelijansa Jaakobin."',
        21: 'He eivät kärsineet janoa, kun hän kuljetti heitä erämaiden halki. Hän vuodatti heille vettä kalliosta ja halkaisi kallion, ja vettä virtasi.',
        22: 'Jumalattomilla ei ole rauhaa, sanoo Herra.',
    },
    49: {
        1: 'Kuulkaa minua, te merensaaret, ja ottakaa tästä vaarin, te, kaukaiset kansat. Herra on kutsunut minut jo äidinkohdusta asti, jo äitini helmasta hän on maininnut nimeni.',
        2: 'Hän teki suuni terävän miekan kaltaiseksi ja kätki minut kätensä varjoon. Hän teki minut hiotuksi nuoleksi ja talletti minut viineensä.',
        3: 'Hän sanoi minulle: "Sinä olet palvelijani, sinä Israel, jossa osoitan kirkkauteni."',
        4: 'Mutta minä sanoin: "Suotta olen itseäni vaivannut, kuluttanut voimani turhaan ja tyhjään. Kuitenkin oikeuteni on Herran huomassa, palkkani on Jumalan luona."',
        5: 'Mutta nyt sanoo Herra, joka on valmistanut minut palvelijakseen jo äitini kohdusta palauttamaan Jaakobin luokseen, niin että Israel koottaisiin hänen omakseen. Olen kallis Herran silmissä, ja Jumalani on voimani.',
        6: 'Hän sanoo: Sinulle, joka olet palvelijani, on liian vähäistä kohottaa ennalleen Jaakobin sukukunnat ja tuoda takaisin Israelin säilyneet: panen sinut pakanoille valkeudeksi, että minulta tulisi pelastus maan ääriin asti.',
        7: 'Näin sanoo Herra, Israelin lunastaja, hänen Pyhänsä, syvästi halveksitulle, kansan inhoamalle, valtiaitten orjalle: Kuninkaat näkevät sen ja nousevat seisomaan, ruhtinaat näkevät ja kumartuvat maahan Herran tähden, joka on uskollinen, Israelin Pyhän tähden, joka on sinut valinnut.',
        8: 'Näin sanoo Herra: Otollisella ajalla olen sinua kuullut ja pelastuksen päivänä sinua auttanut. Olen valmistanut sinut ja pannut sinut kansoille liitoksi kohottamaan ennalleen maan, jakamaan hävitetyt perintöosat ja',
        9: 'sanomaan vangituille: "Käykää ulos!" ja pimeässä oleville: "Tulkaa esiin!" Teiden varsilta he löytävät laitumen, kaikki kalliokukkulat ovat heillä laitumina.',
        10: 'Heidän ei tule nälkä eikä jano, heihin ei satu hietikon helle eikä aurinko, sillä heidän armahtajansa johdattaa heitä ja vie heidät vesilähteille.',
        11: 'Teen kaikki vuoreni teiksi, ja valtatieni kulkevat korkealla.',
        12: 'Katso heitä, he tulevat kaukaa! Katso, nuo pohjoisesta, nuo lännestä, nuo Siinimin maalta!',
        13: 'Riemuitkaa, te taivaat, iloitse, sinä maa, puhjetkaa riemuun, te vuoret, sillä Herra lohduttaa kansaansa ja armahtaa kurjiaan.',
        14: 'Mutta Siion sanoo: " Herra on minut hylännyt, Herra on minut unohtanut."',
        15: 'Unohtaako vaimo rintalapsensa, niin ettei hän armahda kohtunsa poikaa? Mutta vaikka he unohtaisivat, minä en sinua unohda.',
        16: 'Katso, käsiini olen sinut piirtänyt, muurisi ovat aina edessäni.',
        17: 'Lapsesi tulevat rientäen, mutta hävittäjäsi ja raunioittajasi menevät pois luotasi.',
        18: 'Nosta silmäsi ja katso ympärillesi: he kokoontuvat, he tulevat kaikki luoksesi. Niin totta kuin minä elän, sanoo Herra, sinä puet heidät kaikki yllesi kuin korun ja sidot heidät vyöllesi kuin morsian vyönsä.',
        19: 'Sillä sinä – sinun rauniosi ja autiot paikkasi, sinun hävitetty maasi – sinä käyt silloin ahtaaksi asukkaille, ja kaukana ovat ne, jotka sinua söivät.',
        20: 'Vielä saavat lapsettomuutesi lapset sanoa korviesi kuullen: "Paikka on minulle ahdas, tee tilaa, että voin asua."',
        21: 'Silloin sanot sydämessäsi: "Kuka on nämä minulle synnyttänyt? Olin lapseton ja hedelmätön, karkotettu ja hylätty. Kuka on heidät kasvattanut? Katso, minut oli jätetty yksin. Missä nämä silloin olivat?',
        22: 'Näin sanoo Herra, Herra: Katso, nostan käteni kansakuntien puoleen, kohotan lippuni kansoja kohti, niin he tuovat poikasi sylissään ja kantavat tyttäresi olkapäillään.',
        23: 'Kuninkaista tulee sinulle lastenhoitajia, heidän ruhtinattaristaan sinulle imettäjiä. Edessäsi he kumartuvat maahan kasvoilleen ja nuolevat tomun jaloistasi. Tiedät, että minä olen Herra ja että ne, jotka minua odottavat, eivät joudu häpeään.',
        24: 'Otetaanko sankarilta saalis, tai riistetäänkö vangit vanhurskaalta?',
        25: 'Sillä näin sanoo Herra: Vaikka vangit otettaisiinkin sankarilta ja saalis riistettäisiin väkevältä, niin kuitenkin minä taistelen sitä vastaan, joka sinua vastaan taistelee, ja minä pelastan lapsesi.',
        26: 'Panen sortajasi syömään omaa lihaansa, ja he juopuvat omasta verestään kuin rypälemehusta. Silloin kaikki liha on tietävä, että minä, Herra, olen pelastajasi, että Jaakobin Väkevä on lunastajasi.',
    },
    50: {
        1: 'Näin sanoo Herra: Missä on äitinne erokirja, jolla olisin lähettänyt hänet pois? Tai kuka on velkojani, jolle olisin teidät myynyt? Katso, pahojen tekojenne tähden teidät on myyty, rikostenne tähden äitinne on lähetetty pois.',
        2: 'Miksi ei ollut ketään, kun saavuin, miksi kukaan ei vastannut, kun kutsuin? Onko käteni liian lyhyt vapahtamaan, olenko voimaton auttamaan? Katso, nuhtelullani kuivaan meren ja teen virrat erämaaksi, niin että niiden kalat mätänevät. Kun ei ole vettä, ne kuolevat janoon.',
        3: 'Puetan taivaat mustiin ja panen murhepuvun niiden verhoksi.',
        4: 'Herra, Herra on antanut minulle opetuslasten kielen, niin että voin sanalla virvoittaa väsynyttä. Hän herättää aamu aamulta, herättää korvani kuulemaan opetuslasten tavoin.',
        5: 'Herra, Herra on avannut korvani, en ole niskoitellut enkä vetäytynyt pois.',
        6: 'Selkäni annoin lyötäväksi ja poskieni parran revittäväksi, enkä peittänyt kasvojani pilkalta enkä syljeltä.',
        7: 'Herra, Herra auttaa minua. Sen tähden pilkka ei koskenut minuun. Siksi tein kasvoni koviksi kuin piikivi, sillä tiedän, etten joudu häpeään.',
        8: 'Lähellä on se, joka minut vanhurskaaksi tuomitsee. Kuka voi minua vastaan nostaa riita-asian? Astukaamme yhdessä esiin! Kuka on vastapuoleni? Tulkoon tänne lähelleni!',
        9: 'Katso, Herra, Herra auttaa minua. Kuka tuomitsee minut syylliseksi? Katso, kaikki he hajoavat kuin vaate. Koi heidät syö.',
        10: 'Kuka teistä pelkää Herraa ja kuulee hänen palvelijansa ääntä? Se, joka vaeltaa pimeydessä ja valoa vailla, luottakoon Herran nimeen ja turvautukoon Jumalaansa.',
        11: 'Mutta katso, te kaikki, jotka palon sytytätte, te palavilla nuolilla varustetut, suistukaa oman tulenne liekkeihin, niihin palaviin nuoliin, jotka olette sytyttäneet. Kädestäni tämä teille tulee: vaivassa te tulette asumaan.',
    },
    51: {
        1: 'Kuulkaa minua, te jotka tavoittelette vanhurskautta, te jotka etsitte Herraa. Katsokaa kalliota, josta teidät on lohkaistu, ja kaivosonkaloa, josta teidät on kaivettu.',
        2: 'Katsokaa Aabrahamia, isäänne, ja Saaraa, joka teidät synnytti. Sillä Aabraham oli vain yksi, kun hänet kutsuin; mutta siunasin hänet ja enensin hänet.',
        3: 'Sillä Herra lohduttaa Siionin, lohduttaa kaikki sen rauniot, hän tekee sen erämaasta kuin Eedenin ja sen arosta kuin Herran puutarhan. Siellä on oleva riemu ja ilo, kiitos ja ylistysvirren ääni.',
        4: 'Kuuntele minua, kansani, kuule minua, kansakuntani, sillä minusta lähtee laki, ja minä panen oikeuteni valkeudeksi kansoille.',
        5: 'Lähellä on vanhurskauteni, autuuteni ilmestyy, käsivarteni tuomitsevat kansat. Minua odottavat merensaaret ja ne panevat toivonsa käsivarteeni.',
        6: 'Nostakaa silmänne taivasta kohti ja katsokaa maata, joka on alhaalla, sillä taivaat katoavat kuin savu ja maa hajoaa kuin vaate ja sen asukkaat kuolevat kuin sääsket, mutta autuuteni pysyy iankaikkisesti, eikä vanhurskauteni kukistu.',
        7: 'Kuulkaa minua, te jotka vanhurskauden tunnette, kansa, jonka sydämessä on lakini: älkää pelätkö ihmisten pilkkaa älkääkä kauhistuko heidän herjauksiaan.',
        8: 'Sillä koi syö heidät kuin vaatteen, koiperhonen syö heidät kuin villan, mutta vanhurskauteni pysyy iankaikkisesti ja autuuteni polvesta polveen.',
        9: 'Nouse, nouse, pukeudu voimaan, sinä Herran käsivarsi. Nouse kuin muinaisina päivinä, menneiden sukupolvien aikoina. Etkö ole se, joka löit Rahabin kuoliaaksi, joka lävistit lohikäärmeen?',
        10: 'Etkö sinä ole se, joka kuivasit meren, suuren syvyyden vedet, joka teit meren syvänteet tieksi lunastettujen kulkea?',
        11: 'Herran vapahdetut palaavat ja tulevat Siioniin riemuiten, päänsä päällä iankaikkinen ilo. Riemu ja ilo saavuttavat heidät, mutta murhe ja huokaus pakenevat.',
        12: 'Minä, minä olen teidän lohduttajanne. Mikä olet sinä, että pelkäät ihmistä, joka on kuolevainen, ihmislasta, jonka käy kuin ruohon,',
        13: 'ja unohdat Herran, joka on sinut tehnyt, joka on levittänyt taivaan ja perustanut maan, ja vapiset alati kaiket päivät sortajan vihaa, kun hän tähtää tuhotakseen? Mutta missä on sortajan viha?',
        14: 'Pian päästetään kumaraan koukistunut vapaaksi kahleistaan. Hän ei kuole, ei jää kuoppaan eikä häneltä puutu leipää.',
        15: 'Minä olen Herra, Jumalasi, joka liikutan meren, niin että sen aallot pauhaavat, jonka nimi on Herra Sebaot.',
        16: 'Olen pannut sanani suuhusi. Olen kätkenyt sinut käteni varjoon pystyttääkseni taivaan ja perustaakseni maan ja sanoakseni Siionille: "Sinä olet kansani."',
        17: 'Nouse, nouse, lähde liikkeelle, Jerusalem, sinä joka olet juonut Herran kädestä hänen vihansa maljan, joka olet juonut päihdyttävän pikarin ja tyhjentänyt sen.',
        18: 'Ei kukaan kaikista lapsista, jotka hän oli synnyttänyt, ollut häntä taluttamassa. Ei kukaan kaikista lapsista, jotka hän oli kasvattanut, tarttunut hänen käteensä.',
        19: 'Nämä kohtasivat sinua kaksittain – kuka sinua säälii? – tuho ja turmio, nälkä ja miekka. Millä voin sinua lohduttaa?',
        20: 'Poikasi makasivat tajuttomina joka kadun kulmassa, kuin antiloopit pyydyskuopassa, täynnä Herran vihaa, Jumalasi nuhtelua.',
        21: 'Sen tähden kuule tätä, sinä kurja, joka olet juopunut, vaikka et viinistä!',
        22: 'Näin sanoo Herrasi, Herra Jumalasi, joka ajaa kansansa asian: Katso, otan kädestäsi päihdyttävän maljan, vihani pikarin. Sinun ei tarvitse enää siitä juoda.',
        23: 'Panen sen vaivaajiesi käteen, jotka sanoivat sinulle: "Lankea maahan, jotta kulkisimme ylitsesi." Sinä panit selkäsi maaksi ja kaduksi kulkijoille.',
    },
    52: {
        1: 'Nouse, nouse, pukeudu voimaasi, Siion; pukeudu juhlapukuusi, Jerusalem, sinä pyhä kaupunki. Sillä ei koskaan enää astu sisällesi ympärileikkaamaton eikä saastainen.',
        2: 'Pudista päältäsi tomu, nouse istuimellesi, Jerusalem. Irrota kahleet kaulastasi, sinä, vangittu tytär Siion.',
        3: 'Sillä näin sanoo Herra: Ilmaiseksi teidät myytiin, rahatta teidät lunastetaan.',
        4: 'Sillä näin sanoo Herra, Herra: Kansani meni ensin alas Egyptiin asumaan siellä muukalaisena, ja sitten Assur sorti sitä syyttä.',
        5: 'Nyt, mitä minulla on tekemistä täällä, sanoo Herra, kun kansani on viety pois ilmaiseksi? Sen valtiaat elämöivät, sanoo Herra, ja nimeäni pilkataan alati, kaiket päivät.',
        6: 'Sen tähden kansani on tunteva nimeni. Sen tähden se on sinä päivänä tunteva, että minä olen se, joka sanon: "Katso, minä se olen."',
        7: 'Kuinka suloiset ovat vuorilla ilosanoman tuojan jalat, hänen, joka julistaa rauhaa, ilmoittaa hyvän sanoman, joka julistaa pelastusta, sanoo Siionille: "Sinun Jumalasi on kuningas!"',
        8: 'Kuule! Vartijasi korottavat äänensä, kaikki he riemuitsevat, sillä he näkevät silmästä silmään, kuinka Herra palaa Siioniin.',
        9: 'Huutakaa ilosta, riemuitkaa, kaikki te Jerusalemin rauniot, sillä Herra lohduttaa kansansa, lunastaa Jerusalemin.',
        10: 'Herra paljastaa pyhän käsivartensa kaikkien kansojen nähden, ja kaikki maan ääret saavat nähdä Jumalamme autuuden.',
        11: 'Pois, pois! Lähtekää sieltä, älkää koskeko saastaiseen. Lähtekää sen keskeltä, puhdistautukaa, te Herran astioiden kantajat.',
        12: 'Sillä teidän ei tarvitse lähteä kiireellä eikä kulkea paeten, sillä Herra käy teidän edellänne, Israelin Jumala seuraa suojananne.',
        13: 'Katso, palvelijani menestyy, hän on nouseva, kohoava ja sangen korkea oleva.',
        14: 'Niin kuin monet kauhistuivat häntä – sillä niin runneltu, ei enää ihmisen kaltainen, oli hänen muotonsa, hänen hahmonsa ei ollut ihmislasten hahmo –',
        15: 'niin hän on vihmova monet kansat ja hänen tähtensä kuninkaat sulkevat suunsa. Sillä mitä heille ei ole koskaan kerrottu, sen he saavat nähdä, mitä he eivät ole kuulleet, sen he saavat tajuta.',
    },
    53: {
        1: 'Kuka uskoo saarnamme, kenelle Herran käsivarsi ilmoitetaan?',
        2: 'Hän kasvoi Herran edessä kuin vesa, kuin juuri kuivasta maasta. Hänellä ei ollut muotoa eikä kauneutta. Me näimme hänet, mutta hänellä ei ollut sellaista muotoa, johon olisimme mieltyneet.',
        3: 'Hän oli ylenkatsottu, ihmisten hylkäämä, kipujen mies ja sairauden tuttava, jota näkemästä kaikki kasvonsa peittivät, halveksittu, jota emme pitäneet minään.',
        4: 'Mutta, totisesti, meidän sairautemme hän kantoi, meidän kipumme hän sälytti päälleen. Me pidimme häntä rangaistuna, Jumalan lyömänä ja vaivaamana,',
        5: 'mutta hänet on haavoitettu meidän rikostemme tähden, runneltu meidän pahojen tekojemme tähden. Rangaistus oli hänen päällään, että meillä rauha olisi, ja hänen haavojensa kautta me olemme parannetut.',
        6: 'Me vaelsimme kaikki eksyksissä kuin lampaat, kukin meistä poikkesi omalle tielleen. Mutta Herra heitti hänen päälleen meidän kaikkien syntivelat.',
        7: 'Häntä piinattiin, ja hän alistui siihen eikä suutaan avannut. Kuin karitsa, joka viedään teuraaksi, kuin lammas, joka on ääneti keritsijöidensä edessä, hän ei suutaan avannut.',
        8: 'Ahdistettuna ja tuomittuna hänet otettiin pois, mutta kuka ajatteli hänen sukukuntaansa? Sillä hänet temmattiin pois elävien maasta. Kansani rikoksen tähden hän kärsi.',
        9: 'Hänelle annettiin hauta jumalattomien kanssa, mutta rikkaan luo hän tuli kuoltuaan, sillä hän ei ollut vääryyttä tehnyt eikä petosta ollut ollut hänen suussaan.',
        10: 'Mutta Herra näki hyväksi runnella häntä, lyödä häntä sairaudella. Jos sinä panet hänen sielunsa syntiuhriksi, hän saa nähdä jälkeläisiä ja elää kauan, ja Herran tahto toteutuu hänen kauttaan.',
        11: 'Sielunsa vaivan tähden hän saa nähdä sen ja tulee ravituksi. Tuntemuksensa kautta hän, vanhurskas palvelijani, vanhurskauttaa monet sälyttämällä päälleen heidän pahat tekonsa.',
        12: 'Sen tähden jaan hänelle suuren määrän saalista, ja hän jakaa saaliin väkevien kanssa. Sillä hän antoi sielunsa alttiiksi kuolemaan, ja hänet luettiin rikollisten joukkoon, hän kantoi monien synnit, ja hän rukoili rikollisten puolesta.',
    },
    54: {
        1: 'Riemuitse, sinä hedelmätön, joka et ole synnyttänyt, huuda ilosta ja puhkea riemuun, sinä, joka et ole ollut synnytyskivuissa. Sillä hylätyllä on lapsia enemmän kuin aviovaimolla, sanoo Herra.',
        2: 'Tee avaraksi telttasi sija, levennettäköön majojesi seinäkangas. Älä säästele! Pidennä telttaköytesi ja vahvista vaarnasi.',
        3: 'Sillä olet leviävä oikealle ja vasemmalle, jälkeläisesi ottavat omikseen kansat ja tekevät autiot kaupungit asutuiksi.',
        4: 'Älä pelkää, sillä et joudu häpeään. Älä häpeile, sillä et pety. Nuoruutesi häpeän sinä unohdat etkä enää muista leskeytesi pilkkaa.',
        5: 'Sillä se, joka sinut teki, on aviomiehesi. Herra Sebaot on hänen nimensä. Lunastajasi on Israelin Pyhä, hän, jota kutsutaan kaiken maan Jumalaksi.',
        6: 'Sillä kuin hylätyn, syvästi murheellisen vaimon Herra on sinut kutsunut – nuoruuden vaimon, joka on ollut halveksittu, sanoo Jumalasi.',
        7: 'Vähäksi silmänräpäykseksi minä hylkäsin sinut, mutta kokoan sinut jälleen suurella laupeudella.',
        8: 'Ylitsevuotavassa vihassani peitin sinulta kasvoni silmänräpäykseksi, mutta armahdan sinut iankaikkisella armolla, sanoo Herra, lunastajasi.',
        9: 'Sillä tämä on minulle, niin kuin olivat Nooan vedet: niin kuin minä vannoin, etteivät Nooan vedet enää tulvi yli maan, niin vannon, etten enää vihastu sinuun enkä sinua nuhtele.',
        10: 'Sillä vuoret väistykööt ja kukkulat horjukoot, mutta minun armoni ei sinusta väisty eikä rauhanliittoni horju, sanoo Herra, armahtajasi.',
        11: 'Sinä kurja, myrskyn raastama, sinä lohduton! Katso, minä muuraan kivesi kiiltokivestä, teen perustuksesi safiireista,',
        12: 'teen harjasi rubiineista ja porttisi kristalleista ja koko ympärysmuurisi jalokivistä.',
        13: 'Lapsesi ovat kaikki Herran opetuslapsia, ja suuri rauha lapsillasi on oleva.',
        14: 'Sinut vahvistetaan vanhurskaudella. Sinä olet oleva kaukana väkivallasta, sillä sinulla ei ole syytä pelkoon, ja sinä olet kaukana hävityksestä, sillä se ei sinua lähesty.',
        15: 'Jos kimppuusi käydään, se ei ole minusta. Se, joka kimppuusi käy, kaatuu eteesi.',
        16: 'Katso, minä olen luonut sepän, joka lietsoo hiilivalkeaa ja valmistaa aseen käyttöön. Mutta minä olen myös luonut tuhoojan hävittämään sen.',
        17: 'Jokainen ase, joka valmistetaan sinun varallesi, on oleva tehoton; ja jokaisen kielen, joka nousee käymään oikeutta kanssasi, sinä osoitat vääräksi. Tämä on Herran palvelijoiden perintöosa, tämä heidän vanhurskautensa, minulta saatu, sanoo Herra.',
    },
    55: {
        1: 'Kuulkaa, kaikki te, joilla on jano, tulkaa veden ääreen. Tekin, joilla ei ole rahaa, tulkaa, ostakaa ja syökää; tulkaa, ostakaa ilman rahaa, ilman hintaa viiniä ja maitoa.',
        2: 'Miksi annatte rahan siitä, mikä ei ole leipää, ja työnne ansion siitä, mikä ei ravitse? Kuulkaa minua, niin tulette syömään hyvää, ja sielunne virkistyy yltäkylläisyyden ääressä.',
        3: 'Kallistakaa korvanne ja tulkaa luokseni. Kuulkaa, niin sielunne elää. Teen kanssanne iankaikkisen liiton, annan lujat Daavidin armot.',
        4: 'Katso, hänet minä asetin kansoille todistajaksi, kansojen ruhtinaaksi ja käskijäksi.',
        5: 'Katso, olet kutsuva pakanoita, joita et tunne, ja pakanat, jotka eivät sinua tunne, rientävät luoksesi Herran, Jumalasi, tähden, Israelin Pyhän tähden, sillä hän kirkastaa sinut.',
        6: 'Etsikää Herraa silloin, kun hänet löytää voidaan. Huutakaa häntä avuksi, kun hän on läsnä.',
        7: 'Jumalaton hylätköön tiensä ja väärintekijä ajatuksensa ja palatkoon Herran luo, niin hän armahtaa häntä, ja Jumalamme luo, sillä hänellä on paljon anteeksiantamusta.',
        8: 'Sillä minun ajatukseni eivät ole teidän ajatuksianne, eivätkä teidän tienne ole minun teitäni, sanoo Herra.',
        9: 'Vaan niin paljon korkeampi kuin taivas on maata, ovat minun tieni korkeammat teidän teitänne ja minun ajatukseni teidän ajatuksianne.',
        10: 'Sillä niin kuin sade ja lumi, joka taivaasta tulee, ei sinne palaa, vaan kostuttaa maan, tekee sen hedelmälliseksi ja kasvavaksi, antaa kylväjälle siemenen ja syöjälle leivän,',
        11: 'niin on myös sanani, joka suustani lähtee. Se ei palaa tyhjänä luokseni, vaan tekee sen, mikä on minulle otollista, ja saa menestymään sen, mitä varten sen lähetin.',
        12: 'Sillä iloiten te lähdette, ja rauhassa teitä saatetaan. Vuoret ja kukkulat puhkeavat riemuun edessänne, ja kaikki kedon puut taputtavat käsiään.',
        13: 'Orjantappuran sijaan kasvaa sypressi, nokkosen sijaan kasvaa myrtti. Se tulee Herran kunniaksi, iankaikkiseksi merkiksi, joka ei häviä.',
    },
    56: {
        1: 'Näin sanoo Herra: Noudattakaa oikeutta ja tehkää vanhurskaus, sillä autuuteni on lähellä ja vanhurskauteni ilmestyy.',
        2: 'Autuas se ihminen, joka tämän tekee, se ihmislapsi, joka tässä pysyy, joka pitää sapatin eikä sitä riko, joka varoo kätensä tekemästä mitään pahaa!',
        3: 'Älköön muukalainen, joka on liittynyt Herraan, sanoko: " Herra on erottanut minut kokonaan kansastaan", älköönkä kuohittu sanoko: "Minä olen kuiva puu."',
        4: 'Sillä näin sanoo Herra: Kuohituille, jotka pitävät sapattini ja valitsevat sen, mikä on minulle otollista, ja pysyvät liitossani,',
        5: 'heille annan huoneessani ja muurieni sisällä muistomerkin ja nimen, joka on poikia ja tyttäriä parempi. Annan heille iankaikkisen nimen, joka ei häviä.',
        6: 'Silloin muukalaiset, jotka ovat liittyneet Herraan, palvellakseen häntä, rakastaakseen Herran nimeä ja ollakseen hänen palvelijoitaan, kaikki ne, jotka pitävät sapatin eivätkä sitä riko ja pysyvät liitossani,',
        7: 'tuon pyhälle vuorelleni ja ilahdutan heitä rukoushuoneessani, ja heidän polttouhrinsa ja teurasuhrinsa ovat otollisia alttarillani, sillä huoneeni nimenä on oleva kaikkien kansojen rukoushuone.',
        8: 'Herra, Herra sanoo, hän, joka kokoaa Israelin karkotetut: Kokoan vielä muitakin sinne koottujen lisäksi.',
        9: 'Kaikki kedon eläimet, tulkaa syömään, te metsän eläimet kaikki.',
        10: 'Israelin vartijat ovat kaikki sokeita, he eivät käsitä mitään. He ovat kaikki mykkiä koiria, jotka eivät osaa haukkua. He näkevät unta, makailevat ja nukkuvat mielellään.',
        11: 'Näillä koirilla on kauhea nälkä, mikään ei niitä täytä. Ja tällaisia ovat paimenet! He eivät ymmärrä mitään. He ovat kaikki kääntyneet omille teilleen ja etsivät kukin omaa voittoaan, kaikki tyynni.',
        12: '"Tulkaa, noudan viiniä, juokaamme väkijuomaa. Olkoon huomispäivä kuin tämä ja sitäkin vielä suurempi."',
    },
    57: {
        1: 'Vanhurskas tuhoutuu, eikä kukaan pane sitä sydämelleen. Armoon turvaavat otetaan pois kenenkään siitä välittämättä, sillä vanhurskas otetaan pois pahuutta näkemästä.',
        2: 'Hän menee rauhaan. Ne, jotka vakaasti vaeltavat, saavat levätä vuoteillaan.',
        3: 'Mutta tulkaa tänne, te ennustajien lapset, te avionrikkojamiehen ja porttovaimon siemen.',
        4: 'Kenen kustannuksella te iloanne pidätte? Kenelle suuta auotte ja kielenne pitkälle pistätte? Ettekö te ole rikoksen lapsia ja valheen siementä?',
        5: 'Te, jotka hehkutte himosta tammien varjossa, jokaisen vihreän puun alla, te, jotka teurastatte lapsia laaksoissa ja kallionrotkoissa!',
        6: 'Laakson sileät paadet ovat osasi, siinä on arpaosasi. Niillehän olet juomauhrit vuodattanut ja ruokauhrit uhrannut. Siihenkö olisin tyytyväinen!',
        7: 'Korkealle ja valtavalle vuorelle valmistit vuoteesi. Sinne nousit myös uhraamaan teurasuhria.',
        8: 'Oven ja pihtipielen taakse panit omat merkkisi. Sillä minusta luopuen sinä paljastit itsesi ja nousit vuoteellesi, teit sen tilavaksi. Sinä sovit kaupoista heidän kanssaan, makasit heidän kanssaan mielelläsi ja näit heidän häpynsä.',
        9: 'Kuljit kuninkaan luo öljyinesi, runsaine voiteinesi. Lähetit sanansaattajasi kauas, laskeuduit alas hautaan asti.',
        10: 'Väsyit matkasi pituudesta, et kuitenkaan sanonut: "Turhaa!" Koska sait elpynyttä voimaa, et käynyt heikoksi.',
        11: 'Ketä arkailit ja pelkäsit, koska olit vilpillinen etkä muistanut minua etkä minusta välittänyt? Eikö niin: minä olen ollut vaiti aina ikiajoista asti, ja niin sinä et minua pelkää?',
        12: 'Minä ilmoitan, mitä ovat vanhurskautesi ja tekosi. Ne eivät auta sinua.',
        13: 'Kun huudat, auttakoon sinua jumaliesi joukko! Tuuli vie ne pois kaikki, henkäys ottaa ne pois. Mutta joka minuun turvaa, se perii maan ja ottaa omakseen pyhän vuoreni.',
        14: 'Hän sanoo: Tehkää, tehkää tie, tasoittakaa tie, poistakaa kompastuskivet kansani tieltä.',
        15: 'Sillä näin sanoo Korkea ja Ylhäinen, jonka asumus on iankaikkinen ja jonka nimi on Pyhä, joka asun korkeudessa ja pyhyydessä ja niiden luona, joilla on särjetty ja nöyrä henki, että virvoittaisin nöyryytettyjen hengen ja tekisin eläviksi särjettyjen sydämet.',
        16: 'Sillä en riitele loputtomiin enkä vihastu ainiaaksi. Muuten henki nääntyisi kasvojeni edessä, ne sielut, jotka olen tehnyt.',
        17: 'Hänen ahneutensa synnin tähden vihastuin, löin häntä, kätkin itseni ja olin vihainen. Mutta hän luopui minusta ja kulki oman sydämensä tietä.',
        18: 'Olen nähnyt hänen tiensä, mutta parannan hänet ja johdatan häntä ja annan jälleen lohdutuksen hänelle ja häntä sureville.',
        19: 'Luon huulten hedelmän, rauhan, rauhan kaukaisille ja läheisille, sanoo Herra, ja parannan hänet.',
        20: 'Mutta jumalattomat ovat kuin kuohuva meri, joka ei voi tyyntyä ja jonka aallot kuohuttavat liejua ja mutaa.',
        21: 'Jumalattomilla ei ole rauhaa, sanoo Jumalani.',
    },
    58: {
        1: 'Huuda täyttä kurkkua, älä säästä, korota äänesi kuin torvi, ilmoita kansalleni heidän rikoksensa ja Jaakobin huoneelle heidän syntinsä.',
        2: 'Minua he muka etsivät joka päivä ja haluavat tietoa teistäni niin kuin kansa, joka on tehnyt vanhurskauden eikä ole hylännyt Jumalansa oikeutta. He vaativat minulta vanhurskaita tuomioita ja haluavat, että Jumala heitä lähestyisi:',
        3: '"Miksi paastoamme, kun et sitä näe, ja kuritamme itseämme, kun et sitä huomaa?" Katso, paastopäivänänne te ajatte omia asioitanne ja ahdistatte työhön kaiken työväkenne.',
        4: 'Katso, riidaksi ja toraksi te paastoatte lyödäksenne jumalattomalla nyrkillä. Te ette nyt paastoa niin, että teidän ääntänne kuultaisiin korkeudessa.',
        5: 'Tällainenko on se paasto, johon miellyn, se päivä, jona ihminen kurittaa itseään? Jos kallistaa päänsä kuin kaisla ja makaa säkissä ja tuhkassa, sitäkö sanot paastoksi ja päiväksi, joka on otollinen Herralle?',
        6: 'Eikö tämä ole paasto, johon miellyn: että avaatte vääryyden siteet, irrotatte ikeen nuorat, ja päästätte sorretut vapaiksi, että särjette kaikki ikeet?',
        7: 'Eikö tämä: että taitat leipäsi nälkäiselle ja viet kurjat kulkijat kotiisi, kun näet alastoman, vaatetat hänet etkä kätkeydy siltä, joka on omaa lihaasi?',
        8: 'Silloin valkeutesi puhkeaa esiin kuin aamurusko, ja haavasi kasvavat nopeasti umpeen. Vanhurskautesi käy edelläsi, ja Jumalan kunnia seuraa suojanasi.',
        9: 'Silloin rukoilet, ja Herra vastaa, huudat, ja hän sanoo: "Katso, tässä olen." Jos keskuudestasi poistat ikeen, sormella osoittelun ja vääryyden puhumisen,',
        10: 'jos avaat sielusi nälkäiselle ja ravitset vaivatun sielun, valkeus koittaa sinulle pimeydessä, ja pilkkopimeäsi on oleva kuin keskipäivä.',
        11: 'Herra johdattaa sinua alati ja ravitsee sielusi kuivissa erämaissa. Hän vahvistaa luusi, ja olet oleva kuin runsaasti kasteltu puutarha, kuin lähde, josta ei koskaan puutu vettä.',
        12: 'Jälkeläisesi jälleenrakentavat ikivanhat rauniot, kohotat perusmuurit, muinaisten polvien laskemat. Nimesi on oleva: "halkeamien umpeenmuuraaja" ja "teitten korjaaja maan asuttamiseksi".',
        13: 'Jos pidätät jalkasi sapattia rikkomasta, niin ettet toimita omia asioitasi pyhäpäivänäni, vaan kutsut sapatin ilopäiväksi, Herran pyhäpäivän kunnioitettavaksi ja kunnioitat sitä, niin ettet toimita omia toimiasi, et aja omia asioitasi etkä puhu joutavia,',
        14: 'silloin ilosi on oleva Herrassa, ja vien sinut maan kukkuloiden yli ja annan sinun nauttia isäsi Jaakobin perintöosaa. Sillä Herran suu on puhunut.',
    },
    59: {
        1: 'Katso, Herran käsi ei ole liian lyhyt auttamaan, eikä hänen korvansa kuuro kuulemaan:',
        2: 'vaan teidän pahat tekonne erottavat teidät Jumalastanne, ja syntinne peittävät teiltä hänen kasvonsa, ettei hän kuule.',
        3: 'Sillä kätenne ovat tahratut vereen ja sormenne vääryyteen, huulenne puhuvat valhetta ja kielenne miettii petosta.',
        4: 'Kukaan ei saarnaa vanhurskaasti eikä tuomitse rehellisesti. He turvautuvat tyhjään ja puhuvat vilppiä, kantavat sisällään tuhoa ja synnyttävät turmion.',
        5: 'Myrkkyliskon munia he hautovat, hämähäkin verkkoja he kutovat. Se, joka niitä munia syö, kuolee, rikkipoljetusta tulee esiin kyy.',
        6: 'Heidän verkkonsa eivät kelpaa vaatteeksi, heidän tekemäänsä ei voi verhoutua. Heidän työnsä ovat vääryyden töitä, ja heidän käsissään on väkivallan tekoja.',
        7: 'Heidän jalkansa juoksevat pahuuteen ja kiiruhtavat vuodattamaan viatonta verta. Heidän ajatuksensa ovat vääryyden ajatuksia, tuho ja turmio on heidän teillään.',
        8: 'Rauhan tietä he eivät tunne eikä oikeutta ole heidän askeleissaan. Polkunsa he tekevät mutkaisiksi. Kukaan niistä, joka niitä kulkee, ei tunne rauhaa.',
        9: 'Sen tähden oikeus on meistä kaukana eikä vanhurskaus saavuta meitä. Odotamme valoa, mutta katso, on pimeä, aamunkoittoa, mutta vaellamme yössä.',
        10: 'Haparoimme seiniä pitkin kuin sokeat, haparoimme kuin silmiä vailla olevat. Kompastelemme sydänpäivällä kuin hämärässä, olemme terveiden keskellä kuin kuolleet.',
        11: 'Murisemme kaikki kuin karhut ja kujerramme kuin kyyhkyset. Odotamme oikeutta, mutta sitä ei tule, pelastusta, mutta se on kaukana meistä.',
        12: 'Sillä rikoksemme ovat monilukuiset sinun edessäsi, ja syntimme todistavat meitä vastaan. Sillä rikoksemme seuraavat meitä ja pahat tekomme tunnemme:',
        13: 'olemme luopuneet Herrasta ja kieltäneet hänet, vetäytyneet pois Jumalaamme seuraamasta, puhuneet sortoa ja kapinaa, kantaneet sitä sisällämme ja purkaneet sisimmästämme valheen sanoja.',
        14: 'Oikeus työnnetään takaperin, ja vanhurskaus seisoo kaukana, sillä totuus kompastelee torilla, suoruus ei voi tulla sisälle.',
        15: 'Totuus oli kadonnut, ja joka pahasta luopui, se ryöstettiin paljaaksi. Herra näki sen, ja sen, ettei ollut oikeutta. Se oli hänen silmissään paha.',
        16: 'Hän näki, ettei ollut yhtään miestä, ja hän ihmetteli, ettei kukaan astunut väliin. Silloin hänen oma käsivartensa auttoi häntä, ja hänen vanhurskautensa tuki häntä.',
        17: 'Hän puki ylleen vanhurskauden kuin rintahaarniskan ja pani pelastuksen kypärän päähänsä. Hän puki koston vaatteet puvukseen ja verhoutui kiivauteen kuin viittaan.',
        18: 'Tekojen mukaan hän maksaa palkan: vihan vastustajilleen, koston vihollisilleen. Hän kostaa merensaarille.',
        19: 'Silloin he pelkäävät päivän laskun mailla Herran nimeä ja päivän koittamilla hänen kunniaansa. Sillä se tulee kuin padottu virta, jota Herran Henki ajaa eteenpäin.',
        20: 'Mutta Siionille tulee Lunastaja, niille Jaakobissa, jotka synnistä kääntyvät, sanoo Herra.',
        21: 'Mutta minä teen tämän liittoni heidän kanssaan, sanoo Herra: minun Henkeni, joka on päälläsi, ja sanani, jonka panen suuhusi, eivät väisty suustasi, eivät lastesi suusta eivätkä lastesi lasten suusta, sanoo Herra, nyt ja iankaikkisesti.',
    },
    60: {
        1: 'Nouse, ole kirkas, sillä valkeutesi tulee, ja Herran kunnia koittaa ylitsesi.',
        2: 'Sillä katso, pimeys peittää maan ja synkeys kansat, mutta ylitsesi koittaa Herra, ja ylläsi näkyy hänen kunniansa.',
        3: 'Kansat vaeltavat valkeuttasi kohden, kuninkaat aamunkoittosi kirkkautta kohti.',
        4: 'Nosta silmäsi, katso ympärillesi: kaikki nämä ovat kokoontuneet ja tulevat luoksesi. Poikasi tulevat kaukaa ja tyttäriäsi kainalossa kannetaan.',
        5: 'Silloin sen näet, ja loistat ilosta, sydämesi sykkii ja avartuu, kun meren aarteet kääntyvät luoksesi ja kansojen rikkaudet tulevat sinulle.',
        6: 'Kamelien paljous peittää sinut, Midianin ja Eefan varsat. Ne kaikki tulevat Sabasta, kantavat kultaa ja suitsutusta ja kuuluttavat Herran ylistystä.',
        7: 'Kaikki Keedarin laumat kokoontuvat luoksesi, Nebajotin pässit palvelevat sinua. Minulle otollisina ne nousevat alttarilleni, ja kirkastan kirkkauteni huoneen.',
        8: 'Keitä ovat nuo, jotka lentävät kuin pilvet ja lakkoihinsa kuin kyyhkyt?',
        9: 'Merensaaret odottavat minua, ja etumaisina tulevat Tarsiin laivat tuodakseen lapsesi kaukaa. Heillä on mukanaan hopeansa ja kultansa Herran, sinun Jumalasi, nimelle, Israelin Pyhälle, sillä hän kirkastaa sinut.',
        10: 'Muukalaiset rakentavat muurisi, ja heidän kuninkaansa palvelevat sinua, sillä vihassani löin sinua, mutta mielisuosiossani sinut armahdan.',
        11: 'Porttisi pidetään aina auki. Niitä ei suljeta päivällä eikä yöllä, jotta kansojen rikkaudet tuotaisiin ja heidän kuninkaansa saatettaisiin luoksesi.',
        12: 'Sillä se kansa tai valtakunta, joka ei sinua palvele, hukkuu, ja ne kansat hävitetään perin juurin.',
        13: 'Libanonin kunnia tulee luoksesi, sypressit, jalavat sekä hopeakuuset kaunistavat pyhäkköni paikkaa, ja saatan jalkojeni sijan kunniaan.',
        14: 'Kumarassa kulkien tulevat luoksesi sortajiesi pojat, ja kaikki pilkkaajasi heittäytyvät jalkojesi juureen. He nimittävät sinua " Herran kaupungiksi" ja "Israelin Pyhän Siioniksi."',
        15: 'Sen sijaan, että olet ollut hylätty ja vihattu, niin ettei ollut kauttasi kulkijaa, teen sinut korkeaksi iankaikkisesti, iloksi polvesta polveen.',
        16: 'Imet kansojen maidon, imet kuninkaiden rintoja, tunnet, että minä, Herra, olen auttajasi, että Jaakobin Väkevä on lunastajasi.',
        17: 'Tuon vasken sijaan kultaa, ja raudan sijaan tuon hopeaa, puun sijaan vaskea ja kiven sijaan rautaa. Asetan sinulle paimeneksi rauhan ja käskijäksi vanhurskauden.',
        18: 'Enää ei kuulu väkivaltaa maastasi, ei tuhoa eikä turmiota rajojesi sisältä, ja kutsut pelastuksen muuriksesi ja kiitoksen portiksesi.',
        19: 'Aurinko ei ole enää valonasi päivällä, eikä valaise sinua kuun paiste, vaan Herra on iankaikkinen valkeutesi, ja Jumalasi kirkkautesi.',
        20: 'Aurinkosi ei enää laske, eikä kuusi menetä valoaan, sillä Herra on iankaikkinen valkeutesi, ja päättyneet ovat murheesi päivät.',
        21: 'Kansassasi ovat kaikki vanhurskaita. He saavat periä maan iankaikkisesti, he, istutukseni vesa, kätteni teko, kirkkauteni ilmoitukseksi.',
        22: 'Pienimmästä kasvaa heimo, vähäisimmästä väkevä kansa. Minä, Herra, sen aikanaan nopeasti täytän.',
    },
    61: {
        1: 'Herran, Herran Henki on päälläni, sillä hän on voidellut minut julistamaan ilosanomaa nöyrille, lähettänyt minut sitomaan särjettyjä sydämiä, julistamaan vangituille vapautusta ja kahlituille kirvoitusta,',
        2: 'julistamaan Herran otollista vuotta ja Jumalamme kostonpäivää, lohduttamaan kaikkia murheellisia,',
        3: 'panemaan Siionin murheellisten päähän – antamaan heille – juhlapäähineen tuhkan sijaan, iloöljyä murheen sijaan, ylistyksen viitan masentuneen hengen sijaan, ja heidän nimensä on oleva "vanhurskauden tammet" ja " Herran istutus" ilmoittamassa hänen kirkkauttaan.',
        4: 'He jälleenrakentavat ikivanhat rauniot, kohottavat ennalleen esi-isien autiot paikat ja uudistavat rauniokaupungit, jotka ovat olleet autioita polvesta polveen.',
        5: 'Vieraat ovat laumojenne paimenina, muukalaiset peltomiehinänne ja viinitarhureinanne.',
        6: 'Mutta teitä kutsutaan Herran papeiksi, sanotaan Jumalamme palvelijoiksi. Te nautitte kansojen rikkauksista ja peritte heidän kunniansa.',
        7: 'Häpeänne hyvitetään teille kaksin kerroin, ja pilkatut saavat riemuita osastaan. He saavat kaksinkertaisen perinnön maassaan. Heillä on oleva iankaikkinen ilo.',
        8: 'Sillä minä, Herra, rakastan oikeutta, vihaan vääryyttä ja ryöstöä, annan heille palkan uskollisesti ja teen heidän kanssaan iankaikkisen liiton.',
        9: 'Heidän siemenensä tulee tunnetuksi kansojen keskuudessa ja heidän jälkeläisensä kansakuntien keskellä. Kaikki, jotka näkevät heidät, tuntevat heidät Herran siunaamaksi siemeneksi.',
        10: 'Iloitsen suuresti Herrassa, sieluni riemuitsee Jumalassani, sillä hän pukee päälleni autuuden vaatteet ja verhoaa minut vanhurskauden viittaan, yljän kaltaiseksi, joka kantaa turbaania kuin pappi, ja morsiamen kaltaiseksi, joka on kaunistettu koruillaan.',
        11: 'Sillä niin kuin maa tuottaa kasvunsa ja niin kuin kasvitarha saa siemenkylvönsä versomaan, niin saattaa Herra, Herra versomaan vanhurskauden ja kiitoksen kaikkien kansojen nähden.',
    },
    62: {
        1: 'Siionin tähden en voi vaieta, ja Jerusalemin tähden en saa lepoa, ennen kuin sen vanhurskaus nousee kuin aamunkoi ja sen autuus kuin palava tulisoihtu.',
        2: 'Kansat näkevät vanhurskautesi, kaikki kuninkaat kunniasi ja sinulle annetaan uusi nimi, jonka Herran suu säätää.',
        3: 'Tulet kauniiksi kruunuksi Herran kädessä ja kuninkaalliseksi päähineeksi Jumalasi kädessä.',
        4: 'Sinua ei enää sanota "hylätyksi", eikä maatasi enää sanota "autioksi"; vaan sinua kutsutaan "minun rakkaakseni" ja maatasi "aviovaimoksi", sillä Herra rakastaa sinua, ja maasi otetaan avioon.',
        5: 'Sillä niin kuin nuori mies ottaa neitsyen aviovaimoksi, niin lapsesi ottavat sinut omakseen, ja niin kuin ylkä iloitsee morsiamesta, niin Jumalasi iloitsee sinusta.',
        6: 'Muureillesi, Jerusalem, asetan vartijat. Älkööt he koskaan vaietko, ei päivällä eikä yöllä. Te, jotka ylistätte Herraa, älkää suoko itsellenne lepoa.',
        7: 'Älkää antako hänelle lepoa, ennen kuin hän on asettanut ennalleen Jerusalemin ja tehnyt sen ylistykseksi maassa.',
        8: 'Herra on vannonut oikean kätensä ja voimansa käsivarren kautta: Totisesti, enää en anna jyviäsi vihollistesi ruuaksi, eivätkä muukalaiset enää juo viiniäsi, josta sinä olet nähnyt vaivan.',
        9: 'Vaan ne, jotka viljan kokoavat, syövät sen ja ylistävät Herraa, ja ne, jotka viinin korjaavat, juovat sen pyhissä esikartanoissani.',
        10: 'Käykää, käykää ulos porteista, tasoittakaa kansalle tie, tehkää, tehkää valtatie, raivatkaa kivet pois, kohottakaa kansoille lippu.',
        11: 'Katso, Herra on kuuluttanut maan ääriin asti: Sanokaa tytär Siionille: Katso, pelastuksesi tulee. Katso, hänen palkkansa on hänen mukanaan ja hänen työnsä ansio käy hänen edellään.',
        12: 'Heitä kutsutaan "pyhäksi kansaksi", " Herran lunastetuiksi"; ja sinua kutsutaan "halutuksi", "kaupungiksi, joka ei ole hylätty."',
    },
    63: {
        1: 'Kuka tuolla tulee Edomista, tulipunaisissa vaatteissa Bosrasta, tuo puvultaan komea, joka uljaana astelee suuressa voimassaan? "Minä, joka puhun vanhurskautta, joka olen voimallinen auttamaan."',
        2: 'Miksi on punaa puvussasi, miksi vaatteesi ovat kuin viinikuurnan polkijan?',
        3: '"Kuurnan poljin, yksinäni, kansakunnista ketään ei ollut kanssani. Poljin heidät vihassani, tallasin heidät kiivaudessani, ja niin roiskui heidän vertaan vaatteilleni, ja tahrin koko pukuni.',
        4: 'Sillä koston päivä oli mielessäni ja lunastettujeni vuosi oli tullut.',
        5: 'Katselin, mutta ei ollut auttajaa, ja ihmettelin, kun kukaan ei tullut tueksi. Silloin oma käsivarteni auttoi minua, ja vihani tuki minua.',
        6: 'Tallasin kansat vihassani, juovutin heidät kiivaudellani ja vuodatin maahan heidän verensä."',
        7: 'Herran armotöitä julistan, Herran ylistettäviä tekoja, kaikkea, mitä Herra on meille tehnyt, suurta hyvyyttä Israelin heimoa kohtaan, mitä hän on heille osoittanut laupeudessaan ja suuressa armossaan.',
        8: 'Hän sanoi: "Ovathan he kansani ja ovathan he lapsia, joissa ei ole vilppiä", ja hän tuli heille vapahtajaksi.',
        9: 'Kaikissa heidän ahdistuksissaan hänelläkin oli ahdistus, mutta hänen kasvojensa Enkeli vapahti heidät. Rakkaudessaan ja säälissään hän lunasti heidät, nosti heitä ja kantoi heitä kaikkina muinaisina päivinä.',
        10: 'Mutta he niskoittelivat ja saattoivat murheelliseksi hänen Pyhän Henkensä; ja hän muuttui heidän vihollisekseen. Hän itse soti heitä vastaan.',
        11: 'Hänen kansansa muisti entisiä päiviä, muisti Moosesta: Missä on hän, joka toi heidät ylös merestä, heidät sekä hänen laumansa paimenen? Missä on hän, joka pani tämän sydämeen Pyhän Henkensä,',
        12: 'hän, joka antoi kunniansa käsivarren kulkea Mooseksen oikealla puolella, joka halkaisi vedet heidän edestään tehdäkseen itselleen iankaikkisen nimen,',
        13: 'hän, joka kuljetti heitä syvyyksissä kuin hevosia erämaassa, eivätkä he kompastelleet?',
        14: 'Niin kuin karja astuu alas laaksoon, niin Herran Henki vei heidät lepoon. Niin olet kansaasi johdattanut tehdäksesi itsellesi kunniallisen nimen.',
        15: 'Katsele taivaasta, katso pyhyytesi ja kirkkautesi asunnosta. Missä ovat kiivautesi ja voimalliset tekosi? Sydämesi sääli ja armahtavaisuutesi ovat sulkeutuneet minulta.',
        16: 'Sinähän olet isämme, sillä Aabraham ei meistä tiedä eikä Israel meitä tunne: sinä, Herra, olet isämme; "Lunastajamme" on ikiajoista nimesi',
        17: 'Minkä tähden olet sallinut meidän eksyä pois teiltäsi, Herra, ja olet antanut sydämemme paatua, niin ettemme sinua pelkää? Palaa takaisin palvelijoidesi tähden, perintöosasi sukukuntien tähden.',
        18: 'Vähän aikaa vain pyhä kansasi omisti perintönsä. Ahdistajamme ovat tallanneet pyhäkköäsi.',
        19: 'Olemme kuin ne, joita et ole ikinä hallinnut, olemme, kuin meitä ei olisi otettu nimiisi.',
    },
    64: {
        1: 'Oi, jospa sinä halkaisisit taivaat ja astuisit alas, niin että vuoret järkkyisivät edessäsi, niin kuin risut leimahtavat tuleen, niin kuin vesi kiehuu tulella, että tekisit nimesi tunnetuksi vastustajillesi ja kansat vapisisivat kasvojesi edessä,',
        2: 'kun teet pelottavia tekoja, joita emme voineet odottaa! Oi, jospa astuisit alas, niin että vuoret järkkyisivät edessäsi!',
        3: 'Ei ole ikiajoista kuultu, ei ole korviin tullut, ei ole silmä nähnyt muuta Jumalaa, paitsi sinut, joka tekisi sellaisia häntä odottavalle.',
        4: 'Sinä käyt niitä kohden, jotka tekevät ilolla vanhurskautta ja jotka teilläsi sinua muistavat. Katso, sinä vihastuit, ja me jouduimme synnin alaisiksi. Niin on ollut ikiajoista asti – saammeko avun?',
        5: 'Kaikki me olemme kuin saastaiset, ja kuin tahrattu vaate on kaikki vanhurskautemme. Kaikki olemme lakastuneita kuin lehdet, ja pahat tekomme heittelevät meitä kuin tuuli.',
        6: 'Ei ole ketään, joka huutaa avukseen nimeäsi, joka herää pitämään sinusta kiinni, sillä olet peittänyt kasvosi meiltä ja jättänyt meidät menehtymään syntiemme valtaan.',
        7: 'Mutta olethan sinä, Herra, Isämme; me olemme savi, ja sinä olet valajamme, kaikki me olemme kättesi tekoa.',
        8: 'Älä, Herra, vihastu aivan suuresti, äläkä ainiaan muistele pahoja tekoja. Katso ja huomaa, että me kaikki olemme sinun kansaasi.',
        9: 'Pyhät kaupunkisi ovat tulleet erämaaksi, Siion on erämaaksi tullut, Jerusalem autioksi.',
        10: 'Pyhä ja ihana temppelimme, jossa isämme sinua ylistivät, on tulella poltettu, ja rauniona on kaikki meille kallisarvoinen.',
        11: 'Vaikka nämä näin ovat, voitko, Herra, hillitä itsesi, voitko olla vaiti ja vaivata meitä niin kovasti?',
    },
    65: {
        1: 'Olen niiden etsittävänä, jotka eivät minua kysyneet, niiden löydettävänä, jotka eivät minua etsineet. Olen sanonut kansalle, jota ei ole otettu minun nimiini: Katso, tässä olen, katso, tässä olen!',
        2: 'Koko päivän olen ojentanut käsiäni uppiniskaista kansaa kohden, joka vaeltaa omien ajatustensa mukaan tietä, joka ei ole hyvä,',
        3: 'kansaa kohden, joka vihoittaa minua alinomaa, vasten kasvojani, uhraa puutarhoissa ja suitsuttaa tiilikivialttareilla.',
        4: 'He asustavat haudoissa ja yöpyvät salaisissa paikoissa. He syövät sianlihaa, ja heillä on saastaista lientä astioissaan.',
        5: 'He sanovat: "Pysy erilläsi, älä tule minua lähelle, sillä olen sinulle pyhä." Nämä ovat savu sieraimissani, tuli, joka palaa kaiken päivää.',
        6: 'Katso, se on kirjoitettuna edessäni. En ole vaiti, vaan maksan, maksan heille helmaan',
        7: 'heidän pahat tekonsa sekä teidän isienne pahat teot, sanoo Herra, niiden, jotka ovat vuorilla suitsuttaneet ja kukkuloilla minua häväisseet. Ensiksi mittaan heille palkan heidän helmaansa.',
        8: 'Näin sanoo Herra: Niin kuin sanotaan rypäleestä, jos siinä on mehua: "Älä hävitä sitä, sillä siinä on siunaus", niin teen palvelijoideni tähden, etten kaikkea hävittäisi.',
        9: 'Tuotan Jaakobista siemenen ja Juudasta vuorteni perillisen, niin valittuni saavat periä maan ja palvelijani saavat asua siinä.',
        10: 'Saaron on oleva lammasten laitumena ja Aakorin laakso karjan lepopaikkana kansallani, joka minua etsii.',
        11: 'Mutta te, jotka hylkäätte Herran ja unohdatte pyhän vuoreni, jotka valmistatte Gadille pöydän ja vuodatatte uhrijuomaa Menille –',
        12: 'teidät määrään miekan omiksi. Te kaikki kumarrutte teurastettaviksi, sen tähden ettette vastanneet, kun kutsuin, ettekä kuulleet, kun puhuin, vaan teitte sitä, mikä on pahaa silmissäni, ja valitsitte sen, mikä ei ole minulle otollista.',
        13: 'Sen tähden, näin sanoo Herra, Herra: Katso, palvelijani syövät, mutta te näette nälkää. Katso, palvelijani juovat, mutta te kärsitte janoa. Katso, palvelijani iloitsevat, mutta te joudutte häpeään.',
        14: 'Katso, palvelijani riemuitsevat sydämen onnesta, mutta te huudatte sydämen tuskasta ja voivotatte henki murtuneena.',
        15: 'Te jätätte nimenne kiroukseksi valituilleni: "Sinut surmatkoon Herra, Herra!" Mutta palvelijoilleen hän on antava toisen nimen.',
        16: 'Se, joka maassa itsensä siunaa, siunaa itsensä todellisen Jumalan nimeen, ja se, joka maassa vannoo, vannoo oikean Jumalan nimeen. Sillä entiset ahdistukset ovat unohdetut ja silmiltäni peitossa.',
        17: 'Sillä katso, luon uudet taivaat ja uuden maan. Entisiä ei enää muisteta, eivätkä ne enää astu ajatukseen.',
        18: 'Vaan saatte iloita ja riemuita iankaikkisesti siitä, mitä minä luon. Sillä katso, iloksi minä luon Jerusalemin ja riemuksi sen kansan.',
        19: 'Minä iloitsen Jerusalemista ja riemuitsen kansastani, eikä siellä enää kuulla itkun ääntä eikä valituksen ääntä.',
        20: 'Siellä ei ole enää imeväistä, joka eläisi vain muutaman päivän, ei vanhusta, joka ei täyttäisi päiviensä määrää. Sillä nuori kuolee satavuotiaana, ja satavuotiaana synnintekijä joutuu kiroukseen.',
        21: 'He rakentavat taloja ja asuvat niissä, he istuttavat viinitarhoja ja syövät niiden hedelmät.',
        22: 'He eivät rakenna muiden asua, eivät istuta muiden syödä. Sillä niin kuin puiden päivät ovat, niin ovat elinpäivät kansassani. Valittuni kuluttavat itse kättensä työn.',
        23: 'He eivät tee työtä turhaan eivätkä synnytä lapsia äkkikuoleman omiksi, sillä he ovat Herran siunattujen siemen, ja heidän vesansa ovat heidän luonaan.',
        24: 'Ennen kuin he huutavat, minä vastaan, heidän vielä puhuessaan minä kuulen.',
        25: 'Susi ja lammas käyvät yhdessä laitumella, ja leijona syö rehua kuin nauta, ja käärmeen ruokana on maan tomu. Missään pyhällä vuorellani ei tehdä pahaa eikä vahinkoa, sanoo Herra.',
    },
    66: {
        1: 'Näin sanoo Herra: Taivas on valtaistuimeni, ja maa on jalkojeni astinlauta. Mikä olisi huone, jonka te minulle rakentaisitte, mikä paikka olisi leposijani?',
        2: 'Käteni on kaikki nämä tehnyt, ja niin ovat kaikki nämä syntyneet, sanoo Herra. Mutta katson sen puoleen, joka on nöyrä, jolla on särjetty henki ja arka tunto sanani edessä.',
        3: 'Joka teurastaa härän, mutta myös tappaa miehen, joka uhraa lampaan, mutta myös taittaa koiralta niskan, joka uhraa ruokauhrin, mutta myös sian verta, joka polttaa suitsuketta, mutta myös ylistää epäjumalaa: he ovat valinneet omat tiensä. Niin kuin heidän sielunsa on mieltynyt heidän iljetyksiinsä,',
        4: 'minäkin valitsen heidän vaivaamisensa ja annan heille tulla sen, mitä he pelkäävät, koska kukaan ei vastannut, kun kutsuin, koska he eivät kuulleet, kun puhuin, vaan tekivät sitä, mikä on pahaa silmissäni, ja valitsivat sen, mikä ei ole minulle otollista.',
        5: 'Kuulkaa Herran sana, te, jotka olette aralla tunnolla hänen sanansa edessä: Teidän veljenne, jotka vihaavat teitä ja työntävät teidät luotaan nimeni tähden, sanovat: "Osoittakoon Herra kunniansa, että näemme teidän ilonne!" Mutta he joutuvat häpeään.',
        6: 'Kohiseva ääni kaupungista! Ääni temppelistä! Herran ääni: hän maksaa palkan vihollisilleen!',
        7: 'Ennen kuin Siion tuntee kipuja, hän synnyttää. Ennen kuin hänelle tulevat tuskat, hän saa poikalapsen.',
        8: 'Kuka on sellaista kuullut, kuka sellaista nähnyt? Syntyykö maa yhden päivän kivulla, tai synnytetäänkö kansa yhdellä kerralla? Siionhan tunsi kipuja ja samalla jo synnytti lapsensa.',
        9: 'Minäkö avaisin kohdun sallimatta synnyttää, sanoo Herra, tai minäkö, joka saatan synnyttämään, sulkisin kohdun?',
        10: 'Iloitkaa Jerusalemin kanssa ja riemuitkaa hänestä kaikki, jotka häntä rakastatte. Iloitsemalla iloitkaa hänen kanssaan, te, jotka olette surreet hänen tähtensä,',
        11: 'että imisitte ja tulisitte ravituiksi hänen lohdutuksensa rinnoista, että joisitte ja virkistyisitte hänen kunniansa runsaudesta.',
        12: 'Sillä näin sanoo Herra: Ohjaan hänen luokseen rauhan kuin virran ja kansojen kunnian kuin tulvivan joen. Te imette, kainalossa teitä kannetaan, ja polvilla pitäen teitä hyväillään.',
        13: 'Niin kuin mies lohduttaa äitiään, niin minä lohdutan teitä, ja Jerusalemissa te saatte lohdutuksen.',
        14: 'Te näette sen, ja teidän sydämenne iloitsee, ja teidän luunne virkistyvät kuin vihanta ruoho. Silloin Herran käsi tulee tunnetuksi hänen palvelijoissaan, mutta vihollistensa hän antaa tuntea vihansa.',
        15: 'Sillä, katso, Herra tulee tulessa, ja hänen vaununsa ovat kuin myrskytuuli. Hän antaa vihansa purkautua hehkussa ja nuhtelunsa tulenliekeissä.',
        16: 'Herra käy tuomiolle kaiken lihan kanssa tulella ja miekallaan, ja Herran surmaamia on oleva paljon.',
        17: 'Niistä, jotka pyhittäytyvät ja puhdistautuvat puutarhamenoja varten, seuraten miestä, joka on heidän keskellään ja jotka syövät sianlihaa ja muuta inhottavaa sekä hiiriä, niistä kaikista tulee loppu, sanoo Herra.',
        18: 'Minä tunnen heidän tekonsa ja ajatuksensa. Tulee aika, jolloin kokoan kaikki kansat ja kielet, ja he tulevat ja näkevät kunniani.',
        19: 'Teen tunnusteon heidän keskellään ja lähetän pakoon päässeitä heidän joukostaan pakanoiden luo Tarsiiseen, Puuliin ja Luudiin, jousimiesten luo, Tuubaliin ja Jaavaniin, kaukaisiin merensaariin, jotka eivät ole kuulleet minusta kerrottavan eivätkä nähneet kunniaani, ja he ilmoittavat kunniani pakanoiden keskuudessa.',
        20: 'He tuovat kaikki veljenne kaikista kansoista uhrilahjana Herralle hevosilla, vaunuilla, kantotuoleilla, muuleilla ja ratsukameleilla pyhälle vuorelleni Jerusalemiin, sanoo Herra, niin kuin israelilaiset tuovat ruokauhrin puhtaassa astiassa Herran temppeliin.',
        21: 'Heitäkin otan leeviläisiksi papeiksi, sanoo Herra.',
        22: 'Niin kuin uudet taivaat ja uusi maa, jotka minä teen, pysyvät kasvojeni edessä, sanoo Herra, pysyy siemenenne ja nimenne.',
        23: 'Joka kuukausi uudenkuun päivänä ja joka viikko sapattina tulee kaikki liha kumartaen rukoilemaan minua, sanoo Herra.',
        24: 'He käyvät ulos katselemaan niiden miesten ruumiita, jotka ovat luopuneet minusta. Sillä heidän matonsa ei kuole, eikä heidän tulensa sammu, ja he ovat kauhistukseksi kaikelle lihalle.',
    },
}
